UPDATE `creature_text` SET `Text` = '$n, I\'ll make sure all my friends in the Cartel know that you\'ve saved my life today.  Here - I\'m going to need to be able to travel light, so please help yourself to my cache of tailoring and leatherworking supplies!  Thanks again - see ya!', `Type` = 12, `Language` = 0, `Probability` = 0, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9346, `TextRange` = 0, `comment` = 'Knot' WHERE `CreatureID` = 14338 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'OH NOES!  Da king is dead!  Uh... hail to da new king!  Yeah!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9348, `TextRange` = 0, `comment` = 'Mizzle the Crafty to 58960' WHERE `CreatureID` = 14353 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Yar, he\'s dead all right.  That makes you da new king... well, all of you!  Gordok is yours now, boss!  You should talk to me so you can learn everything there is about being da king!  I was... is his assistant!  Yeah, that\'s why I\'m called da crafty one!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9411, `TextRange` = 0, `comment` = 'Mizzle the Crafty to 58960' WHERE `CreatureID` = 14353 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I very much doubt that he will have anything to say, stranger...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9446, `TextRange` = 0, `comment` = 'Lorekeeper Lydros' WHERE `CreatureID` = 14368 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I personally didn\'t mind him. It was the Prince who took exception to a high elf in his domain. Alas, I am not one to question the Prince. In his defense, he did not incinerate Master Winthalus immediately.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9447, `TextRange` = 0, `comment` = 'Lorekeeper Lydros' WHERE `CreatureID` = 14368 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'We most definitely do not need anymore attention drawn to us, stranger. Return to those that sent you in search of the lost master and tell them that nothing could be found. When this is done - and I will know when it is so - return and I shall reveal the secrets of the deceased.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9448, `TextRange` = 0, `comment` = 'Lorekeeper Lydros' WHERE `CreatureID` = 14368 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'NEFARIAN IS SLAIN! people of Orgrimmar, bow down before the might of $N and his allies for they have laid a blow against the Black Dragonflight that is sure to stir the Aspects from their malaise! This defeat shall surely be felt by the father of the Black Flight: Deathwing reels in pain and anguish this day!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9867, `TextRange` = 0, `comment` = 'Overlord Runthak' WHERE `CreatureID` = 14392 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Be lifted by $N accomplishment! Revel in his rallying cry!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 9868, `TextRange` = 0, `comment` = 'Overlord Runthak' WHERE `CreatureID` = 14392 AND `GroupID` = 1 AND `ID` = 0;

