UPDATE `creature_text` SET `Text` = 'Hakkar binds me no more!  Peace at last!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 8424, `BroadcastTextId` = 10451, `TextRange` = 0, `comment` = 'thekal SAY_DEATH' WHERE `CreatureID` = 14509 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Bless you, mortals, for this release...Hakkar controls me no longer!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 8423, `BroadcastTextId` = 10459, `TextRange` = 0, `comment` = 'marli SAY_DEATH' WHERE `CreatureID` = 14510 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Lord Hir\'eek, grant me wings of vengeance!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 8417, `BroadcastTextId` = 10027, `TextRange` = 0, `comment` = 'jeklik SAY_AGGRO' WHERE `CreatureID` = 14517 AND `GroupID` = 0 AND `ID` = 0;

