UPDATE `creature_text` SET `Text` = 'Hardly a fitting introduction, Spear-Wife.  Now, who is this outsider that I\'ve been hearing so much about?', `Type` = 14, `Language` = 0, `Probability` = 0, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31956, `TextRange` = 0, `comment` = 'Prince Sandoval say 1' WHERE `CreatureID` = 14688 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I will make this as easy as possible for you.  Simply come here and die.  That is all that I ask for your many trespasses.  For your sullying of this exalted place of battle.', `Type` = 14, `Language` = 0, `Probability` = 0, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31957, `TextRange` = 0, `comment` = 'Prince Sandoval say 2' WHERE `CreatureID` = 14688 AND `GroupID` = 1 AND `ID` = 0;

