UPDATE `creature_text` SET `Text` = 'By the seven Ata\'mal crystals!  Others have survived the crash!  Zhanaa, is that you?  It is so good to see you again!', `Type` = 12, `Language` = 7, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12845, `TextRange` = 0, `comment` = 'Image of Technician Dyvuun' WHERE `CreatureID` = 16550 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'And who do we have here?  No doubt th... crzzzk ...ade this communication possible?  I give you greetings fro... psshzzzk... Azure Watch.', `Type` = 12, `Language` = 7, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12752, `TextRange` = 0, `comment` = 'Image of Technician Dyvuun' WHERE `CreatureID` = 16550 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Judging by your signal, we put you... ust southeast of the larger part of the island we crashed onto.  Cross the Crystalbrook River to ge... kshhhhk zzzt. Sorry, there\'s a lot of stat...', `Type` = 12, `Language` = 7, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12753, `TextRange` = 0, `comment` = 'Image of Technician Dyvuun' WHERE `CreatureID` = 16550 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Brothers and sisters, I have been to the promised land. I have tasted in the sublime energy. I have felt bliss - bliss so engrossing and all encompassing that I was left wondering if I had stumbled upon the dreams of gods.', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 5, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12698, `TextRange` = 0, `comment` = 'Martik Tor\'seldoi' WHERE `CreatureID` = 16577 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'In paradise, you merely reach out and take from the Nether.', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12703, `TextRange` = 0, `comment` = 'Martik Tor\'seldoi' WHERE `CreatureID` = 16577 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'From the very air! Tendrils of arcane energy light up the obsidian sky as plumes of raw magic rise up from fissures in the land. Kneel and drink from the fissure as you do from a stream or well. Pluck a tendril from the heavens as if it were an apple hanging from a branch.', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 5, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12706, `TextRange` = 0, `comment` = 'Martik Tor\'seldoi' WHERE `CreatureID` = 16577 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Tell us more, Martik. What is it? What does it feel like?', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12700, `TextRange` = 0, `comment` = 'Blood Elf Pilgrim' WHERE `CreatureID` = 16578 AND `GroupID` = 0 AND `ID` = 0;

