UPDATE `creature_text` SET `Text` = 'Yer slop is ready. Come n\' get it...', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12531, `TextRange` = 0, `comment` = 'Cookie One-Eye' WHERE `CreatureID` = 16585 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'And if I hear that you palookas complained to Nazgrel again, it\'ll be one of ya\'s that I serve up next time...', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12532, `TextRange` = 0, `comment` = 'Cookie One-Eye' WHERE `CreatureID` = 16585 AND `GroupID` = 1 AND `ID` = 0;

