UPDATE `creature_text` SET `Text` = 'So there we were - me and the battalion, doing a routine recon down the bone road. We\'d sent the scout up ahead to look around in case anything dangerous come up.', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12617, `TextRange` = 0, `comment` = 'Guard Captain Cragtar - Speech Text 0' WHERE `CreatureID` = 16589 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Sure enough, scout came runnin\' back, talkin\' bout some orcs down the path. They hadn\'t seen us yet so we figured we\'d go get acquainted.', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12618, `TextRange` = 0, `comment` = 'Guard Captain Cragtar - Speech Text 1' WHERE `CreatureID` = 16589 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Big red suckers! Bigger than any orc I\'d ever seen. Muscles out to here, tusks out to here... ', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12625, `TextRange` = 0, `comment` = 'Guard Captain Cragtar - Speech Text 2' WHERE `CreatureID` = 16589 AND `GroupID` = 2 AND `ID` = 0;

