UPDATE `creature_text` SET `Text` = 'Lost some of my best soldiers that day...', `Type` = 12, `Language` = 1, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 12638, `TextRange` = 0, `comment` = 'Guard Captain Cragtar - Speech Text 7' WHERE `CreatureID` = 16589 AND `GroupID` = 7 AND `ID` = 0;

