UPDATE `creature_text` SET `Text` = 'I fear for the worst, old friend. Within the Dream we fight a new foe, born of an ancient evil. Ysera\'s noble brood has fallen victim to the old whisperings. It seems as if the Nightmare has broken through the realm and seeks a new host on Azeroth.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 10871, `TextRange` = 0, `comment` = 'Malfurion Stormrage - say Text 1' WHERE `CreatureID` = 17949 AND `GroupID` = 1 AND `ID` = 0;

