UPDATE `creature_text` SET `Text` = 'Ah, there it is. Follow me, fleshling.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17254, `TextRange` = 0, `comment` = 'Cryo-Engineer Sha heen' WHERE `CreatureID` = 19671 AND `GroupID` = 9 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'What do we have here? I thought you said the area was secure? This is now the third attack? If we make it out of here, I will definitely be deducting this from your reward. Now don\'t just stand there, destroy them so I can get to that collector.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17256, `TextRange` = 0, `comment` = 'Cryo-Engineer Sha heen' WHERE `CreatureID` = 19671 AND `GroupID` = 10 AND `ID` = 0;

