UPDATE `creature_text` SET `Text` = 'He was right, you know. I\'ll have to take that tag-line for my own… It\'s not like he\'ll have a use for it anymore!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17264, `TextRange` = 0, `comment` = 'Cryo-Engineer Sha heen' WHERE `CreatureID` = 19671 AND `GroupID` = 15 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Follow me, stranger.  This won\'t take long.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17239, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_0' WHERE `CreatureID` = 19685 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Let us go into the Lower City.  I will warn you that as one of the only safe havens in Outland, Shattrath has attracted droves of refugees from all wars, current and past.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17270, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_4' WHERE `CreatureID` = 19685 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'They were drawn to the ruins of Shattrath City where a small remnant of the draenei priesthood conducted its rites inside a ruined temple on this very spot.\n', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17271, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_6' WHERE `CreatureID` = 19685 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The priesthood, known as the Aldor, quickly regained its strength as word spread that the naaru had returned and reconstruction soon began.  The ruined temple is now used as an infirmary for injured refugees.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17272, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_7' WHERE `CreatureID` = 19685 AND `GroupID` = 7 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'It wouldn\'t be long, however, before the city came under attack once again.  This time, the attack came from Illidan\'s armies. A large regiment of blood elves had been sent by Illidan\'s ally, Kael\'thas Sunstrider, to lay waste to the city.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17245, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_8' WHERE `CreatureID` = 19685 AND `GroupID` = 8 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'As the regiment of blood elves crossed this very bridge, the Aldor\'s exarchs and vindicators lined up to defend the Terrace of Light.  But then the unexpected happened.\n', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17274, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_9' WHERE `CreatureID` = 19685 AND `GroupID` = 9 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The defection of Voren\'thal and his followers was the largest loss ever incurred by Kael\'s forces. And these weren\'t just any blood elves.  Many of the best and brightest amongst Kael\'s scholars and magisters had been swayed by Voren\'thal\'s influence.\n', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17250, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_12' WHERE `CreatureID` = 19685 AND `GroupID` = 12 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The naaru accepted the defectors, who would be known as the Scryers; their dwelling lies in the platform above.  Only those initiated with the Scryers are allowed there.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17276, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_13' WHERE `CreatureID` = 19685 AND `GroupID` = 13 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Many of the priesthood had been slain by the same magisters who now vowed to serve the naaru.  They were not happy to share the city with their former enemies.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17277, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_15' WHERE `CreatureID` = 19685 AND `GroupID` = 15 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The Aldor\'s most holy temple and its surrounding dwellings lie on the terrace above.  As a holy site, only the initiated are welcome inside.\n', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17278, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_16' WHERE `CreatureID` = 19685 AND `GroupID` = 16 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'There he continues to wage war on Illidan with the assistance of the Aldor and the Scryers.  The two factions have not given up on their old feuds, though.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17279, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_18' WHERE `CreatureID` = 19685 AND `GroupID` = 18 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Such is their animosity that they vie for the honor of being sent to assist the naaru there. Each day, that decision is made here by A\'dal.  The armies gather here to receive A\'dal\'s blessing before heading to Shadowmoon.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17280, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_19' WHERE `CreatureID` = 19685 AND `GroupID` = 19 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Khadgar should be ready to see you again.  Just remember that to serve the Sha\'tar you will most likely have to ally with the Aldor or the Scryers. And seeking the favor of one group will cause the others\' dislike.\n', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17262, `TextRange` = 0, `comment` = 'kservant SAY_KHAD_SERV_20' WHERE `CreatureID` = 19685 AND `GroupID` = 20 AND `ID` = 0;

