UPDATE `creature_text` SET `Text` = 'Nat, I\'ve heard a whopper or two in my day but that one takes the cake.\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17992, `TextRange` = 0, `comment` = 'Hal McAllister' WHERE `CreatureID` = 20342 AND `GroupID` = 2 AND `ID` = 1;

UPDATE `creature_text` SET `Text` = 'That one where thousands of people are all watching us from up in the sky...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 18060, `TextRange` = 0, `comment` = 'Nat Pagle' WHERE `CreatureID` = 20344 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'We\'re like their puppets - we dance and cry and fight and say silly things for their amusement.\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 18061, `TextRange` = 0, `comment` = 'Nat Pagle' WHERE `CreatureID` = 20344 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'And if that weren\'t crazy enough, that big demon gets killed by a bunch of little floating light things... Oh, I was also a female elf in that one... Yep...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17978, `TextRange` = 0, `comment` = 'Nat Pagle' WHERE `CreatureID` = 20344 AND `GroupID` = 10 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'This one\'s real grim... So the king\'s kid, Arthas... Well he goes out to battle evil, along with Uther... *Nat pats his brow dry*', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 17985, `TextRange` = 0, `comment` = 'Nat Pagle' WHERE `CreatureID` = 20344 AND `GroupID` = 14 AND `ID` = 0;

