UPDATE `creature_text` SET `Text` = 'What have you done to my sister, you motherless elf scum!?', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14665, `BroadcastTextId` = 25360, `TextRange` = 0, `comment` = 'thassarian SAY_THASSARIAN_2' WHERE `CreatureID` = 26170 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I would sooner slit my own throat.  You will pay for what you did to your own men, Arthas... for what you did to me!  I swear it.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14666, `BroadcastTextId` = 25366, `TextRange` = 0, `comment` = 'thassarian SAY_THASSARIAN_3' WHERE `CreatureID` = 26170 AND `GroupID` = 2 AND `ID` = 0;

