UPDATE `creature_text` SET `Text` = 'Don\'t you dare talk about my father, monster.  He was twice the man you\'ll ever be.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26113, `TextRange` = 0, `comment` = 'Sasha' WHERE `CreatureID` = 26935 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I\'d rather be dead than be one of you!  You think you\'re still human?  You\'re... animals!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26112, `TextRange` = 0, `comment` = 'Sasha' WHERE `CreatureID` = 26935 AND `GroupID` = 2 AND `ID` = 0;

