UPDATE `creature_text` SET `Text` = 'We\'ll all end up serving the Lich King, kid.  Better this way than becoming a rotten corpse.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26108, `TextRange` = 0, `comment` = 'Anatoly' WHERE `CreatureID` = 26971 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I know why you\'ve come - one of those foolish Magnataur on the plains meddled and managed to get the dragons involved.  Do you enjoy serving them like a dog?', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26544, `TextRange` = 0, `comment` = 'Dregmar Runebrand - yell' WHERE `CreatureID` = 27003 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'You seek their leader... little thing, you wage war against the clans of Grom\'thar the Thunderbringer himself.  Don\'t be so eager to rush to your death.', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26186, `TextRange` = 0, `comment` = 'Dregmar Runebrand yell' WHERE `CreatureID` = 27003 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Hah!  So be it.  Blow the horn of a magnataur leader at the ring of torches south of the Blue Dragonshrine.  Make peace with your gods... Grom\'thar will come.  ', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26187, `TextRange` = 0, `comment` = 'Dregmar Runebrand yell' WHERE `CreatureID` = 27003 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Wait... WAIT! What is it that you want to know?! I know you\'re the $c named $n.', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26481, `TextRange` = 0, `comment` = 'Torturer LeCraft' WHERE `CreatureID` = 27209 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'We know... that you don\'t... know why we\'re immune... to your so-called blight. Grand Admiral Westwind somehow gave the high abbot that prayer. I beg you... no more... please?!', `Type` = 15, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 26483, `TextRange` = 0, `comment` = 'Torturer LeCraft' WHERE `CreatureID` = 27209 AND `GroupID` = 4 AND `ID` = 0;

