UPDATE `creature_text` SET `Text` = 'Behold, Noth the Plaguebringer. Responsible for the creation of the process that distills the souls of the living and places them within the cold cage of undeath, Noth was observed to be refining this process even now. ', `Type` = 12, `Language` = 7, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 27055, `TextRange` = 0, `comment` = 'Commander Eligor Dawnbringer' WHERE `CreatureID` = 27784 AND `GroupID` = 23 AND `ID` = 0;

