UPDATE `creature_text` SET `Text` = 'I was king of this empire once, long ago. In life I stood as champion. In death I returned as conqueror. Now I protect the kingdom once more. Ironic, yes? ', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14053, `BroadcastTextId` = 0, `TextRange` = 0, `comment` = 'anub arak SAY_INTRO' WHERE `CreatureID` = 29120 AND `GroupID` = 5 AND `ID` = 0;

