UPDATE `creature_text` SET `Text` = 'So too do the Knights of the Ebon Blade. Although our kind has no place in your world, we will fight to bring an end to the Lich King. This I vow!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14710, `BroadcastTextId` = 29851, `TextRange` = 0, `comment` = 'Highlord Darion Mograine' WHERE `CreatureID` = 29173 AND `GroupID` = 67 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = '%s kneels in defeat before Tirion Fordring.', `Type` = 16, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 29759, `TextRange` = 0, `comment` = 'Highlord Darion Mograine' WHERE `CreatureID` = 29173 AND `GroupID` = 72 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Have you learned nothing, boy? You have become all that your father fought against! Like that coward, Arthas, you allowed yourself to be consumed by the darkness, the hate... feeding upon the misery of those you tortured and killed!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14586, `BroadcastTextId` = 29744, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 27 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Your master knows what lies beneath the chapel. That is why he dares not show his face! He\'s sent you and your death knights to meet their doom, Darion.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14587, `BroadcastTextId` = 29745, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 28 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Rise, Darion, and listen...\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14593, `BroadcastTextId` = 29835, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 59 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'We have all been witness to a terrible tragedy. The blood of good men has been shed upon this soil! Honorable knights, slain defending their lives -- our lives!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14594, `BroadcastTextId` = 29843, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 60 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'And while such things can never be forgotten, we must remain vigilant in our cause!\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14595, `BroadcastTextId` = 29845, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 61 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The Lich King must answer for what he has done, and must not be allowed to cause further destruction in our world.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14596, `BroadcastTextId` = 29846, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 62 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I make a promise to you now, brothers and sisters: the Lich King will be defeated! On this day, I call for a union.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14597, `BroadcastTextId` = 29847, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 63 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The Argent Dawn and the Order of the Silver Hand will come together as one! We will succeed where so many before us have failed!\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14598, `BroadcastTextId` = 29848, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 64 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'We will take the fight to Arthas, and we will tear down the walls of Icecrown!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14599, `BroadcastTextId` = 29849, `TextRange` = 0, `comment` = 'Highlord Tirion Fordring' WHERE `CreatureID` = 29175 AND `GroupID` = 65 AND `ID` = 0;

