UPDATE `creature_text` SET `Text` = 'Stripping energy from our foes, both fighting and fallen, allows us to persevere where lesser beings fall exhausted.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 29870, `TextRange` = 0, `comment` = 'Lord Thorval - (Part 4 of Speech To Deciples)' WHERE `CreatureID` = 29196 AND `GroupID` = 3 AND `ID` = 0;

