UPDATE `creature_text` SET `Text` = 'Darion Mograine, you are barely of age to hold a sword, let alone battle the undead hordes of Lordaeron! I could not bear losing you. Even the thought...\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14495, `BroadcastTextId` = 29775, `TextRange` = 0, `comment` = 'Highlord Alexandros Mograine' WHERE `CreatureID` = 29227 AND `GroupID` = 38 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'My son, there will come a day when you will command the Ashbringer and, with it, mete out justice across this land. I have no doubt that when that day finally comes, you will bring pride to our people and that Lordaeron will be a better place because of you. But, my son, that day is not today.\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14496, `BroadcastTextId` = 29777, `TextRange` = 0, `comment` = 'Highlord Alexandros Mograine' WHERE `CreatureID` = 29227 AND `GroupID` = 40 AND `ID` = 0;

