UPDATE `creature_text` SET `Text` = 'If I die, Father, I would rather it be on my feet, standing in defiance against the undead legions! If I die, let me die with you!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14706, `BroadcastTextId` = 29776, `TextRange` = 0, `comment` = 'Darion Mograine' WHERE `CreatureID` = 29228 AND `GroupID` = 39 AND `ID` = 0;

