UPDATE `creature_text` SET `Text` = 'The Lich King is unlike any foe that you have ever faced, Highlord. Though you bested him upon the holy ground of Light\'s Hope Chapel, you tread now upon his domain.\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31006, `TextRange` = 0, `comment` = 'The Ebon Watcher' WHERE `CreatureID` = 30377 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'You cannot win. Not like this...\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 274, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31007, `TextRange` = 0, `comment` = 'The Ebon Watcher' WHERE `CreatureID` = 30377 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The Lich King knows your boundaries, Highlord. He knows that you will not fire on your own men. Do you not understand? He has no boundaries. No rules to abide. \n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31015, `TextRange` = 0, `comment` = 'The Ebon Watcher' WHERE `CreatureID` = 30377 AND `GroupID` = 8 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Then you have lost, Highlord.\n', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 1, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31017, `TextRange` = 0, `comment` = 'The Ebon Watcher' WHERE `CreatureID` = 30377 AND `GroupID` = 9 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'King Jokkum, you have summoned me?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31001, `TextRange` = 0, `comment` = 'Thorim  - Conversation 18 sec in' WHERE `CreatureID` = 30390 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Jokkum, son of Arngrim, I have always regretted my actions here. In my grief, I brought great harm to those closest to me.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31003, `TextRange` = 0, `comment` = 'Thorim  - Conversation 26 sec in' WHERE `CreatureID` = 30390 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I would ask your forgiveness for the suffering I have caused you and your people.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31062, `TextRange` = 0, `comment` = 'Thorim - Conversation 32 sec in' WHERE `CreatureID` = 30390 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Krolmir... I thank you Jokkum. I hadn\'t dared hope it still existed. It shall soon see glorious battle once again!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 396, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31063, `TextRange` = 0, `comment` = 'Thorim - Conversation 68 sec in' WHERE `CreatureID` = 30390 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The disturbances in the tomb, they must be involved. Look around you, $n. Do you see them?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 25, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31156, `TextRange` = 0, `comment` = 'Chieftain Swiftspear' WHERE `CreatureID` = 30395 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'King Stormheart is putting you to the test, eh? He must see something in you to begin with or I doubt he\'d put you through such a sacred ritual.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30942, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I know you\'re new to our kind, so I\'ll catch you up a bit while we\'re on our way over.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30943, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Years back, my father and several other frostborn were returning from a trek across Dragonblight. There was a heavy blizzard... far worse than we\'ve ever seen since.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30944, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'They crossed a trail of blood-soaked snow and followed it to find a dwarf wandering and speaking in a dialect they couldn\'t make out... and not a dwarf of our kind mind you, but a mountain dwarf - something our kind had never seen before.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30945, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The dwarf seemed lost, having no memory of where he came from, or even of his own name. Not being the kind to leave a dwarven cousin to die in the snow, my father\'s party took him in and continued back towards Frosthold.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30946, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Not long later, out of nowhere, the snow burst before them and a jormungar the size of Veranus herself came down upon their party... one of them was swallowed whole before they even had time to react.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30947, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'My father thought they were all doomed... but behind him, a furious roar rumbled across the snow, and he turned to see the mountain dwarf growing in size, his skin taking on a stone-like texture, and his hands sizzling with lightning.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30948, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The dwarf barreled forward with a sound like rolling thunder and hurled a shining metal hammer, lightning coursing over its surface, directly into the jormungar\'s throat.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30949, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 7 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The jormungar collapsed instantly, its head barely still attached to its convulsing body. My father turned to the dwarf in awe and raised a fist in praise...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30950, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 8 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The stranger having no name of his own, my father deemed \"Yorg,\" a name reserved for champions of legend. Years later, he now stands before us as Yorg Stormheart, King of the Frostborn.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30952, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 9 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'King Stormheart has trained us well... turned us into even more fearsome warriors than we could have boasted during the time of our war with the Frost Giants.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30953, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 10 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'And as one of the fiercest tests put upon a warrior of the frostborn, we are made to face a creature far larger than ourselves--giants, dragons, jormungar--as a testament to the fact that size will never be our weakness.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30955, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 11 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'This is the test put before you this day. Return to us only once The Iron Watcher is dead, and be revered as a warrior of the frostborn.', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 30956, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 12 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'He is slow from the rust of the ages... be quick on your feet and he will not best you. You have King Stormheart\'s favor - do not disappoint.', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31343, `TextRange` = 0, `comment` = 'Velog Icebellow' WHERE `CreatureID` = 30401 AND `GroupID` = 13 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I\'LL RISE AGAIN AND WHEN I DO I WILL HAVE MY REVENGE!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31173, `TextRange` = 0, `comment` = 'Dr. Terrible to Nergeld' WHERE `CreatureID` = 30404 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'By all the gods... it can\'t be... Muradin?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31032, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Come on boy, there\'s no mistak\'n it - it\'s definately you. Don\'t ya recognize your younger brother?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31033, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I can\'t believe this! You were dead! All accounts said so... what happened, Muradin. How did you get here?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31034, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Indeed! Magni will be so happy to see you too! He\'s gotten nothing but bad news for a long time now, but this changes everything!', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31035, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'He\'s here in Northrend, brother, looking for you. A seer in Wintergarde brought word that you were not dead, and he left Ironforge immediately to come find you.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31036, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Speaking of which...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31087, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'That\'s in the past, Muradin. Regrets won\'t change anything.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31096, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Aye, be safe Muradin. I\'d join you, but I\'m on top of the most amazing discovery the world has yet seen. I can\'t abandon it now.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31102, `TextRange` = 0, `comment` = 'Brann' WHERE `CreatureID` = 30405 AND `GroupID` = 7 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'What\'s that? You talkin\' to me, lad?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31037, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'My brother... yes... I do have brothers...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31038, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Muradin clutches his head and reels for a moment as the memories rush back to him.', `Type` = 16, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31039, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = '...Brann?', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31040, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I... I dunno, Brann. I\'ve been \'ere a long time... all I \'ave of me life before this place are flashes and nightmares.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31042, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'It\'s good te see you though, brother. More than words can say.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31043, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Magn! Forgive me, the memories are comin\' back slowly, brother.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31045, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The frostborn have been very good to me. They\'re strong people.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31048, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 7 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Not much, Magni. I\'ve had nightmares of a human... tall... light hair... death black armor. His name rests on the tip of me tongue, but...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31089, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 8 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = '...Arthas.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31091, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 9 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Aye, I know. I watched him turn... I watched him give up all that was right and I didn\'t lift a hand... I didn\'t even consider it until it was too late.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31094, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 10 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'No... no they won\'t. But I can make this right. I have te. I\'m goin\' after the boy. I\'ll make\'m answer for everything he\'s done.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31097, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 11 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'I\'m sure, Magni. I\'ll see this through, don\'t ya worry.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31100, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 12 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Go Brann. Bring back an epic tale when we meet again. Farewell for now, brothers...', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31103, `TextRange` = 0, `comment` = 'Yorg' WHERE `CreatureID` = 30408 AND `GroupID` = 13 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Look, Lagnus, I consider you a capable man, but my patience is wearing thin. I know that Muradin is here, can you point me to him or not?', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31084, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Brother! There you are! I can barely believe my eyes... you\'re alive!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31085, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'It\'s so good to see you again, Muradin. And what\'s this I heard about you being a King in your own right now? The Bronzebeards were always destined to greatness.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31086, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 2 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'So it seems! And you haven\'t lost any muscle yourself. Do you remember anything of what happened, Muradin? Fate as turned ill in your absence.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31088, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 3 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Magni nods.', `Type` = 16, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31092, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'He\'s not the boy of your memories anymore, Muradin. He\'s become something else entirely.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31093, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 5 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Are you sure Muradin? I just got you back after years of thinking you were dead. I do not want to lose you again.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31099, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 6 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'So be it then. I have to return to my people, brothers. Come back to me in one piece.', `Type` = 12, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 0, `BroadcastTextId` = 31101, `TextRange` = 0, `comment` = 'Magni' WHERE `CreatureID` = 30411 AND `GroupID` = 7 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'You pose no threat, lesser beings! Give me your worst!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14133, `BroadcastTextId` = 32002, `TextRange` = 0, `comment` = 'vesperon SAY_VESPERON_AGGRO' WHERE `CreatureID` = 30449 AND `GroupID` = 0 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'The least you could do is put up a fight!', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14134, `BroadcastTextId` = 32003, `TextRange` = 0, `comment` = 'vesperon SAY_VESPERON_SLAY_1' WHERE `CreatureID` = 30449 AND `GroupID` = 1 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Father was right about you, Sartharion. You ARE a weakling.', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14139, `BroadcastTextId` = 32008, `TextRange` = 0, `comment` = 'vesperon SAY_VESPERON_RESPOND' WHERE `CreatureID` = 30449 AND `GroupID` = 4 AND `ID` = 0;

UPDATE `creature_text` SET `Text` = 'Aren\'t you tricky? I have a few tricks of my own...', `Type` = 14, `Language` = 0, `Probability` = 100, `Emote` = 0, `Duration` = 0, `Sound` = 14137, `BroadcastTextId` = 32006, `TextRange` = 0, `comment` = 'vesperon SAY_VESPERON_SPECIAL_1' WHERE `CreatureID` = 30449 AND `GroupID` = 5 AND `ID` = 0;

