INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (733, 0, 0, 'Very good.  You are relieved, private.  Rest, but don\'t get too comfortable.  Kurzen won\'t leave us alone forever.', 12, 7, 100, 1, 0, 0, 108, 0, 'Sergeant Yohwa');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (738, 0, 0, 'Time for my patrol.  I\'ll be back shortly.', 12, 7, 100, 66, 0, 0, 102, 0, 'Private Thorsen');

