INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1205, 0, 4, 'Die, $R!  These lands belong to the Stonesplinter Tribe!', 12, 0, 100, 0, 0, 0, 446, 0, 'Grawmug');

