INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1268, 1, 0, 'Precisely.', 12, 7, 100, 273, 0, 0, 1891, 0, 'Ozzie Togglevolt');

