INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1268, 1, 2, 'Couldn\'t have said it better myself.', 12, 7, 100, 273, 0, 0, 1893, 0, 'Ozzie Togglevolt');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1268, 1, 3, 'Most definitely.', 12, 7, 100, 273, 0, 0, 1894, 0, 'Ozzie Togglevolt');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1268, 1, 4, 'I was thinking the same thing.', 12, 7, 100, 273, 0, 0, 1895, 0, 'Ozzie Togglevolt');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 0, 0, 'Let me install these Gyromechanic Gears and Restabilization Cogs and we\'ll fire up The Recombobulator.', 12, 7, 100, 0, 0, 0, 1883, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 1, 0, 'That should do the trick.', 12, 7, 100, 0, 0, 0, 1884, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 2, 0, 'Time to save the entire gnomish race. Here goes nothing!', 12, 7, 100, 5, 0, 0, 1885, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 3, 0, 'Back to the drawing board.', 12, 7, 100, 0, 0, 0, 1887, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 4, 0, 'Perhaps a bit more grease will do the trick.', 12, 7, 100, 1, 0, 0, 1888, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 4, 1, 'Pretty close that time. I think we\'ve almost got it.', 12, 7, 100, 1, 0, 0, 1889, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1269, 4, 2, 'The Recombobulator is shaping up quite nicely. Just a few adjustments to go!', 12, 7, 100, 1, 0, 0, 1890, 0, 'Razzle Sprysprocket');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (1309, 0, 0, 'These are fine pieces, $n.  Let me get started on your robe.', 12, 7, 100, 1, 0, 0, 2647, 0, 'Wynne Larson');

