INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2112, 0, 2, 'I can\'t even visit my father\'s grave in peace anymore.', 12, 7, 100, 0, 0, 0, 963, 0, 'Farrin Daris');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2112, 0, 3, 'Why haven\'t the Stormwind guards come?', 12, 7, 100, 0, 0, 0, 964, 0, 'Farrin Daris');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2112, 0, 4, 'I fear something dark is coming.', 12, 7, 100, 0, 0, 0, 965, 0, 'Farrin Daris');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2112, 0, 5, 'The light appears to have forsaken us.', 12, 7, 100, 0, 0, 0, 966, 0, 'Farrin Daris');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2230, 0, 0, 'Croak!', 12, 0, 100, 0, 0, 0, 579, 0, 'Umpi');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2238, 0, 0, 'Have you freed Drull yet? I don\'t know where he\'s being held.', 12, 1, 100, 6, 0, 0, 593, 0, 'Tog\'thar');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2238, 1, 0, 'I will only slow you down, but no pink-skinned humans will keep me from freedom!', 12, 1, 100, 15, 0, 0, 595, 0, 'Tog\'thar');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2239, 0, 0, 'Ah, it is good to be free of my bonds! Have you freed Tog\'thar yet? The humans split us up after our capture.', 12, 1, 100, 4, 0, 0, 592, 0, 'Drull');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2239, 1, 0, 'Go on ahead without me! I will make my own way to Tarren Mill.', 12, 1, 100, 5, 0, 0, 594, 0, 'Drull');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2274, 0, 0, '%s sniffs the elixir then eagerly digs in!', 16, 0, 100, 0, 0, 0, 580, 0, 'Stanley');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2284, 2, 0, '%s raises his mug to his eye, and frowns.', 16, 0, 100, 0, 0, 0, 561, 0, 'Captured Farmer');

