INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2284, 4, 0, '%s mumbles incoherent words.', 16, 0, 100, 1, 0, 0, 560, 0, 'Captured Farmer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2316, 0, 0, 'Over here! Inside the room. Did you find the key to my chains? The human Borhuin has them.', 12, 1, 100, 22, 0, 0, 598, 0, 'Gol\'dir');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2378, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Kundric Zanden');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2379, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Caretaker Smithers');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2380, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Nandar Branson');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2381, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Micha Yance');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2382, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Darren Malvew');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2383, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Lindea Rabonne');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2433, 0, 3, 'I returned from the grave to take my revenge!', 14, 0, 100, 15, 0, 0, 599, 0, 'Helcular\'s Remains');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2433, 1, 1, 'Die in the name of the Dark Lady, $n.', 14, 0, 100, 0, 0, 0, 600, 0, 'Helcular\'s Remains');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2498, 2, 0, 'Hm... if you\'re looking to adle wits, $n, then the secret behind Zanzil\'s zombies might just do the trick!', 12, 0, 100, 0, 0, 0, 1468, 0, 'Crank Fizzlebub');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2519, 5, 0, 'Ah, good $n.  Now let us see what tale these heads tell...', 12, 1, 100, 1, 0, 0, 735, 0, 'Kin\'weelay');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2519, 6, 0, '%s begins chanting...', 16, 0, 100, 0, 0, 0, 736, 0, 'Kin\'weelay');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2519, 7, 0, 'There, $n.  You may now speak to the Bloodscalp chief and his witchdoctor.', 12, 1, 100, 1, 0, 0, 740, 0, 'Kin\'weelay');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2696, 0, 0, 'Sure does seem like it\'s been a long time since anyone has relieved me from my post.', 12, 7, 100, 0, 0, 0, 790, 0, 'Foggy MacKreel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2696, 1, 0, 'Well, that\'s what I get for oversleeping!', 12, 7, 100, 0, 0, 0, 791, 0, 'Foggy MacKreel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2705, 0, 0, 'Hiccup!', 12, 0, 100, 33, 0, 0, 794, 0, 'Brewmeister Bilger');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2711, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Phin Odelic');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2713, 9, 0, 'Found something... I think.', 12, 7, 100, 0, 0, 0, 820, 0, 'Kinelory');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 0, 0, '%s begins searching through his pack...', 16, 0, 100, 0, 0, 0, 870, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 1, 0, 'Ah!  There is my ratchet!  Now let\'s re-attach these scroll fragments.', 12, 0, 100, 0, 0, 0, 871, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 2, 0, 'There we are, $n.  The Scroll is fixed!  Hooray!', 12, 0, 100, 4, 0, 0, 872, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 3, 0, '%s reads the ancient text $n fetched for him...', 16, 0, 100, 0, 0, 0, 914, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 4, 0, 'Aha!  That\'s it!', 12, 0, 100, 5, 0, 0, 915, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 5, 0, '%s hunkers down to read Yagyin\'s Digest...', 16, 0, 100, 0, 0, 0, 923, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 6, 0, '%s is struck by unleashed magic!', 16, 0, 100, 34, 0, 0, 924, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2785, 7, 0, 'Ow.  Spicy.', 12, 0, 100, 0, 0, 0, 934, 0, 'Theldurin the Lost');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2786, 0, 0, '%s stows the items $n gave him.', 16, 0, 100, 0, 0, 0, 919, 0, 'Gerrig Bonegrip');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2786, 1, 0, 'I thank you, $n.  My associates who will do great things with these...', 12, 7, 100, 2, 0, 0, 920, 0, 'Gerrig Bonegrip');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 1, 0, 'Ow.  Spicy.', 12, 0, 100, 33, 0, 0, 934, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 2, 0, '%s grinds the pearls $n gave him...', 16, 0, 100, 0, 0, 0, 1021, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 3, 0, 'There we are.  A new batch of flash bombs!', 12, 0, 100, 0, 0, 0, 1023, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 4, 0, 'Look out!  We\'re under attack by a $n!', 12, 0, 100, 5, 0, 0, 1022, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 5, 0, 'Take that, beast!', 12, 0, 100, 0, 0, 0, 1024, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2817, 6, 0, '%s tosses dynamite through the air and it lands near by.', 16, 0, 100, 0, 0, 0, 1025, 0, 'Rigglefuzz');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2909, 0, 0, 'Go with speed... <cough cough> Find... <cough> Ryedol...', 12, 7, 100, 0, 0, 0, 957, 0, 'Hammertoe Grez');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2909, 1, 0, '%s falls to the ground. His spirit is released with his last breath.', 16, 0, 100, 0, 0, 0, 979, 0, 'Hammertoe Grez');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2917, 1, 1, 'Oh my! What\'s this? Help!', 12, 7, 100, 0, 0, 0, 938, 0, 'remtravel SAY_REM_AGGRO');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2917, 1, 2, 'Looks like we\'ve uncovered this $n. Now help me kill it!', 12, 7, 100, 0, 0, 0, 939, 0, 'remtravel SAY_REM_AGGRO');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2917, 1, 3, 'Help me! This $n won\'t get off of me!', 12, 7, 100, 0, 0, 0, 940, 0, 'remtravel SAY_REM_AGGRO');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2917, 1, 4, '$n! Help!', 12, 7, 100, 0, 0, 0, 942, 0, 'remtravel SAY_REM_AGGRO');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2917, 1, 5, 'Can you get this $n off me?', 12, 7, 100, 0, 0, 0, 943, 0, 'remtravel SAY_REM_AGGRO');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2919, 0, 0, '%s is ripped apart as it is banished from this world.', 16, 0, 100, 0, 0, 0, 853, 0, 'Fam\'retor Guardian');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2920, 0, 0, '%s looks over at Lotwil nervously.', 16, 0, 100, 0, 0, 0, 959, 0, 'Lucien Tosselwrench');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2921, 0, 0, 'Now to test my design!', 12, 0, 100, 1, 0, 0, 948, 0, 'Lotwil Veriatus');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2921, 1, 0, 'Oh no!  It\'s out of control!  Run!', 12, 0, 100, 5, 0, 0, 949, 0, 'Lotwil Veriatus');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2921, 2, 0, 'I guess I\'d better do something about this!', 12, 0, 100, 0, 0, 0, 950, 0, 'Lotwil Veriatus');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2922, 2, 0, 'Protect master!', 12, 0, 100, 0, 0, 0, 951, 0, 'Servo');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2934, 0, 0, '%s accepts the relics from $n.', 16, 0, 100, 0, 0, 0, 921, 0, 'Keeper Bel\'dugur');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (2934, 1, 0, 'Accept my thanks, $n.  Yagyin\'s journal shall be yours.', 12, 0, 100, 2, 0, 0, 922, 0, 'Keeper Bel\'dugur');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3291, 0, 0, 'Fresh Bread! Get your oven fresh bread here!', 12, 6, 100, 0, 0, 0, 995, 0, 'Greishan Ironstove');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3291, 0, 1, 'Get\'em while they are nice and fresh! Loaves of bread here!', 12, 6, 100, 0, 0, 0, 996, 0, 'Greishan Ironstove');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3291, 0, 2, 'All kinds of bread here! Made fresh today. Get\'em while they last!', 12, 6, 100, 0, 0, 0, 997, 0, 'Greishan Ironstove');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3291, 0, 3, 'Bread here! Loaves of your favorites! Nice and fresh!', 12, 6, 100, 0, 0, 0, 998, 0, 'Greishan Ironstove');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3413, 0, 0, 'Come and have a talk with me if you\'re going to go to Gnomeregan, $n!', 12, 0, 100, 0, 0, 0, 3903, 0, 'Sovik');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3484, 0, 0, 'I shall now begin the robe...', 12, 1, 100, 0, 0, 0, 2665, 0, 'Kil\'hala');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (3484, 1, 0, 'Your robe is complete, $n.', 12, 1, 100, 1, 0, 0, 2666, 0, 'Kil\'hala');

