INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6019, 0, 0, 'Bye!  Better luck next time!', 12, 0, 100, 3, 0, 0, 7553, 0, 'Hornizz Brimbuzzle');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6019, 1, 0, 'Always on the go, that girl.', 12, 0, 100, 0, 0, 0, 7554, 0, 'Hornizz Brimbuzzle');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6031, 0, 0, '%s begins to work...', 16, 0, 100, 0, 0, 0, 2303, 0, 'Tormus Deepforge');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6031, 1, 0, '$n!  I\'m finished!', 12, 7, 100, 1, 0, 0, 2304, 0, 'Tormus Deepforge');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6114, 0, 0, 'Farewell, $n.  And remember, a warrior never shows his back to his foe!', 12, 0, 100, 66, 0, 0, 2302, 0, 'Muren Stormpike');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6123, 0, 0, 'Never cross a Dark Iron, $C.', 12, 0, 100, 0, 0, 0, 1934, 0, 'Dark Iron Spy');

