INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6166, 1, 0, 'Hip hip, hoorah!', 12, 7, 100, 4, 0, 0, 2309, 0, 'Yorus Barleybrew');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6169, 0, 0, '%s begins to work...', 16, 0, 100, 0, 0, 0, 2344, 0, 'Klockmort Spannerspan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6169, 1, 0, 'Hooray hooray! $n! It\'s done!', 12, 7, 100, 4, 0, 0, 2345, 0, 'Klockmort Spannerspan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6172, 1, 0, 'Good luck to you, $n. And don\'t forget... get that script before finding Gazin.', 12, 7, 100, 0, 0, 0, 2353, 0, 'Henze Faulk');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6177, 1, 0, 'Good luck, $n. And remember, find Muiredon once you\'ve accomplished the task.', 12, 6, 100, 0, 0, 0, 2351, 0, 'Narm Faulk');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6181, 0, 0, 'Let\'s get to work, $n!', 12, 0, 100, 1, 0, 0, 2501, 0, 'Jordan Stilwell');

