INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6221, 0, 1, 'The troggs...they never stop coming.  Die trogg!  Die!', 12, 7, 100, 0, 0, 0, 2423, 0, 'Addled Leper');

