INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6223, 1, 0, 'No gnome will be left behind.', 12, 7, 100, 0, 0, 0, 2422, 0, 'Leprous Defender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6223, 1, 1, 'The troggs...they never stop coming.  Die trogg!  Die!', 12, 7, 100, 0, 0, 0, 2423, 0, 'Leprous Defender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6223, 1, 2, 'This sickness clouds my vision, but I know you must be a trogg.  Die foul invader!', 12, 7, 100, 0, 0, 0, 2424, 0, 'Leprous Defender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6223, 1, 3, 'A foul trogg if ever I saw one.  Die!', 12, 7, 100, 0, 0, 0, 2425, 0, 'Leprous Defender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6224, 1, 0, 'No gnome will be left behind.', 12, 7, 100, 0, 0, 0, 2422, 0, 'Leprous Machinesmith');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6224, 1, 1, 'The troggs...they never stop coming.  Die trogg!  Die!', 12, 7, 100, 0, 0, 0, 2423, 0, 'Leprous Machinesmith');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6224, 1, 2, 'This sickness clouds my vision, but I know you must be a trogg.  Die foul invader!', 12, 7, 100, 0, 0, 0, 2424, 0, 'Leprous Machinesmith');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6224, 1, 3, 'A foul trogg if ever I saw one.  Die!', 12, 7, 100, 0, 0, 0, 2425, 0, 'Leprous Machinesmith');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6244, 0, 0, 'A thousand years ago, the immortal elves, demigods of the forest and dragons fought against the Legion on the slopes of Hyjal.', 12, 7, 100, 1, 0, 0, 2310, 0, 'Takar the Seer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6244, 1, 0, 'Anathera and Latherion fought back to back where the battle was thickest. Two lovers determined to survive the war together.', 12, 7, 100, 1, 0, 0, 2311, 0, 'Takar the Seer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6244, 2, 0, 'But it was not to be. As their foes pressed close, Anathera\'s armor was pierced by a demon\'s tainted blade. In the thick of battle, there would be nothing to save her.', 12, 7, 100, 1, 0, 0, 2312, 0, 'Takar the Seer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6244, 3, 0, 'Ignoring the battle that raged about him, Latherion dropped his guard to cradle his love in her dying moments. But the demons gave him no quarter, and quickly laid him low.', 12, 7, 100, 1, 0, 0, 2314, 0, 'Takar the Seer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6244, 4, 0, 'Where the two lovers fell, a tree would bloom. The elves call it the heartswood. It will surely serve your ends.', 12, 7, 100, 1, 0, 0, 2317, 0, 'Takar the Seer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6245, 0, 0, 'So this... this is how it ends, my love...', 12, 7, 100, 0, 0, 0, 2316, 0, 'Anathera');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6246, 0, 0, 'Anathera!', 12, 7, 100, 15, 0, 0, 2313, 0, 'Latherion');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6246, 1, 0, 'Anathera... I cannot bear to face the rest of eternity without you by my side... If you are taken from me, then let this be the day I also return to the earth...', 12, 7, 100, 0, 0, 0, 2315, 0, 'Latherion');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6266, 1, 0, 'Ok, let\'s get this orb made...', 12, 0, 100, 0, 0, 0, 2663, 0, 'Menara Voidrender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6266, 2, 0, 'All right.  It\'s made!', 12, 0, 100, 1, 0, 0, 2664, 0, 'Menara Voidrender');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6408, 0, 0, '%s begins to work...', 16, 0, 100, 0, 0, 0, 2348, 0, 'Ula\'elek');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6408, 1, 0, 'I am done.  Your armor is ready, $n.', 12, 1, 100, 1, 0, 0, 2646, 0, 'Ula\'elek');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6410, 0, 0, '%s begins to work...', 16, 0, 100, 0, 0, 0, 2348, 0, 'Orm Stonehoof');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6410, 1, 0, 'I have completed your helm, $n.', 12, 1, 100, 1, 0, 0, 2635, 0, 'Orm Stonehoof');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6411, 0, 0, '%s begins to craft...', 16, 0, 100, 0, 0, 0, 2644, 0, 'Velora Nitely');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6411, 1, 0, 'I have finished your leg guards, $n.', 12, 0, 100, 1, 0, 0, 2645, 0, 'Velora Nitely');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6516, 0, 0, '%s looks tired. He then yawns and lies down next to A-Me 01.', 16, 0, 100, 0, 0, 0, 5045, 0, 'Un\'Goro Thunderer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6516, 0, 1, '%s snores loudly and cuddles up next to A-Me 01.', 16, 0, 100, 0, 0, 0, 5046, 0, 'Un\'Goro Thunderer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 1, 0, 'Ok, let\'s get this orb made...', 12, 0, 100, 0, 0, 0, 2663, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 2, 0, 'All right.  It\'s made!', 12, 0, 100, 1, 0, 0, 2664, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 3, 0, 'Stand back, and ... hold your breath.  I haven\'t done this in a while.', 12, 0, 100, 1, 0, 0, 2708, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 4, 0, 'It worked!  Amazing!  I guess I haven\'t lost my touch...', 12, 0, 100, 4, 0, 0, 2709, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 5, 0, 'Good luck out there, $n.', 12, 0, 100, 0, 0, 0, 2624, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 6, 0, 'I just have one thing to check...', 12, 0, 100, 0, 0, 0, 2656, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 7, 0, 'That\'s it!  It worked!', 12, 0, 100, 4, 0, 0, 2657, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 8, 0, 'Thanks for your patience, $n.', 12, 0, 100, 2, 0, 0, 2658, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6546, 9, 0, 'I\'ll just keep this here until we need it...	', 12, 0, 100, 1, 0, 0, 2659, 0, 'Tabetha');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6557, 0, 0, '%s begins to make a copy of itself!', 16, 0, 100, 0, 0, 0, 2082, 0, 'Primal Ooze');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6559, 0, 0, '%s explodes into chunks of acidic slime!', 16, 0, 100, 0, 0, 0, 4838, 0, 'Glutinous Ooze');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6826, 1, 0, 'Let me grab a spell focus from inside my home here, and then we\'ll get started!', 12, 7, 100, 0, 0, 0, 3121, 0, 'Talvash del Kissel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6826, 2, 0, 'Bah, it isn\'t here.  Where did I have that blasted thing at last?', 12, 7, 100, 6, 0, 0, 3122, 0, 'Talvash del Kissel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6826, 3, 0, 'That\'s right, it\'s over by the bed.  Heh, sorry about that!', 12, 7, 100, 0, 0, 0, 3123, 0, 'Talvash del Kissel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6826, 4, 0, 'Fantastic then!  Let\'s get this thing fixed for you.', 12, 7, 100, 0, 0, 0, 3124, 0, 'Talvash del Kissel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6826, 5, 0, 'Success!  Huzzah!  The power source restored the necklace!', 12, 7, 100, 4, 0, 0, 3125, 0, 'Talvash del Kissel');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (6966, 0, 0, 'Oh! I almost forgot! I slipped you a set of thieven\' tools. You\'ll need those where you\'re going.', 12, 0, 100, 0, 0, 0, 3562, 0, 'Lucius');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (7033, 1, 0, 'GOR\'TESH DEAD?!?!', 14, 0, 100, 0, 0, 0, 4707, 0, 'Firegut Ogre');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (7033, 1, 1, 'RUN! RUN FOR HILLS!', 14, 0, 100, 0, 0, 0, 4708, 0, 'Firegut Ogre');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (7033, 1, 2, 'WHO KILL GOR\'TESH!?!? WHO DO THIS?!', 14, 0, 100, 0, 0, 0, 4709, 0, 'Firegut Ogre');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (7033, 1, 3, '$n KILL! $G He:She; kill you now! RUN! RUN!', 14, 0, 100, 0, 0, 0, 4711, 0, 'Firegut Ogre');

