INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (7035, 1, 1, 'RUN! RUN FOR HILLS!', 14, 0, 100, 0, 0, 0, 4708, 0, 'Firegut Brute');

