INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9520, 11, 0, 'Time to make your final stand, insect.', 12, 0, 100, 0, 0, 0, 4913, 0, 'Grark Lorkrub');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9598, 7, 0, 'Thank you, $n. Now my spirit will finally be at peace.', 12, 0, 100, 0, 0, 0, 5036, 0, 'Arei');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9598, 8, 0, 'I sense the taint of corruption upon this $n. Help me destroy it!', 12, 0, 100, 0, 0, 0, 5473, 0, 'Arei');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9598, 8, 1, 'This creature suffers from the effects of the fel... We must end its misery.', 12, 0, 100, 0, 0, 0, 5474, 0, 'Arei');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9598, 8, 2, 'This $n has been driven mad from the corruption!', 12, 0, 100, 0, 0, 0, 5475, 0, 'Arei');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9936, 1, 0, '%s follows $n obediently.', 16, 0, 100, 0, 0, 0, 5940, 0, 'Corrupted Kitten');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9937, 0, 0, '%s jumps into the moonwell, and goes underwater...', 16, 0, 100, 0, 0, 0, 5939, 0, 'Common Kitten');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9978, 0, 0, 'Guards! Help me!', 12, 7, 100, 0, 0, 0, 4566, 0, 'Wesley');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9996, 0, 0, 'I\'m very curious to see what this sample of water will do!', 12, 0, 100, 1, 0, 0, 5945, 0, 'Winna Hazzard');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9996, 1, 0, '%s pours the corrupted water onto the cat.', 16, 0, 100, 16, 0, 0, 5946, 0, 'Winna Hazzard');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (9996, 2, 0, 'Haha! Perfect!', 12, 0, 100, 11, 0, 0, 5947, 0, 'Winna Hazzard');

