INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 0, 'What could be taking so long?', 12, 1, 100, 0, 0, 0, 5955, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 1, 'How long can it take to pick a handful of weeds?', 12, 1, 100, 0, 0, 0, 5956, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 2, 'At this rate I could have gathered them myself!', 12, 1, 100, 0, 0, 0, 5957, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 3, 'If you want something done right, do it yourself!', 12, 1, 100, 0, 0, 0, 5958, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 4, 'As if I had all eternity.', 12, 1, 100, 0, 0, 0, 5959, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 5, 'Ah, this must be him now... no?  Bah!', 12, 1, 100, 0, 0, 0, 5960, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 6, 'Maybe I should have just bought some off of Faruza?', 12, 1, 100, 0, 0, 0, 5961, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10665, 0, 7, 'I had to go and requisition an Abomination... an Abomination!', 12, 1, 100, 0, 0, 0, 5962, 0, 'Junior Apothecary Holland');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10740, 0, 0, '%s whimpers.', 16, 0, 100, 0, 0, 0, 6270, 0, 'Awbee');

