INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (10740, 0, 2, '%s cries for help.', 16, 0, 100, 0, 0, 0, 6272, 0, 'Awbee');

