INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (20926, 0, 0, 'You hear a faint echo....', 16, 0, 100, 0, 0, 0, 18599, 3, 'When Access Panel is used');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (20926, 1, 0, 'You hear a loud rumble of metal grinding on stone...', 16, 0, 100, 0, 0, 0, 18600, 3, 'When main door open');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21397, 0, 0, '%s applauds lightly, smiling.', 16, 0, 100, 21, 0, 0, 19078, 0, 'Aeman Brightsong');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21397, 1, 0, 'How fortuitous. I believe this calls for some wine.', 12, 7, 100, 1, 0, 0, 19079, 0, 'Aeman Brightsong');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21397, 2, 0, 'A fine vintage in celebration of our salvation!', 12, 7, 100, 1, 0, 0, 19080, 0, 'Aeman Brightsong');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21400, 0, 0, 'We\'re saved? We\'re really saved?! YAHOO!', 12, 7, 100, 5, 0, 0, 19076, 0, 'Eckert');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21400, 1, 0, 'It\'s time to PARTY!', 12, 7, 100, 0, 0, 0, 19077, 0, 'Eckert');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (21504, 13, 0, 'Rise, young Voldoun.  Do not worry yourself with pleasantries.  I come at the behest of our master, Prince Kael\'thas.  He bids me to check on the progress of the mana bomb.', 12, 0, 100, 1, 0, 0, 19157, 0, 'Pathaleon the Calculator\'s Image');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22006, 0, 0, 'Master... I\'ve failed you...', 14, 0, 100, 0, 0, 0, 19820, 0, 'Shadowlord Deathwail');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22082, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 2384, 0, 'Shadowmoon Slayer');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22148, 0, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 10677, 0, 'Gordunni Head-Splitter');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 0, 0, 'Get to work on those crystals!', 12, 0, 100, 0, 0, 0, 21112, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 0, 1, 'Move it!  These crystals aren\'t going to collect themselves.', 12, 0, 100, 0, 0, 0, 21114, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 0, 2, 'These crystals will work.  Get them!', 12, 0, 100, 0, 0, 0, 21113, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 1, 0, 'At least you didn\'\'t screw this batch up.', 12, 0, 100, 0, 0, 0, 21116, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 1, 1, 'I can\'\'t believe you\'\'ve actually done something right for once.', 12, 0, 100, 0, 0, 0, 21117, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22304, 1, 2, 'You\'\'ve ruined this batch!  Why must I work with you worthless Gan\'\'arg.', 12, 0, 100, 0, 0, 0, 21115, 0, 'Mo\'\'arg Extractor');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22378, 0, 0, 'Speak, filthy refugee!  What was your caravan doing in the Bone Wastes?', 12, 0, 100, 0, 0, 0, 20160, 0, 'Cabal Interrogator');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22424, 6, 0, '%s wanders off into the distance.', 16, 0, 100, 0, 0, 0, 20297, 0, 'Skywing');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22459, 1, 0, 'Praise the naaru, I\'m saved. I will try to make it clear on my own.', 12, 7, 100, 5, 0, 0, 20143, 0, 'Freed Sha\'tar Warrior');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22459, 1, 1, 'I\'m hurt, but I can still run. Thank you, stranger.', 12, 7, 100, 5, 0, 0, 20144, 0, 'Freed Sha\'tar Warrior');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22459, 1, 2, 'My thanks, stranger.', 12, 7, 100, 5, 0, 0, 20145, 0, 'Freed Sha\'tar Warrior');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22459, 1, 3, 'I\'m too weak to fight with you.  Please find my friends.', 12, 7, 100, 5, 0, 0, 20146, 0, 'Freed Sha\'tar Warrior');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (22483, 0, 3, 'AYYAYAAYAA!', 12, 7, 100, 5, 0, 0, 20311, 0, 'Sand Gnome');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23566, 0, 0, 'It would be a shame to let these leaflets go to waste, wouldn\'t it?', 12, 7, 100, 0, 0, 0, 22105, 0, 'Calia Hastings');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23566, 1, 0, 'With just a little creative editing, these are much more useful...', 12, 7, 100, 0, 0, 0, 22107, 0, 'Calia Hastings');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23569, 0, 0, 'Hmm... old coins... ugly jewelry...', 12, 7, 100, 0, 0, 0, 22160, 0, 'Renn McGill');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23569, 1, 0, 'More ugly jewelry... letters home... I\'m beginning to give up hope!', 12, 7, 100, 0, 0, 0, 22161, 0, 'Renn McGill');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23569, 2, 0, 'Hey... what\'s this? A pair of manacles and not just any. These are enchanted. This cargo, it wasn\'t a thing... it was a person!', 12, 7, 100, 0, 0, 0, 22162, 0, 'Renn McGill');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23600, 0, 0, 'Hmm... I wonder...', 12, 0, 100, 0, 0, 0, 22042, 0, 'Apprentice Morlann');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23600, 1, 0, 'Now, where is it?', 12, 0, 100, 6, 0, 0, 22045, 0, 'Apprentice Morlann');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23600, 2, 0, 'Stupid mages... always using the last of a reagent and never replacing it.', 12, 0, 100, 1, 0, 0, 22043, 0, 'Apprentice Morlann');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23601, 0, 0, 'Is he complaining about the reagents again? Does he even remember how he left the summoning tomes last time?', 12, 0, 100, 6, 0, 0, 22044, 0, 'Apprentice Garion');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23651, 0, 0, 'Suffer, insect!', 12, 0, 100, 0, 0, 0, 22701, 0, 'Dragonflayer Tribesman');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23651, 0, 1, 'My life for Ymiron!', 12, 0, 100, 0, 0, 0, 22702, 0, 'Dragonflayer Tribesman');

