INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23712, 0, 0, 'What\'s happening?', 12, 7, 100, 18, 0, 0, 22177, 0, 'Touring Orphan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23712, 0, 1, 'I want to go back to the orphanage!', 12, 7, 100, 18, 0, 0, 22344, 0, 'Touring Orphan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23712, 0, 2, 'Matron!  Is that bad man going to eat us?', 12, 7, 100, 18, 0, 0, 22345, 0, 'Touring Orphan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23712, 0, 3, 'If my dad were alive, he would put out the fires!', 12, 7, 100, 18, 0, 0, 22346, 0, 'Touring Orphan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23712, 0, 4, 'If my mom were alive, she would put out the fires!', 12, 7, 100, 18, 0, 0, 22347, 0, 'Touring Orphan');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 0, 0, 'Me crush puny friend of dragons!', 12, 0, 100, 15, 0, 0, 22416, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 0, 1, 'You leave Stonemaul lands now!', 12, 0, 100, 15, 0, 0, 22417, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 0, 2, 'Why you wake ghost? Where other Stonemauls?!', 12, 0, 100, 15, 0, 0, 22418, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 1, 0, 'Raaar!!! Me smash $r!', 12, 0, 100, 0, 0, 0, 1925, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 1, 1, 'Me smash! You die!', 12, 0, 100, 0, 0, 0, 1926, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23786, 1, 2, 'I\'ll crush you!', 12, 0, 100, 0, 0, 0, 1927, 0, 'Stonemaul Spirit');

INSERT INTO `creature_text`(`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES (23905, 4, 0, 'We defeated the sea monster!', 14, 0, 100, 0, 0, 0, 22634, 0, 'Major Mills');

