INSERT INTO `gossip_menu_option`(`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (6534, 0, 0, 'Hello, Rutgar. The Commander has sent me here to gather some information about his missing wife.', 10712, 1, 1, 6551, 0, 0, 0, '', 0, 0);

