UPDATE `gossip_menu_option` SET `OptionIcon` = 0, `OptionText` = 'Worry no more, taunka. The Horde will save and protect you and your people, but first you must swear allegiance to the Warchief by taking the blood oath of the Horde.', `OptionBroadcastTextID` = 25649, `OptionType` = 1, `OptionNpcFlag` = 1, `ActionMenuID` = 9305, `ActionPoiID` = 0, `BoxCoded` = 0, `BoxMoney` = 0, `BoxText` = '', `BoxBroadcastTextID` = 0, `VerifiedBuild` = 0 WHERE `MenuID` = 9302 AND `OptionID` = 0;

UPDATE `gossip_menu_option` SET `OptionIcon` = 0, `OptionText` = 'For the Horde!\r\n\r\nArm yourself from the crates that surround us and report to Agmar\'s Hammer, east of here. Your first trial as a member of the Horde is to survive the journey.\r\n\r\nLok\'tar ogar!', `OptionBroadcastTextID` = 25655, `OptionType` = 1, `OptionNpcFlag` = 1, `ActionMenuID` = 0, `ActionPoiID` = 0, `BoxCoded` = 0, `BoxMoney` = 0, `BoxText` = '', `BoxBroadcastTextID` = 0, `VerifiedBuild` = 0 WHERE `MenuID` = 9303 AND `OptionID` = 0;

UPDATE `gossip_menu_option` SET `OptionIcon` = 0, `OptionText` = 'Then repeat after me: \"Lok\'tar ogar! Victory or death - it is these words that bind me to the Horde. For they are the most sacred and fundamental of truths to any warrior of the Horde.\r\n\r\nI give my flesh and blood freely to the Warchief. I am the instrument of my Warchief\'s desire. I am a weapon of my Warchief\'s command.\r\n\r\nFrom this moment until the end of days I live and die - For the Horde!\"', `OptionBroadcastTextID` = 25653, `OptionType` = 1, `OptionNpcFlag` = 1, `ActionMenuID` = 9303, `ActionPoiID` = 0, `BoxCoded` = 0, `BoxMoney` = 0, `BoxText` = '', `BoxBroadcastTextID` = 0, `VerifiedBuild` = 0 WHERE `MenuID` = 9304 AND `OptionID` = 0;

UPDATE `gossip_menu_option` SET `OptionIcon` = 0, `OptionText` = 'Yes, taunka. Retribution is a given right of all members of the Horde.', `OptionBroadcastTextID` = 25651, `OptionType` = 1, `OptionNpcFlag` = 1, `ActionMenuID` = 9304, `ActionPoiID` = 0, `BoxCoded` = 0, `BoxMoney` = 0, `BoxText` = '', `BoxBroadcastTextID` = 0, `VerifiedBuild` = 0 WHERE `MenuID` = 9305 AND `OptionID` = 0;

