UPDATE `npc_text` SET `text0_0` = 'If you ask me, I think the goblins are a shoe in.  We have the tools, and we have the talent!', `text0_1` = 'If you ask me, I think the goblins are a shoe in.  We have the tools, and we have the talent!', `BroadcastTextID0` = 2764, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'If it weren\'t for that cursed, gnomish luck, they\'d never win a race!', `text1_1` = 'If it weren\'t for that cursed, gnomish luck, they\'d never win a race!', `BroadcastTextID1` = 2765, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'If I were you, I\'d buy a goblin race voucher.  Rooting for the other team is a waste of time.', `text2_1` = 'If I were you, I\'d buy a goblin race voucher.  Rooting for the other team is a waste of time.', `BroadcastTextID2` = 2766, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'My money\'s on the goblins!  And if you have any sense then yours is too!', `text3_1` = 'My money\'s on the goblins!  And if you have any sense then yours is too!', `BroadcastTextID3` = 2767, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'I heard they were going to try to blow up the gnome\'s car in the next race!  True or not, I\'d stand clear of their pit area.', `text4_1` = 'I heard they were going to try to blow up the gnome\'s car in the next race!  True or not, I\'d stand clear of their pit area.', `BroadcastTextID4` = 2768, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextI