UPDATE `npc_text` SET `text0_0` = 'Oh, you mean Johnson?  I heard he\'s in hiding.', `text0_1` = 'Oh, you mean Johnson?  I heard he\'s in hiding.', `BroadcastTextID0` = 2773, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Hah!  Tirth\'s been looking for him for days, but he doesn\'t want to be found.  He\'s chicken!', `text1_1` = 'Hah!  Tirth\'s been looking for him for days, but he doesn\'t want to be found.  He\'s chicken!', `BroadcastTextID1` = 2782, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'You looking for plucky?  Well, you didn\'t hear me say this, but... maybe if you ask Kronkrider up in the tower, he\'ll tell you...', `text2_1` = 'You looking for plucky?  Well, you didn\'t hear me say this, but... maybe if you ask Kronkrider up in the tower, he\'ll tell you...', `BroadcastTextID2` = 8427, `lang2` = 0, `Probability2` = 2, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 779;

UPDATE `npc_text` SET `text0_0` = 'If it weren\'t for the goblins\' inconceivable, dumb luck, they\'d crash their car during every race!', `text0_1` = 'If it weren\'t for the goblins\' inconceivable, dumb luck, they\'d crash their car during every race!', `BroadcastTextID0` = 2774, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'These races are a great opportunity to show our ingenuity!', `text1_1` = 'These races are a great opportunity to show our ingenuity!', `BroadcastTextID1` = 2775, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I installed a new device in our car\'s matrix regulometer.  That should increase its velocity quotient by a factor of no less than fifteen!', `text2_1` = 'I installed a new device in our car\'s matrix regulometer.  That should increase its velocity quotient by a factor of no less than fifteen!', `BroadcastTextID2` = 2776, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'My son could design a faster car than that clunky goblin junk heap! ', `text3_1` = 'My son could design a faster car than that clunky goblin junk heap!', `BroadcastTextID3` = 2777, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'My Gizmotic Almanacotron says that we should beat the goblins by twenty seconds more than we did last time!', `text4_1` = 'My Gizmotic Almanacotron says that we should beat the goblins by twenty seconds more than we did last time!', `BroadcastTextID4` = 2778, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', 