UPDATE `npc_text` SET `text0_0` = 'You can find the gryphon master on the northeast rampart overlooking the Valley of Heroes.', `text0_1` = 'You can find the gryphon master on the northeast rampart overlooking the Valley of Heroes.', `BroadcastTextID0` = 2864, `lang0` = 7, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Ahhh, you are looking for Dungar Longdrink. He has some of the fastest gryphons this side of Khaz Modan! You can find him up on the ramparts in the Trade District.', `text1_1` = 'Ahhh, you are looking for Dungar Longdrink. He has some of the fastest gryphons this side of Khaz Modan! You can find him up on the ramparts in the Trade District.', `BroadcastTextID1` = 2876, `lang1` = 7, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Lookin\' to take a gryphon ride, eh? Dungar keeps his birds up on the rampart in the Trade District. Just remember to hold on tight! ', `text2_1` = 'Lookin\' to take a gryphon ride, eh? Dungar keeps his birds up on the rampart in the Trade District. Just remember to hold on tight! ', `BroadcastTextID2` = 2877, `lang2` = 7, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Gryphons, eh? Never really cared for the beasts but to each their own.$B$BYou can find Dungar Longdrink on the rampart in the Trade District.', `text3_1` = 'Gryphons, eh? Never really cared for the beasts but to each their own.$B$BYou can find Dungar Longdrink on the rampart in the Trade District.', `BroadcastTextID3` = 2878, `lang3` = 7, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probabi