UPDATE `npc_text` SET `text0_0` = 'Ragnaros will reign supreme!', `text0_1` = 'Ragnaros will reign supreme!', `BroadcastTextID0` = 4944, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Have a drink, $c.  It might be your last!', `text1_1` = 'Have a drink, $c.  It might be your last!', `BroadcastTextID1` = 4945, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'If it weren\'t for the Grim Guzzler, I\'d spend my free time pulling the wings off dragon whelps.', `text2_1` = 'If it weren\'t for the Grim Guzzler, I\'d spend my free time pulling the wings off dragon whelps.', `BroadcastTextID2` = 4946, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'If it weren\'t for the Grim Guzzler, I\'d probably spend my free time pulling the wings off dragon whelps.', `text3_1` = 'If it weren\'t for the Grim Guzzler, I\'d probably spend my free time pulling the wings off dragon whelps.', `BroadcastTextID3` = 4947, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'The water elementals are at war with the fire elementals, which sort of means they\'re at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause...', `text4_1` = 'The water elementals are at war with the fire elementals, which sort of means they\'re at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause...', `BroadcastTextID4` = 4948, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'I heard that a noble among the water elementals, Hydraxis, wages war with the servants of fire.  Let\'s hope he loses!', `text5_1` = 'I heard that a noble among the water elementals, Hydraxis, wages war with the servants of fire.  Let\'s hope he loses!', `BroadcastTextID5` = 4950, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 1, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'The Waterlord Hydraxis hides off in Azshara, on an island in the Bay of Storms.  What kind of threat can the fool muster from there?', `text6_1` = 'The Waterlord Hydraxis hides off in Azshara, on an island in the Bay of Storms.  What kind of threat can the fool muster from there?', `BroadcastTextID6` = 4951, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 1, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'If Hydraxis recruits more in his war, then it might shift the balance of power...', `text7_1` = 'If Hydraxis recruits more in his war, then it might shift the balance of power...', `BroadcastTextID7` = 4953, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 1, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 2636;

UPDATE `npc_text` SET `text0_0` = 'It\'s all guns and flames until someone loses and dies.', `text0_1` = 'It\'s all guns and flames until someone loses and dies.', `BroadcastTextID0` = 4954, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'My father told me there\'d be days like this, where a stranger would talk to me and I\'d have to restrain myself from killing $ghim:her;.', `text1_1` = 'My father told me there\'d be days like this, where a stranger would talk to me and I\'d have to restrain myself from killing $ghim:her;.', `BroadcastTextID1` = 4956, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Have you tried that Thunderbrew Lager?  It\'s good stuff!', `text2_1` = 'Have you tried that Thunderbrew Lager?  It\'s good stuff!', `BroadcastTextID2` = 5066, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'I have duty in an hour, but until then... bottom\'s up!', `text3_1` = 'I have duty in an hour, but until then... bottom\'s up!', `BroadcastTextID3` = 5067, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 1234