UPDATE `npc_text` SET `text0_0` = 'Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye\'ll want to be seeing about that.  $B$BYe can find him on the eastern side of The Great Forge in the middle of Ironforge.', `text0_1` = 'Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye\'ll want to be seeing about that.  $B$BYe can find him on the eastern side of The Great Forge in the middle of Ironforge.', `BroadcastTextID0` = 5083, `lang0` = 0, `Probability0` = 50, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo\'s of theirs, just give me a gryphon and the wind in me hair!  $B$BWell now, I won\'t keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he\'ll get ye on yer way.', `text1_1` = 'Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo\'s of theirs, just give me a gryphon and the wind in me hair!  $B$BWell now, I won\'t keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he\'ll get ye on yer way.', `BroadcastTextID1` = 5085, `lang1` = 0, `Probability1` = 50, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4