UPDATE `npc_text` SET `text0_0` = 'Brandur Ironhammer would be the one ye\'d want to see.  Ye can find him in the Hall of Mysteries north of the gates of Ironforge.', `text0_1` = 'Brandur Ironhammer would be the one ye\'d want to see.  Ye can find him in the Hall of Mysteries north of the gates of Ironforge.', `BroadcastTextID0` = 5103, `lang0` = 0, `Probability0` = 50, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Ah, good ol\' Brandur Ironhammer.  There\'s no doubt he\'ll provide ye with the guidance ye seek, $glad : lass;.  Ye\'ll find him in the Hall of Mysteries north of the gates of Ironforge.', `text1_1` = 'Ah, good ol\' Brandur Ironhammer.  There\'s no doubt he\'ll provide ye with the guidance ye seek, $glad : lass;.  Ye\'ll find him in the Hall of Mysteries north of the gates of Ironforge.', `BroadcastTextID1` = 5104, `lang1` = 0, `Probability1` = 50, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `V