UPDATE `npc_text` SET `text0_0` = 'Now why would ye be needing the services of one of those types?  We get enough trouble out of that rogue, Hulfdan Blackbeard, over in The Forlorn Cavern, do I need to be turning my eye to you as well?', `text0_1` = 'Now why would ye be needing the services of one of those types?  We get enough trouble out of that rogue, Hulfdan Blackbeard, over in The Forlorn Cavern, do I need to be turning my eye to you as well?', `BroadcastTextID0` = 5106, `lang0` = 0, `Probability0` = 50, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I\'d wager ye\'ll find Fenthwick there, no doubt counting the coin of another cut purse.  I\'ll catch him one of these days!  $B$BIn the meantime I\'ll have my eye on you as well, $glad : lass;.', `text1_1` = 'All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I\'d wager ye\'ll find Fenthwick there, no doubt counting the coin of another cut purse.  I\'ll catch him one of these days!  $B$BIn the meantime I\'ll have my eye on you as well, $glad : lass;.', `BroadcastTextID1` = 5107, `lang1` = 0, `Probability1` = 50, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `tex