UPDATE `npc_text` SET `text0_0` = 'Ah, I believe Gimble Thistlefuzz is who ye\'ll be needing if yer looking to learn the Enchanter\'s profession.  Ye\'ll find Gimble in his shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge.', `text0_1` = 'Ah, I believe Gimble Thistlefuzz is who ye\'ll be needing if yer looking to learn the Enchanter\'s profession.  Ye\'ll find Gimble in his shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge.', `BroadcastTextID0` = 5122, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn\'t spill a drop, but now I can\'t drink from it!  Such a tragedy.  $B$BYou be sure to heed me advice when ye see Gimble.  He\'ll be in his shop right by the Gryphon Master at The Great Forge.', `text1_1` = 'Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn\'t spill a drop, but now I can\'t drink from it!  Such a tragedy.  $B$BYou be sure to heed me advice when ye see Gimble.  He\'ll be in his shop right by the Gryphon Master at The Great Forge.', `BroadcastTextID1` = 5365, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0,