UPDATE `npc_text` SET `text0_0` = 'The tinkerer\'s craft for you is it?  No doubt ye\'ll want to go see Springspindle Fizzlegear in Tinker Town.  $B$BJust head east from the gates of Ironforge, or follow the sound of the explosions.', `text0_1` = 'The tinkerer\'s craft for you is it?  No doubt ye\'ll want to go see Springspindle Fizzlegear in Tinker Town.  $B$BJust head east from the gates of Ironforge, or follow the sound of the explosions.', `BroadcastTextID0` = 5124, `lang0` = 0, `Probability0` = 60, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Oh, you\'re looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you\'re going to his shop in Tinker Town, keep your hands to yourself and don\'t pet any of his mechanical sheep!  $B$BExploding sheep... now why would you even make such a thing!?', `text1_1` = 'Oh, you\'re looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you\'re going to his shop in Tinker Town, keep your hands to yourself and don\'t pet any of his mechanical sheep!  $B$BExploding sheep... now why would you even make such a thing!?', `BroadcastTextID1` = 6337, `lang1` = 0, `Probability1` = 40, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5