UPDATE `npc_text` SET `text0_0` = 'That Jormund Stonebrow has a knack for the needle, he does.  Should you be needing some training, then you\'ll find him at Stonebrow\'s Clothier on the northern side of The Great Forge.', `text0_1` = 'That Jormund Stonebrow has a knack for the needle, he does.  Should you be needing some training, then you\'ll find him at Stonebrow\'s Clothier on the northern side of The Great Forge.', `BroadcastTextID0` = 5145, `lang0` = 0, `Probability0` = 60, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he\'d killed seven with one blow!  $B$BYe should pay him a visit at his store on the north side of The Great Forge an\' see if he\'ll tell ye the tale!', `text1_1` = 'Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he\'d killed seven with one blow!  $B$BYe should pay him a visit at his store on the north side of The Great Forge an\' see if he\'ll tell ye the tale!', `BroadcastTextID1` = 6347, `lang1` = 0, `Probability1` = 40, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_