UPDATE `npc_text` SET `text0_0` = 'Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen\'s Terrace.', `text0_1` = 'Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen\'s Terrace.', `BroadcastTextID0` = 5357, `lang0` = 0, `Probability0` = 75, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'The dishes that Alegorn whips up are to die for.  He\'s always busy preparing new delicacies over in the Craftsman\'s Terrace.  Be sure to try his Cenarion Green recipe if he has any left.  $B$BNow, if you don\'t mind, I must investigate this rash of missing deer. ', `text1_1` = 'The dishes that Alegorn whips up are to die for.  He\'s always busy preparing new delicacies over in the Craftsman\'s Terrace.  Be sure to try his Cenarion Green recipe if he has any left.  $B$BNow, if you don\'t mind, I must investigate this rash of missing deer. ', `BroadcastTextID1` = 5358, `lang1` = 0, `Probability1` = 25, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `e