UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Time is running out for me... for us all...', `BroadcastTextID0` = 6110, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'I have so much to do... so much before the plague comes...$B', `BroadcastTextID1` = 6111, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'John, honey, where are you?', `BroadcastTextID2` = 6112, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'What is happening to everyone?  I feel... cold...', `BroadcastTextID3` = 6113, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'Shhh... do you smell something?', `BroadcastTextID4` = 6539, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 3668;

