UPDATE `npc_text` SET `text0_0` = 'Aye, everyone wants to ride the tram, it\'s a real hoot and a half.  Well, if ye want to find the tram, it\'s located over in Tinker Town just east of the gates of Ironforge.', `text0_1` = 'Aye, everyone wants to ride the tram, it\'s a real hoot and a half.  Well, if ye want to find the tram, it\'s located over in Tinker Town just east of the gates of Ironforge.', `BroadcastTextID0` = 6333, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol\' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  $B$BBah!  You go take the tram then... it\'s over in Tinker Town with the rest of the gnomish contraptions.', `text1_1` = 'Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol\' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  $B$BBah!  You go take the tram then... it\'s over in Tinker Town with the rest of the gnomish contraptions.', `BroadcastTextID1` = 6334, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` =