UPDATE `npc_text` SET `text0_0` = 'There is a mailbox located conveniently right between the Stormwind Bank and The Gilded Rose Inn in the Trade District.', `text0_1` = 'There is a mailbox located conveniently right between the Stormwind Bank and The Gilded Rose Inn in the Trade District.', `BroadcastTextID0` = 6394, `lang0` = 0, `Probability0` = 60, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I don\'t know how they do it...  those mailboxes must be magic portals or something.  Why I see people gathered around the mailbox next to the bank all day pulling swords and shields and various armor all from that small box!', `text1_1` = 'I don\'t know how they do it...  those mailboxes must be magic portals or something.  Why I see people gathered around the mailbox next to the bank all day pulling swords and shields and various armor all from that small box!', `BroadcastTextID1` = 6395, `lang1` = 0, `Probability1` = 40, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0