UPDATE `npc_text` SET `text0_0` = 'You can find Vance Undergloom upstairs in a room at the Gallows\' End Tavern on the southeast side of Brill.', `text0_1` = 'You can find Vance Undergloom upstairs in a room at the Gallows\' End Tavern on the southeast side of Brill.', `BroadcastTextID0` = 6751, `lang0` = 1, `Probability0` = 80, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Word is that Vance Undergloom has taken a permanent room upstairs at the Gallows\' End Tavern at the southeast end of town.  I think he\'s just off the reading room.', `text1_1` = 'Word is that Vance Undergloom has taken a permanent room upstairs at the Gallows\' End Tavern at the southeast end of town.  I think he\'s just off the reading room.', `BroadcastTextID1` = 6752, `lang1` = 1, `Probability1` = 20, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 4085;

UPDATE `npc_text` SET `text0_0` = 'While there\'s no Engineering Trainer in Brill, there is one down in the Undercity.  To get there head to the back of the Ruins of Lordaeron to the south of town and take the elevator down.  Once you get there ask an Undercity Guardian for more specific directions.', `text0_1` = 'While there\'s no Engineering Trainer in Brill, there is one down in the Undercity.  To get there head to the back of the Ruins of Lordaeron to the south of town and take the elevator down.  Once you get there ask an Undercity Guardian for more specific directions.', `BroadcastTextID0` = 6753, `lang0` = 1, `Probability0` = 80, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Rifles, dynamite, bombs, exploding sheep... what\'s not to love?  To learn how to make these and many other exciting tools of the trade head to the Undercity, under the Ruins of Lordaeron to the south of Brill.  Take the elevators down at the back of the ruins.  Once you arrive speak to one of the Undercity Guardians about where the trainer is exactly.', `text1_1` = 'Rifles, dynamite, bombs, exploding sheep... what\'s not to love?  To learn how to make these and many other exciting tools of the trade head to the Undercity, under the Ruins of Lordaeron to the south of Brill.  Take the elevators down at the back of the ruins.  Once you arrive speak to one of the Undercity Guardians about where the trainer is exactly.', `BroadcastTextID1` = 6754, `lang1` = 1, `Probability1` = 20, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` 