UPDATE `npc_text` SET `text0_0` = 'It is Bowen Brisboise that you seek then.  You\'ll find him inside his house southwest of Brill just on the other side of the bridge at Cold Hearth Manor.', `text0_1` = 'It is Bowen Brisboise that you seek then.  You\'ll find him inside his house southwest of Brill just on the other side of the bridge at Cold Hearth Manor.', `BroadcastTextID0` = 6767, `lang0` = 1, `Probability0` = 80, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Black, grey and dark purple are the prescribed colors.  See to it that you don\'t stray onto the wrong side of fashion street friend.  Bowen Brisboise can help to see that you don\'t.  You\'ll find him inside Cold Hearth Manor on the other side of the bridge to the southwest of town.', `text1_1` = 'Black, grey and dark purple are the prescribed colors.  See to it that you don\'t stray onto the wrong side of fashion street friend.  Bowen Brisboise can help to see that you don\'t.  You\'ll find him inside Cold Hearth Manor on the other side of the bridge to the southwest of town.', `BroadcastTextID1` = 6768, `lang1` = 1, `Probability1` = 20, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em