UPDATE `npc_text` SET `text0_0` = 'Season\'s savings to you and yours!', `text0_1` = 'Season\'s savings to you and yours!', `BroadcastTextID0` = 8778, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Fresh from our farm to your plate - it\'s Smokywood Pastures wholesome goodness!', `text1_1` = 'Fresh from our farm to your plate - it\'s Smokywood Pastures wholesome goodness!', `BroadcastTextID1` = 8779, `lang1` = 0, `Probability1` = 3, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '\'Tis the season for great bargains!  Fah la la la la!', `text2_1` = '\'Tis the season for great bargains!  Fah la la la la!', `BroadcastTextID2` = 8780, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Have a wondrous Feast of Winter Veil!  Start it off right with treats from Smokywood Pastures!', `text3_1` = 'Have a wondrous Feast of Winter Veil!  Start it off right with treats from Smokywood Pastures!', `BroadcastTextID3` = 8781, `lang3` = 0, `Probability3` = 3, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Be sure to tell Greatfather Winter what secret surprise you\'d like to get this Winter Veil!', `text4_1` = 'Be sure to tell Greatfather Winter what secret surprise you\'d like to get this Winter Veil!', `BroadcastTextID4` = 8782, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Don\'t let the jingle of the bells take away from the jingle in your pocket!  Buy Smokywood Pastures treats for your Winter Veil festivities!', `text5_1` = 'Don\'t let the jingle of the bells take away from the jingle in your pocket!  Buy Smokywood Pastures treats for your Winter Veil festivities!', `BroadcastTextID5` = 8783, `lang5` = 0, `Probability5` = 3, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'If I had some chestnuts, you\'d better believe I\'d have them roasting over an open fire.  Mmmm!', `text6_1` = 'If I had some chestnuts, you\'d better believe I\'d have them roasting over an open fire.  Mmmm!', `BroadcastTextID6` = 8784, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'Don\'t forget to stock up on wrapping paper this holiday season!  Nothing says \"Wondrous Winter Veil\" like wrapped armors and weapons for your friends and family.', `text7_1` = 'Don\'t forget to stock up on wrapping paper this holiday season!  Nothing says \"Wondrous Winter Veil\" like wrapped armors and weapons for your friends and family.', `BroadcastTextID7` = 8785, `lang7` = 0, `Probability7` = 3, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11159 WHERE `ID` = 6194;

