UPDATE `npc_text` SET `text0_0` = 'Look alive, soldier! Stormpike Intelligence has reported that a master goblin engineer has been taken prisoner by the Winterax trolls. The Frostwolf dogs are actively trying to rescue him so that they may use his engineered gadgets to destroy us! Do not let that happen.', `text0_1` = '', `BroadcastTextID0` = 9077, `lang0` = 0, `Probability0` = 0, `em0_0` = 1, `em0_1` = 5, `em0_2` = 25, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'The Syndicate have been reported to be nosing around in a cave on the eastern plateau. Find out what they\'re up to, soldier! Beware of Frostwolf activity!', `text1_1` = '', `BroadcastTextID1` = 9078, `lang1` = 0, `Probability1` = 0, `em1_0` = 1, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Beware of entering Frostwolf territory, soldier. The whole damn place is booby trapped! Landmines galore! Speak with our explosives expert in the first tower on the front lines for more information. I am certain that he could teach you how to diffuse the situation.', `text2_1` = '', `BroadcastTextID2` = 9079, `lang2` = 0, `Probability2` = 0, `em2_0` = 1, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1`