UPDATE `npc_text` SET `text0_0` = 'We mustn\'t anger the Master. His is a wrath that is cruel beyond measure.', `text0_1` = 'We mustn\'t anger the Master. His is a wrath that is cruel beyond measure.', `BroadcastTextID0` = 9408, `lang0` = 0, `Probability0` = 1, `em0_0` = 1, `em0_1` = 274, `em0_2` = 0, `em0_3` = 1, `em0_4` = 2, `em0_5` = 0, `text1_0` = 'Keep your voice down, stranger. You do not want to disrupt the Master\'s meditations.', `text1_1` = 'Keep your voice down, stranger. You do not want to disrupt the Master\'s meditations.', `BroadcastTextID1` = 9409, `lang1` = 0, `Probability1` = 1, `em1_0` = 20, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Many have come to this sanctuary, few have left.', `text2_1` = 'Many have come to this sanctuary, few have left.', `BroadcastTextID2` = 9410, `lang2` = 0, `Probability2` = 1, `em2_0` = 1, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'The Lorekeeper is an ancient. He has served under our glorious Queen!', `text3_1` = 'The Lorekeeper is an ancient. He has served under our glorious Queen!', `BroadcastTextID3` = 9412, `lang3` = 0, `Probability3` = 1, `em3_0` = 1, `em3_1` = 5, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre\'Thalas.', `text4_1` = 'Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre\'Thalas.', `BroadcastTextID4` = 9466, `lang4` = 0, `Probability4` = 1, `em4_0` = 1, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him.', `text5_1` = 'Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him.', `BroadcastTextID5` = 9467, `lang5` = 0, `Probability5` = 1, `em5_0` = 1, `em5_1` = 1, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'I suspect that the imps are stealing knowledge.', `text6_1` = 'I suspect that the imps are stealing knowledge.', `BroadcastTextID6` = 9468, `lang6` = 0, `Probability6` = 1, `em6_0` = 1, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince\'s lips. The Ashbringer could be found!', `text7_1` = 'The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince\'s lips. The Ashbringer could be found!', `BroadcastTextID7` = 9469, `lang7` = 0, `Probability7` = 1, `em7_0` = 1, `em7_1` = 1, `em7_2` = 5, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 6911;

