UPDATE `npc_text` SET `text0_0` = 'Hail to da new king!', `text0_1` = '', `BroadcastTextID0` = 9455, `lang0` = 0, `Probability0` = 3, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'When I scowled at you before you became da new king... um... I was just joking.$B$BYeah!', `text1_1` = '', `BroadcastTextID1` = 9456, `lang1` = 0, `Probability1` = 3, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Dem other ogres was dumb to attack you, boss!  Dat\'s why I\'m still alive - I\'m smart and stuff!', `text2_1` = '', `BroadcastTextID2` = 9457, `lang2` = 0, `Probability2` = 3, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'We a lot cleaner than da ogres in Tanaris.  All over da desert as far as da eye can see - ogre poo.  Not here, no $g sir : ma\'am;!', `text3_1` = '', `BroadcastTextID3` = 9458, `lang3` = 0, `Probability3` = 2, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'So long as you stay here with us, you da king.  You take off, and some other ogre will take your place.  That\'s da way of da Gordok!', `text4_1` = '', `BroadcastTextID4` = 9459, `lang4` = 0, `Probability4` = 4, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'I am so smart!  S-M-R-T!', `text5_1` = '', `BroadcastTextID5` = 9460, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'Old king got dead?  That\'s unpossible!', `text6_1` = '', `BroadcastTextID6` = 9461, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'I cause you no trouble, boss.', `text7_1` = '', `BroadcastTextID7` = 9462, `lang7` = 0, `Probability7` = 3, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 6922;

