UPDATE `npc_text` SET `text0_0` = 'Where can I send you today $c?', `text0_1` = '', `BroadcastTextID0` = 10029, `lang0` = 1, `Probability0` = 25, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Though the Crossroads seems to be the center of activity in The Barrens, I prefer the quietude of Camp Taurajo.  Where shall I send you?', `text1_1` = '', `BroadcastTextID1` = 10030, `lang1` = 1, `Probability1` = 25, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Many are the paths of the Earth Mother.  Wherever you decide to travel, may she watch over you.', `text2_1` = '', `BroadcastTextID2` = 10031, `lang2` = 1, `Probability2` = 25, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Treat the wind rider well as it takes you to your destination.  May your ancestors watch over you $N.', `text3_1` = '', `BroadcastTextID3` = 10032, `lang3` = 1, `Probability3` = 25, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 7315;

