UPDATE `npc_text` SET `text0_0` = '<Narain holds an unopened envelope to his forehead.>$B$BWhat is... Mmmm... Velvet!$B$BAm I right?$B$BIf you\'re here to try and relearn a tradeskill, use the book over there...$B$B<Narain points to \"Soothsaying for Dummies.\">', `text0_1` = '', `BroadcastTextID0` = 11064, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 5, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Don\'t tell me! Shhh! You are here about the Ashbringer?!? Yes... Yes... No! My bad.$B$BWhat can I help you with, $r?$B$BIf you\'re here to try and relearn a tradeskill, use the book over there...$B$B<Narain points to \"Soothsaying for Dummies.\">', `text1_1` = '', `BroadcastTextID1` = 11065, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 22, `em1_2` = 0, `em1_3` = 1, `em1_4` = 0, `em1_5` = 6, `text2_0` = 'Narain Soothfancy, at your service! Retired engineer and master soothsayer! I can tell your future before it even happens!$B$BIf you\'re here to try and relearn a tradeskill, use the book over there...$B$B<Narain points to \"Soothsaying for Dummies.\">', `text2_1` = '', `BroadcastTextID2` = 11066, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 5, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `