UPDATE `npc_text` SET `text0_0` = 'What?! How did you sneak past my jail...er, minion out there? Well, I suppose it\'s for the best. Sales have been a little slow lately.$B$BHow may I fulfill your infernal needs, $c?', `text0_1` = NULL, `BroadcastTextID0` = 11800, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 5, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Very clever how you got in here like that, $N.$B$BWhat? Surprised that I know your name? I\'m a demon, that\'s what we do. I also know your true name, so you\'d better buy something expensive.', `text1_1` = NULL, `BroadcastTextID1` = 11862, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Here for the rod? Or, maybe you\'re simply stocking up on runes?$B$BWait a minute! Are you just trying to offload a whole bunch of junk on me?! Curse my never-ending compulsion to buy, buy, buy!', `text2_1` = NULL, `BroadcastTextID2` = 11863, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'What? No, I don\'t do armor repairs. Everlook is about a mile to the north, $g brother : sister;.$B$BNow buy something, or move along before I summon my warlock to deal with you!', `text3_1` = NULL, `BroadcastTextID3` = 11864, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = NULL, `text4_1` = NULL, `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = NULL, `text5_1` = NULL, `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = NULL, `text6_1` = NULL, `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = NULL, `text7_1` 