UPDATE `npc_text` SET `text0_0` = 'Hi, $N!  Enjoying the party?', `text0_1` = 'Hi, $N!  Enjoying the party?', `BroadcastTextID0` = 13340, `lang0` = 1, `Probability0` = 1, `em0_0` = 5, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Hey everyone, it\'s $N!', `text1_1` = 'Hey everyone, it\'s $N!', `BroadcastTextID1` = 13341, `lang1` = 1, `Probability1` = 1, `em1_0` = 4, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Word travels fast in this circle.  Thanks for restocking the supplies!', `text2_1` = 'Word travels fast in this circle.  Thanks for restocking the supplies!', `BroadcastTextID2` = 13342, `lang2` = 1, `Probability2` = 1, `em2_0` = 1, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'This party is just the best!  Don\'t you agree?', `text3_1` = 'This party is just the best!  Don\'t you agree?', `BroadcastTextID3` = 13343, `lang3` = 1, `Probability3` = 1, `em3_0` = 6, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'You should try the springpaw appetizers, they\'re to die for!', `text4_1` = 'You should try the springpaw appetizers, they\'re to die for!', `BroadcastTextID4` = 13344, `lang4` = 1, `Probability4` = 1, `em4_0` = 1, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Hmm... I think this year\'s Suntouched Special isn\'t so special afterall.  Wouldn\'t you agree, $N?', `text5_1` = 'Hmm... I think this year\'s Suntouched Special isn\'t so special afterall.  Wouldn\'t you agree, $N?', `BroadcastTextID5` = 13345, `lang5` = 1, `Probability5` = 1, `em5_0` = 1, `em5_1` = 6, `em5_2` = 0, `em5_3` = 0, `em5_4` = 500, `em5_5` = 0, `text6_0` = 'I heard a rumor that we\'re all going to go watch the battle with the scourge at the border tonight.  How delightfully wicked!', `text6_1` = 'I heard a rumor that we\'re all going to go watch the battle with the scourge at the border tonight.  How delightfully wicked!', `BroadcastTextID6` = 13346, `lang6` = 1, `Probability6` = 1, `em6_0` = 1, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'Can you believe the nerve of that Elisara Sunstriker?  Thinking that she can catch the eye of Lord Saltheril?  And did you see what she\'s wearing?  So last season.  It\'s sad, really.', `text7_1` = 'Can you believe the nerve of that Elisara Sunstriker?  Thinking that she can catch the eye of Lord Saltheril?  And did you see what she\'s wearing?  So last season.  It\'s sad, really.', `BroadcastTextID7` = 13347, `lang7` = 1, `Probability7` = 1, `em7_0` = 6, `em7_1` = 6, `em7_2` = 0, `em7_3` = 0, `em7_4` = 500, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 8760;

