UPDATE `npc_text` SET `text0_0` = 'What\'s that $T scrub : girlie;?  You want your mommy?  Well too bad.  Maybe you should pay a visit to the Thrallmar officer\'s club to get her back?', `text0_1` = '', `BroadcastTextID0` = 14020, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 6, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Do you know where you are?  This is Honor Hold, sweetheart!  Love it or get out!', `text1_1` = '', `BroadcastTextID1` = 14021, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 5, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'This isn\'t a field trip, maggot!  You\'re in the Outland now!  Shape up or take a stroll back through the portal.', `text2_1` = '', `BroadcastTextID2` = 14023, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 5, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'I have neither the time, nor the inclination, to explain things to you, scumbag!  Now do you have something important to say, or are you just here to ask me out for a drink, princess?', `text3_1` = '', `BroadcastTextID3` = 14024, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 5, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'What is your major malfunction?!', `text4_1` = '', `BroadcastTextID4` = 14025, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 5, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'I\'ve seen you prancing around.  Why don\'t you do us all a favor and just drop your gear off at the armory?', `text5_1` = '', `BroadcastTextID5` = 14026, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 1, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'Who in name of Kurdran let you through the Dark Portal?', `text6_1` = '', `BroadcastTextID6` = 14027, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 5, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'Well, well, well, what have we here?  A $T civilian : civilian;?  Isn\'t that precious?  You\'ll get no special treatment from me!', `text7_1` = '', `BroadcastTextID7` = 14028, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 6, `em7_2` = 500, `em7_3` = 5, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 8961;

