UPDATE `npc_text` SET `text0_0` = 'Did you hear that they lost total control of Murmur in the Shadow Labyrinth?!', `text0_1` = 'Did you hear that they lost total control of Murmur in the Shadow Labyrinth?!', `BroadcastTextID0` = 15795, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 6, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'They don\'t pay us enough for this.  But this ruined village sure beats skulking around inside of Auchindoun.', `text1_1` = 'They don\'t pay us enough for this.  But this ruined village sure beats skulking around inside of Auchindoun.', `BroadcastTextID1` = 15796, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I joined up because they said they\'d pay my way into the academy.  My uncle says that I can go next season!', `text2_1` = 'I joined up because they said they\'d pay my way into the academy.  My uncle says that I can go next season!', `BroadcastTextID2` = 15797, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 500, `em2_3` = 4, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Hey there, you must be the new recruit!  Good to meet you!$B$BAny word from the Shadow Labyrinth in Auchindoun on whether we\'ve regained control of Murmur yet?', `text3_1` = 'Hey there, you must be the new recruit!  Good to meet you!$B$BAny word from the Shadow Labyrinth in Auchindoun on whether we\'ve regained control of Murmur yet?', `BroadcastTextID3` = 15798, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 500, `em3_3` = 6, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'If you\'re interested, a couple of us are going into Shattrath for drinks later.', `text4_1` = 'If you\'re interested, a couple of us are going into Shattrath for drinks later.', `BroadcastTextID4` = 15799, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Interested in joining up for the leather ball league?  We play Monday through Wednesday, mostly. $B$BYou\'re welcome to join us after this shift.  We\'re going to toss it around.', `text5_1` = 'Interested in joining up for the leather ball league?  We play Monday through Wednesday, mostly. $B$BYou\'re welcome to join us after this shift.  We\'re going to toss it around.', `BroadcastTextID5` = 15800, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 6, `em5_2` = 500, `em5_3` = 1, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'I hope this place pans out as a forward base for Shadow Council operations.  I know it sounds weird, but I kind of miss the Shadow Labyrinth.', `text6_1` = 'I hope this place pans out as a forward base for Shadow Council operations.  I know it sounds weird, but I kind of miss the Shadow Labyrinth.', `BroadcastTextID6` = 15801, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 1, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '<He leans in closer.>$B$BJust between you and me, I\'m thinking about \'mustering\' out one of these nights.  You know what I mean?', `text7_1` = '<She leans in closer.>$B$BJust between you and me, I\'m thinking about \'mustering\' out one of these nights.  You know what I mean?', `BroadcastTextID7` = 15802, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 1, `em7_2` = 500, `em7_3` = 1, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 9523;

