UPDATE `npc_text` SET `text0_0` = 'What? Where am I? This isn\'t right at all! Look at you! Look at this place! It isn\'t on my list! There\'s going to be so much paperwork...$b$b<The goblin writes frantically in a small notebook.>$b$bLook, if you\'ve got nothing better to do than stand there and stare, why don\'t you go visit my cousin, Kwee Q. Peddlefeet, in one of the major cities? Says here he\'s taking care of Orgrimmar, Stormwind, Thunder Bluff, Ironforge, the Undercity, and Darnassus. Go on, get outta here!', `text0_1` = 'What? Where am I? This isn\'t right at all! Look at you! Look at this place! It isn\'t on my list! There\'s going to be so much paperwork...$b$b<The goblin writes frantically in a small notebook.>$b$bLook, if you\'ve got nothing better to do than stand there and stare, why don\'t you go visit my cousin, Kwee Q. Peddlefeet, in one of the major cities? Says here he\'s taking care of Orgrimmar, Stormwind, Thunder Bluff, Ironforge, the Undercity, and Darnassus. Go on, get outta here!', `BroadcastTextID0` = 19932, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `tex