UPDATE `npc_text` SET `text0_0` = 'Hallow\'s End is a scary holiday, but I like it!', `text0_1` = 'Hallow\'s End is a scary holiday, but I like it!', `BroadcastTextID0` = 22532, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Have you seen the Headless Horseman?  If he comes here then I\'ll fight him and steal his pumpkin!', `text1_1` = 'Have you seen the Headless Horseman?  If he comes here then I\'ll fight him and steal his pumpkin!', `BroadcastTextID1` = 23020, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I like to play in the water barrel but I\'m told it\'s not for children.', `text2_1` = 'I like to play in the water barrel, but I\'m told it\'s not for children.', `BroadcastTextID2` = 23021, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'They say the barrel and buckets are for fighting fires.  Are you a fire fighter?', `text3_1` = 'They say the barrel and buckets are for fighting fires.  Are you a fire fighter?', `BroadcastTextID3` = 23022, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'The Headless Horseman lives in the Scarlet Monastery with all the other creepy ghosts and humans.', `text4_1` = 'The Headless Horseman lives in the Scarlet Monastery with all the other creepy ghosts and humans.', `BroadcastTextID4` = 23023, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'They\'re giving candies and treats at the inn!  Guardian Grimwatch says if they don\'t give us a treat... then we get to play a trick on them!', `text5_1` = 'They\'re giving candies and treats at the inn!  Guardian Grimwatch says if they don\'t give us a treat... then we get to play a trick on them!', `BroadcastTextID