UPDATE `npc_text` SET `text0_0` = 'Ahoy, mon!  What be happenin\', ye salty \'at steppa!$B$BDis place be all chacka-chacka, ye scallywag!', `text0_1` = '', `BroadcastTextID0` = 23558, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Lookin\' mighty cris, me bucko!  Ye pillage a fat sutler?  Best ye spread da wealth... don\'t be a craven choke puppy, mon!', `text1_1` = '', `BroadcastTextID1` = 23559, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Ku ovah yonder, matey!  Dat scurvy bobo be all up inne quashie\'s face.  Dat hard-eared swab gonnna get salt, mon... gonna get keelhauled and gonna be made into a duppy, mon.', `text2_1` = '', `BroadcastTextID2` = 23560, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Issa truut, matey!  Neh tougher salts anyweh but da northsea freebootahs yahso, mon!$B$BBest not brindle s\'mady, mon.  Scuppah dat!  \'Alf eediat swabs get feh kiss da gunnah\'s dawta, mate!', `text3_1` = '', `BroadcastTextID3` = 23565, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` =