UPDATE `npc_text` SET `text0_0` = 'The land is in great upheaval!$B$BThe Dark One rides forth again with his San\'layn, the dragons fight in their great Nexus War, and the vrykul are reawakened.$B$BYour people sail north on your wooden ships to fight them and one another, and we Kalu\'ak are caught in the middle.$B$BAnd now some great evil has been done so that the land explodes with the magical power of the world. We must find a safe haven where we will have a chance to survive.$B$BThese two ambassadors make my head hurt... perhaps you can help my people, $r?', `text0_1` = '', `BroadcastTextID0` = 25378, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 12575;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'It is truly a pleasure to see you again, $n.', `BroadcastTextID0` = 25394, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '$n! I\'ve been wondering how you were. What\'s kept you?', `BroadcastTextID1` = 25446, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'I trust you\'re taking every precaution....$b$bThis is a dangerous place and I couldn\'t forgive myself if something were to happen to you.', `BroadcastTextID2` = 25447, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'We must hurry, $n. Malygos\' ruinous plans will soon be irreversible.', `BroadcastTextID3` = 25448, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'In times such as these, dear friends are invaluable.$b$bBe safe, $n. As safe as one can be in a place like this....', `BroadcastTextID4` = 25449, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'If you hadn\'t rescued me from that prison I surely would have succumbed by now.$b$bI have not forgotten....', `BroadcastTextID5` = 25450, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = 'When our duty here is behind us, I shall find a way to repay you for my rescue.', `BroadcastTextID6` = 25452, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = 'My strength is returning, slowly....$b$bI hope to be able to show you the glory of my true form soon.', `BroadcastTextID7` = 25453, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 12576;

