UPDATE `npc_text` SET `text0_0` = 'There is nothing left for us here.', `text0_1` = 'There is nothing left for us here.', `BroadcastTextID0` = 25569, `lang0` = 1, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'My family was slaughtered without mercy. Even the young.', `text1_1` = 'My family was slaughtered without mercy. Even the young.', `BroadcastTextID1` = 25570, `lang1` = 1, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'May the Lich King burn in hellfire for what he has called down upon this land.', `text2_1` = 'May the Lich King burn in hellfire for what he has called down upon this land.', `BroadcastTextID2` = 25571, `lang2` = 1, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'We are a people without a home to call our own now.', `text3_1` = 'We are a people without a home to call our own now.', `BroadcastTextID3` = 25572, `lang3` = 1, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'The Scourge are a fearless machine set to bring about the end of all life on this world.', `text4_1` = 'The Scourge are a fearless machine set to bring about the end of all life on this world.', `BroadcastTextID4` = 25573, `lang4` = 1, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'The one that they call Hellscream might be our only hope.', `text5_1` = 'The one that they call Hellscream might be our only hope.', `BroadcastTextID5` = 25574, `lang5` = 1, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'Only the Horde can save us now.', `text6_1` = 'Only the Horde can save us now.', `BroadcastTextID6` = 25575, `lang6` = 1, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6