UPDATE `npc_text` SET `text0_0` = 'Those damned peasants need to work faster! I wanna get back home to Ironforge. I surely do miss my wife and children. ', `text0_1` = '', `BroadcastTextID0` = 26670, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 5, `em0_2` = 0, `em0_3` = 1, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'The cap\'n says that as soon as Prince Arthas returns we\'ll be on our way back to Lordaeron.', `text1_1` = '', `BroadcastTextID1` = 26671, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 1, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I don\'t know what could be takin\' the young prince so long, but I don\'t think we can hold out for much longer. The cold is gettin\' to some of the soldiers.', `text2_1` = '', `BroadcastTextID2` = 26672, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 1, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 12858;

UPDATE `npc_text` SET `text0_0` = 'When we saw that the ships had been burned by those savage beasts our hearts sank. Never have I felt so helpless...', `text0_1` = '', `BroadcastTextID0` = 26674, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 1, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Rage. That\'s how I can sum up my feelings towards this whole mess. We worked our fingers to the bone trying to get through the woods to the shore only to find that we were too late. Our only way home had been destroyed.', `text1_1` = '', `BroadcastTextID1` = 26675, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 1, `em1_4` = 0, `em1_5` = 5, `text2_0` = 'Despite the hardships we\'ve had to go through in this wasteland, I believe that the young prince will see us to victory. I pray each night for his safety.', `text2_1` = '', `BroadcastTextID2` = 26676, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 1, `em2_4` = 0, `em2_5` = 1, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 12859;

UPDATE `npc_text` SET `text0_0` = '<Forgotten footman shakes his head.>$B$BWe can\'t keep this up, friend. If Prince Arthas doesn\'t return soon we will all perish.', `text0_1` = '', `BroadcastTextID0` = 26678, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 1, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'We\'ll never get these ships ready in time. The winter comes and with it our doom. I fear that the young prince has damned us all.', `text1_1` = '', `BroadcastTextID1` = 26679, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 1, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Arthas and Muradin have been gone a long time. I hope they aren\'t in danger.', `text2_1` = '', `BroadcastTextID2` = 26680, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 1, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 12860;

