UPDATE `npc_text` SET `text0_0` = 'You haven\'t heard of the \"Brew of the Month\" club?  It\'s a bunch of really cute guys that want to celebrate Brewfest all year long!  They tried to bring Brewfest back in the past, but it never lasted very long.$b$bOnce you join the club you get mailed a different brew every month!  If you like that brew, you can talk to the vendors in Ironforge to get more brew.$b$bI think you are cute enough to join the club.  You give me a few prize tokens and I\'ll give you the forms.  Then maybe we can celebrate Brewfest together, all year round!', `text0_1` = 'You haven\'t heard of the \"Brew of the Month\" club?  It\'s a bunch of really cute guys that want to celebrate Brewfest all year long!  They tried to bring Brewfest back in the past, but it never lasted very long.$b$bOnce you join the club you get mailed a different brew every month!  If you like that brew, you can talk to the vendors in Ironforge to get more brew.$b$bI think you are cute enough to join the club.  You give me a few prize tokens and I\'ll give you the forms.  Then maybe we can celebrate Brewfest together, all year round!', `BroadcastTextID0` = 26771, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 5, `em0_4` = 0, `em0_5` = 24, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` =