UPDATE `npc_text` SET `text0_0` = 'Welcome to Booty Bay, partner.  Don\'t mind DeMeza and her crew... we let the hellion run riot one day a year, Pirates\' Day, and then she leaves us in peace to go plunder the South Seas again.$B$BNow then... what can this humble servant of the Steamwheedle Cartel do for you?  Better still - what can you do for me, eh?', `text0_1` = '', `BroadcastTextID0` = 27467, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 3, `em0_2` = 0, `em0_3` = 1, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = -1 WHERE `ID` = 13062;

UPDATE `npc_text` SET `text0_0` = 'This is getting good!  It really warms the stomach!  And $N, I have to say, you\'re a sharp dressing $gfellow:lass;!', `text0_1` = '', `BroadcastTextID0` = 27468, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 7, `em0_2` = 0, `em0_3` = 11, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Yes $gsir:ma\'am;, this is quite a drink!  Quite a drink indeed!', `text1_1` = '', `BroadcastTextID1` = 27490, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 7, `em1_2` = 0, `em1_3` = 273, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Let\'s sing a song!$B$BBrew, brawl,$BBrew, brawl!$BA Dark Iron\'s life for me!$B$BHah hah!  $N, I like you!', `text2_1` = '', `BroadcastTextID2` = 27491, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 7, `em2_2` = 0, `em2_3` = 5, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Now where was I?  I yeah...  So I said to her, \"But I need you!  I need you!\"... and she just laughed and slithered away!  It\'s the honest truth, $N.  Naga can be so cruel!', `text3_1` = '', `BroadcastTextID3` = 27492, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 7, `em3_2` = 0, `em3_3` = 18, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 13063;

UPDATE `npc_text` SET `text0_0` = 'This is good stuff!  But it\'s a little weak.  I think I\'ll add a little more garlic breath to it...', `text0_1` = '', `BroadcastTextID0` = 27469, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 7, `em0_2` = 0, `em0_3` = 1, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'This is good stuff!  But I think it\'s a little flat.  Let\'s round it out with a few squishy basilisk eyeballs...', `text1_1` = '', `BroadcastTextID1` = 27487, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 7, `em1_2` = 0, `em1_3` = 1, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Not bad, not bad... But it\'s missing spice!  How about adding scorpid venom?  Yes!  That\'ll fix it right up!', `text2_1` = '', `BroadcastTextID2` = 27488, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 7, `em2_2` = 0, `em2_3` = 1, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'It\'s shaping up!  But it needs more kick.  Yep, you guessed it... Let\'s wash yesterday\'s socks in the cauldron... Mmmh, delicious!', `text3_1` = '', `BroadcastTextID3` = 27489, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 7, `em3_2` = 0, `em3_3` = 4, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 13064;

