UPDATE `npc_text` SET `text0_0` = 'I can\'t take it anymore....$b$bThey kill you, then eat you! And that\'s if you\'re lucky!', `text0_1` = 'I can\'t take it anymore....$b$bThey kill you, then eat you! And that\'s if you\'re lucky!', `BroadcastTextID0` = 27477, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'You gotta help me get outta here, $r!$b$bI don\'t wanna become like them!', `text1_1` = 'You gotta help me get outta here, $r!$b$bI don\'t wanna become like them!', `BroadcastTextID1` = 27478, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I haven\'t been able to eat or sleep since I got here.$b$bI\'m just not cut out for the Crusade....', `text2_1` = 'I haven\'t been able to eat or sleep since I got here.$b$bI\'m just not cut out for the Crusade....', `BroadcastTextID2` = 27479, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '<sob> My uncle served in the Argent Dawn.$b$bHow was he able to face these foul things?', `text3_1` = '<sob> My uncle served in the Argent Dawn.$b$bHow was he able to face these foul things?', `BroadcastTextID3` = 27480, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Every time I close my eyes I see the scourge surrounding me!$b$bI gotta get outta here....', `text4_1` = 'Every time I close my eyes I see the scourge surrounding me!$b$bI gotta get outta here....', `BroadcastTextID4` = 27481, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'I\'m going to die here... I just know it.', `text5_1` = 'I\'m going to die here... I just know it.', `BroadcastTextID5` = 27482, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_