UPDATE `npc_text` SET `text0_0` = 'We can has aged yolk?', `text0_1` = '', `BroadcastTextID0` = 34555, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Do Great Ones ever run out of bag space for shinies?', `text1_1` = '', `BroadcastTextID1` = 34556, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Why you think puppy-man hatchlings keep asking if we pity Lafoo? Lafoo talks a lot, but he\'s our friend.', `text2_1` = '', `BroadcastTextID2` = 34557, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Soo-$n, maybe you give us whistle for when we need to call you. Oki?', `text3_1` = '', `BroadcastTextID3` = 34558, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Maybe we be a $r when we grow up. Think so?', `text4_1` = '', `BroadcastTextID4` = 34559, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Are you alone because puppy-men killed your parents too?', `text5_1` = '', `BroadcastTextID5` = 34560, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 14535;

UPDATE `npc_text` SET `text0_0` = 'You should stay away from walrus-men. They could pup-nap you.', `text0_1` = '', `BroadcastTextID0` = 34561, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Kekek take you hunting. You be good bait.', `text1_1` = '', `BroadcastTextID1` = 34562, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Orcs always point and laugh at Kekek, but he get revenge one day.', `text2_1` = '', `BroadcastTextID2` = 34563, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Know what? If Kekek closes his eyes, you can\'t see him.', `text3_1` = '', `BroadcastTextID3` = 34564, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Caught three chickens for lunch. Bet you couldn\'t catch any.', `text4_1` = '', `BroadcastTextID4` = 34565, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Kekek took big-tongue hatchling\'s favorite toy. Maybe it help you get to sleep at night.', `text5_1` = '', `BroadcastTextID5` = 34566, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 11723 WHERE `ID` = 14536;

