UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Hi, babe! How do I look?', `BroadcastTextID0` = 35255, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 4, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'I missed you so much! Where have you been?$B$BAre you going to answer me, or just stand there?', `BroadcastTextID1` = 35262, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 6, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'Do you like my outfit?  It\'s for the party. I charged it to your account.', `BroadcastTextID2` = 35263, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 6, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'There was another guy just hitting on me. Oh, the nerve!$B$BWill you beat him up for me, sweetie? Thanks. Love ya!', `BroadcastTextID3` = 35264, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 5, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'I can\'t wait for the day when you rise to the top. Just think, I\'ll be able to call myself Mrs. Trade Prince$B$BNot to mention buy all that stuff I\'ve always wanted!!!', `BroadcastTextID4` = 35265, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'Be careful out there. I heard that there are Southsea pirates in the bay.$B$BHmm, maybe I should go check for myself...', `BroadcastTextID5` = 35266, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 1, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = 'Can we go on a nice, romantic picnic on top of Mount Kajaro?$B$BMake sure you pickup my favorite champagne!', `BroadcastTextID6` = 35267, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 6, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = 'You\'ve got a miscievious look in your eye. What have you been up to, babe?$B$BWell?', `BroadcastTextID7` = 35268, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 6, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 14681;

