UPDATE `npc_text` SET `text0_0` = 'I adore you! You believe me? Right, baby?', `text0_1` = '', `BroadcastTextID0` = 35261, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 17, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Sweetie, where have you been? You know how worried I get when you don\'t check in with me!', `text1_1` = '', `BroadcastTextID1` = 35269, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 6, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'What do you think of my abs, baby? I just got back from the gym.$B$BI am one fine piece of meat!', `text2_1` = '', `BroadcastTextID2` = 35270, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 23, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Those other women are just friends, baby.', `text3_1` = '', `BroadcastTextID3` = 35271, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'I like what you\'re wearing!', `text4_1` = '', `BroadcastTextID4` = 35272, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'I know that I promised you last night, and the night before that, but I\'m taking you out someplace really nice tomorrow night!', `text5_1` = '', `BroadcastTextID5` = 35273, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 1, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'I heard that some Southsea pirates pulled into dock earlier. Be careful if you go into town!$B$BThey even have women pirates! Hmm, maybe I should go check it out myself? Just to make sure it\'s safe for you out there, baby.', `text6_1` = '', `BroadcastTextID6` = 35275, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 1, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'How\'s my hot, company executive girlfriend today? With the way you run things around here, I think that any day now we\'ll be calling you Trade Princess $N!$B$BI cannot wait! I\'m gonna spend my days at the gym and working on my tan by the pool.', `text7_1` = '', `BroadcastTextID7` = 35276, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 6, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 14683;

