UPDATE `npc_text` SET `text0_0` = 'Good day, $N.  If you require my services as an auctioneer, I regret to inform you: no.  Only grand master engineers possess the minimum intellectual capacity to interface with my superior functions.$b$bMore importantly, why are you still talking to me?', `text0_1` = '', `BroadcastTextID0` = 35876, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 12340 WHERE `ID` = 14764;

UPDATE `npc_text` SET `text0_0` = 'Kalytha - you\'re still alive! Find some cover, there\'s no end to these ... things!', `text0_1` = '', `BroadcastTextID0` = 35884, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Am I still bleeding? I can\'t ... I can\'t keep this up much longer. Have you seen any of the archmages?', `text1_1` = '', `BroadcastTextID1` = 35885, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Hmph. I suppose these are the consequences of magic. You reap what you sew ... Elune help us all.', `text2_1` = '', `BroadcastTextID2` = 35886, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Kalytha! Archmage Selwyn was looking for you. She should be nearby...', `text3_1` = '', `BroadcastTextID3` = 35887, `lang3` = 0, `Probability3` = 2, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'These creatures ... so many of them. So many dead! Look at Azshara burn. What have the highborne done?', `text4_1` = '', `BroadcastTextID4` = 35888, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Why didn\'t I flee with the others? They\'ve got the academy surrounded. We\'re trapped here.', `text5_1` = '', `BroadcastTextID5` = 35889, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 14766;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'I\'ve got to keep the arcane wards charged.', `BroadcastTextID0` = 35890, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'My strength ... is beginning ... to falter. Kalytha, please tell me the Archmages have a backup plan...', `BroadcastTextID1` = 35891, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'I can\'t maintain this shield much longer. Kalytha - are any of us going to survive this?', `BroadcastTextID2` = 35892, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'More of these creatures! Where are they coming from? What\'s going on in the capital?', `BroadcastTextID3` = 35893, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'Kalytha! Hurry - Archmage Selwyn wanted to see you, she said it was urgent. Maybe we can win this thing?', `BroadcastTextID4` = 35894, `lang4` = 0, `Probability4` = 2, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'It\'s all I can do to keep these wards up. Find one of the Archmages, Kalytha! I feel like I\'m about to collapse...', `BroadcastTextID5` = 35895, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 14767;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Kalytha ... it is done. The Sarcen Stone is fully charged and is already diverting energy from the portal. Are you still the incredible swimmer I knew those many years ago? The stone must not be found by either the demons or our \"beloved\" Queen.$B$BSwim to the bottom of the lake, Kalytha, and bury the stone deep under the center arch. Hopefully the demonic invaders will not discover it when they raze the surrounding temple. Go!', `BroadcastTextID0` = 35897, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 14768;

