UPDATE `npc_text` SET `text0_0` = 'Surprised to see an orc here? Don\'t be.$b$bThe forsaken need watching. If we\'d been paying closer attention from the start, maybe the Wrath Gate wouldn\'t have happened.', `text0_1` = 'Surprised to see an orc here? Don\'t be.$b$bThe forsaken need watching. If we\'d been paying closer attention from the start, maybe the Wrath Gate wouldn\'t have happened.', `BroadcastTextID0` = 36294, `lang0` = 1, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Hope you\'re not looking for those abominations. The apothecaries can\'t be trusted, and that means none of their little constructs patrolling the halls. We\'re here to keep things safe.', `text1_1` = 'Hope you\'re not looking for those abominations. The apothecaries can\'t be trusted, and that means none of their little constructs patrolling the halls. We\'re here to keep things safe.', `BroadcastTextID1` = 36295, `lang1` = 1, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Lok\'tar. Don\'t try anything suspicious around here. If these undead are going to be part of the Horde, they\'re going to mind themselves under our watch.', `text2_1` = 'Lok\'tar. Don\'t try anything suspicious around here. If these undead are going to be part of the Horde, they\'re going to mind themselves under our watch.', `BroadcastTextID2` = 36296, `lang2` = 1, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_