UPDATE `npc_text` SET `text0_0` = 'What\'s wrong, bonebag? Looking for someone else? I\'m all you\'ve got now, so if you want something, make it quick.', `text0_1` = 'What\'s wrong, bonebag? Looking for someone else? I\'m all you\'ve got now, so if you want something, make it quick.', `BroadcastTextID0` = 36297, `lang0` = 1, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I bet you rotters thought you were pretty clever at the Wrath Gate, didn\'t you? Playtime\'s over. We\'re here to make sure you don\'t try anything.', `text1_1` = 'I bet you rotters thought you were pretty clever at the Wrath Gate, didn\'t you? Playtime\'s over. We\'re here to make sure you don\'t try anything.', `BroadcastTextID1` = 36307, `lang1` = 1, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'I\'ll tell you what you need to know, but I don\'t have to like it. We\'re watching you and your kind.', `text2_1` = 'I\'ll tell you what you need to know, but I don\'t have to like it. We\'re watching you and your kind.', `BroadcastTextID2` = 36308, `lang2` = 1, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` =