UPDATE `npc_text` SET `text0_0` = 'Thoth\'al amun Ree\'thael vormos! Vormos! Vormos!', `text0_1` = '', `BroadcastTextID0` = 39714, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 5, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Al\'tha, Al\'tha bormaz. Ni bormaz ta\'thall? It comes, it walks in flames, $r!', `text1_1` = '', `BroadcastTextID1` = 39715, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 6, `em1_2` = 0, `em1_3` = 5, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'The shadow sees. Bo\'al lal arwi C\'toth. The end comes, cloaked in silent fire.', `text2_1` = '', `BroadcastTextID2` = 39716, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 6, `em2_2` = 0, `em2_3` = 5, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Mar\'kowa tallol ye\'tarin, it knows, it knows.', `text3_1` = '', `BroadcastTextID3` = 39717, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Fear broils forth from the heart of the infinite. Don\'t make me look! I\'ve seen more than I can stand!', `text4_1` = '', `BroadcastTextID4` = 39718, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 274, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'We are nothing. Tulall par\'okoth. Far\'al, ka\'kar. The void devours.', `text5_1` = '', `BroadcastTextID5` = 39719, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 274, `em5_2` = 0, `em5_3` = 1, `em5_4` = 0, `em5_5` = 0, `text6_0` = '<The Twilight Servitor gurgles at you, white spittle foaming and bubbling from his mouth.>', `text6_1` = '', `BroadcastTextID6` = 39720, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 274, `em6_2` = 0, `em6_3` = 21, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'H\'thon, the column of darkness stretching beyond sight. H\'thon marwol qualar: the infinite grasp of night.', `text7_1` = '', `BroadcastTextID7` = 39721, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 430, `em7_2` = 0, `em7_3` = 5, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 15711;

