UPDATE `npc_text` SET `text0_0` = 'You smell somethin\'?', `text0_1` = '', `BroadcastTextID0` = 39768, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 6, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I\'d lend a hand, but I\'ve got... chain rash. I\'ll just hang back a little.', `text1_1` = '', `BroadcastTextID1` = 39769, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'You\'re one unusual $c, $N. I don\'t mean that it a negative way. I\'m just sayin\', you\'re kinda funny.', `text2_1` = '', `BroadcastTextID2` = 39770, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 1, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'How long was I hanging back there? It felt like days.', `text3_1` = '', `BroadcastTextID3` = 39771, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'I don\'t recommend hanging from a chain like that. But, to be honest, it did great things for my hair.', `text4_1` = '', `BroadcastTextID4` = 39772, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 1, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Ogres.$B$BI hate ogres.', `text5_1` = '', `BroadcastTextID5` = 39773, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 274, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'Do you always talk so much when there\'s stuff to kill?', `text6_1` = '', `BroadcastTextID6` = 39774, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 5, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'Less yap flappin\'. More ogre thwappin\'. Deal?', `text7_1` = '', `BroadcastTextID7` = 39775, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 25, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 15733;

