UPDATE `npc_text` SET `text0_0` = 'Heya, $g dude : toots;! The word is that you\'re gunning for the Trade Prince\'s job.$B$BThat true?', `text0_1` = '', `BroadcastTextID0` = 40289, `lang0` = 0, `Probability0` = 1, `em0_0` = 1, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I\'d like to punch that Chip right in the kisser! I\'d also like to kiss that Candy right in the kisser, too!', `text1_1` = '', `BroadcastTextID1` = 40296, `lang1` = 0, `Probability1` = 1, `em1_0` = 15, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Did someone say, party?', `text2_1` = '', `BroadcastTextID2` = 40297, `lang2` = 0, `Probability2` = 1, `em2_0` = 6, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'This Kaja\'Cola thing\'s got me thinking. Do we really want the competition to have ideas?', `text3_1` = '', `BroadcastTextID3` = 40298, `lang3` = 0, `Probability3` = 1, `em3_0` = 6, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 15829;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Hiya, $g babe : hon;! What\'s this I hear about you and $g Candy : Chip;?', `BroadcastTextID0` = 40291, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 1, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'Nice day for digging up the last known deposits of kaja\'mite in the world, wouldn\'t you say, $N?', `BroadcastTextID1` = 40292, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 1, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'Isn\'t it weird how kaja\'mite made us smart thousands of years ago, but it doesn\'t seem to be having any effect on our trolls?', `BroadcastTextID2` = 40293, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 6, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'Distilling Kaja\'Cola out of kaja\'mite was a stroke of pure genius on your part, $N. The Trade Prince has got to be worried that you\'re going to take his title!', `BroadcastTextID3` = 40294, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 1, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 15831;

