UPDATE `npc_text` SET `text0_0` = 'I can\'t do business with you, $c. Warchief\'s Orders.', `text0_1` = 'I can\'t do business with you, $c. Warchief\'s Orders.', `BroadcastTextID0` = 43504, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I have nothing I\'m allowed to sell to you.', `text1_1` = 'I have nothing I\'m allowed to sell to you.', `BroadcastTextID1` = 43505, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'Get lost, $c! I don\'t want the enforcers to see me doing business with you...', `text2_1` = 'Get lost, $c! I don\'t want the enforcers to see me doing business with you...', `BroadcastTextID2` = 43506, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'Go away, I don\'t want the Warchief to find out I\'ve been talking to the Horde.', `text3_1` = 'Go away, I don\'t want the Warchief to find out I\'ve been talking to the Horde.', `BroadcastTextID3` = 43507, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'My goods aren\'t for sale to the Horde. Don\'t like it? Take it up with the Warchief!', `text4_1` = 'My goods aren\'t for sale to the Horde. Don\'t like it? Take it up with the Warchief!', `BroadcastTextID4` = 43508, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Warchief Mor\'ghor ordered us not to do business with the Horde.$B$B<The merchant spits on the ground, infuriated, but refuses to speak any more on the subject.>', `text5_1` = 'Warchief Mor\'ghor ordered us not to do business with the Horde.$B$B<The merchant spits on the ground, infuriated, but refuses to speak any more on the subject.>', `BroadcastTextID5` = 43509, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `e