UPDATE `npc_text` SET `text0_0` = 'Go ahead, $r. Give me an excuse.', `text0_1` = '', `BroadcastTextID0` = 43533, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 5, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'Warchief Mor\'ghor runs the show here. Don\'t forget it.', `text1_1` = '', `BroadcastTextID1` = 43534, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 274, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '<The enforcer\'s eyes flash red.>$B$BI hope your pathetic Horde tries to attack us. I am itching to shed some blood, $c!', `text2_1` = '', `BroadcastTextID2` = 43535, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 25, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'The fury! The power! I have never felt so strong in all my life.$B$BSoon, ALL the Dragonmaw will feel as I do.', `text3_1` = '', `BroadcastTextID3` = 43536, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 15, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Don\'t try anything funny, $c.$B$B<The enforcer tenses his fingers near the hilt of his blade, eager for you to make a scene.>', `text4_1` = '', `BroadcastTextID4` = 43537, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 25, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Warchief Mor\'ghor will make the Dragonmaw great again!$B$BWe have no need for your pathetic Horde.', `text5_1` = '', `BroadcastTextID5` = 43538, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 11, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 16430;

