UPDATE `npc_text` SET `text0_0` = 'Do I know you? No? Welcome to the Twilight\'s Hammer.', `text0_1` = 'Do I know you? No? Welcome to the Twilight\'s Hammer.', `BroadcastTextID0` = 47997, `lang0` = 0, `Probability0` = 1, `em0_0` = 6, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'The end days are nigh!', `text1_1` = 'The end days are nigh!', `BroadcastTextID1` = 47998, `lang1` = 0, `Probability1` = 1, `em1_0` = 1, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = 'There\'s a little blood on your armor there. Are you okay?', `text2_1` = 'There\'s a little blood on your armor there. Are you okay?', `BroadcastTextID2` = 47999, `lang2` = 0, `Probability2` = 1, `em2_0` = 25, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = 'New recruit? Have you reported to the commander yet?', `text3_1` = 'New recruit? Have you reported to the commander yet?', `BroadcastTextID3` = 48000, `lang3` = 0, `Probability3` = 1, `em3_0` = 6, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = 'Hey, you haven\'t seen Grom-Grom have you? Orc, about this tall. No?$B$BHmm. No one\'s seen him for a while. Probably went a.w.o.l.', `text4_1` = 'Hey, you haven\'t seen Grom-Grom have you? Orc, about this tall. No?$B$BHmm. No one\'s seen him for a while. Probably went a.w.o.l.', `BroadcastTextID4` = 48001, `lang4` = 0, `Probability4` = 1, `em4_0` = 6, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = 'Something big\'s brewing at the Withering to the east.$B$BWhatever it is, I hope that it\'ll be over soon and we get restationed somewhere nicer.', `text5_1` = 'Something big\'s brewing at the Withering to the east.$B$BWhatever it is, I hope that it\'ll be over soon and we get restationed somewhere nicer.', `BroadcastTextID5` = 48002, `lang5` = 0, `Probability5` = 1, `em5_0` = 1, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = 'Keep your eyes peeled. They say that freak that was attacking people earlier might still be around.', `text6_1` = 'Keep your eyes peeled. They say that freak that was attacking people earlier might still be around.', `BroadcastTextID6` = 48003, `lang6` = 0, `Probability6` = 1, `em6_0` = 1, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = 'Isn\'t it weird that we\'re keeping Magatha Grimtotem captive here? Good thing all of her totems were destroyed.$B$BI even heard that she poisoned Cairne Bloodhoof. Wish she were on our side.', `text7_1` = 'Isn\'t it weird that we\'re keeping Magatha Grimtotem captive here? Good thing all of her totems were destroyed.$B$BI even heard that she poisoned Cairne Bloodhoof. Wish she were on our side.', `BroadcastTextID7` = 48004, `lang7` = 0, `Probability7` = 1, `em7_0` = 6, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 17319;

