UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'Yeah? Whadya want?', `BroadcastTextID0` = 49174, `lang0` = 0, `Probability0` = 1, `em0_0` = 6, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'I don\'t talk to no $g scrub : trash;!', `BroadcastTextID1` = 49175, `lang1` = 0, `Probability1` = 1, `em1_0` = 274, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'You\'re not quite in my league, honey.', `BroadcastTextID2` = 49176, `lang2` = 0, `Probability2` = 1, `em2_0` = 25, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'I didn\'t talk to you back in school and I\'m sure not going to start now.', `BroadcastTextID3` = 49177, `lang3` = 0, `Probability3` = 1, `em3_0` = 1, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'That\'s an interesting... \"outfit\" you\'re wearing.', `BroadcastTextID4` = 49178, `lang4` = 0, `Probability4` = 1, `em4_0` = 11, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'Yes. I\'d love a refill. Fetch one and be quick about it.', `BroadcastTextID5` = 49179, `lang5` = 0, `Probability5` = 1, `em5_0` = 1, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = 'This is the Trade Prince\'s party, sweetie. Invite only!', `BroadcastTextID6` = 49180, `lang6` = 0, `Probability6` = 1, `em6_0` = 396, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '$N, right? Word of advice: don\'t let the Trade Prince catch you around here. He knows you\'re after his job.$B$BEveryone knows.', `BroadcastTextID7` = 49181, `lang7` = 0, `Probability7` = 1, `em7_0` = 6, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 17549;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'A mook?! I don\'t speak to brutes. How dare you!', `BroadcastTextID0` = 49182, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 14, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'What are we calling you things these days? Brutes? Hobgoblins?$B$BI can\'t keep it straight. Get out of here.', `BroadcastTextID1` = 49183, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 6, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'You\'re big and strong. But you need a bath. Go jump in the pool.', `BroadcastTextID2` = 49184, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 11, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'Oh no you did not just talk to me!', `BroadcastTextID3` = 49185, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 274, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'What smells around here? Oh, that\'d be you.$B$BBeat it!', `BroadcastTextID4` = 49186, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 6, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'What\'s your name?$B$BI guess it\'s a good thing you brutes can\'t talk. Otherwise, I\'d have to tell the Trade Prince how you annoyed me.$B$BNow scram!', `BroadcastTextID5` = 49187, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 25, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = 'Touch me one more time and I\'ll make sure that they send you to the Undermine!', `BroadcastTextID6` = 49188, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 15, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = 'Oh, you\'re just disgusting! Why is it always the ugly ones that try to pickup on me?!', `BroadcastTextID7` = 49189, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 274, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 17550;

UPDATE `npc_text` SET `text0_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$B$G Papa : Mama;...?', `text0_1` = '', `BroadcastTextID0` = 49198, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BI hunger... therefore, I am.', `text1_1` = '', `BroadcastTextID1` = 49216, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BWhat does \"$c\" mean? Are you the goblin $g patriarch : matriarch;?', `text2_1` = '', `BroadcastTextID2` = 49217, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BThey call you $N. Is this your unique signifier, or is it an honorary title?', `text3_1` = '', `BroadcastTextID3` = 49220, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BGreetings. I recently emerged from an egg. You?', `text4_1` = '', `BroadcastTextID4` = 49224, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BIs it true that you cook your meat? Curious.', `text5_1` = '', `BroadcastTextID5` = 49225, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BYou lack a helmet. Does this diminish your intellectual capacities?', `text6_1` = '', `BroadcastTextID6` = 49226, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '<To your astonishment, the Raptor hatchling is able to communicate with you.>$B$BThe ends of your fingers are dull and round. Is this why you carry around other implements for use in combat?$B$BHow interesting.', `text7_1` = '', `BroadcastTextID7` = 49227, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 17552;

UPDATE `npc_text` SET `text0_0` = '$N?! What are you still doing here?$B$BYou have to get off of the island, or better yet, into one of my Town-In-A-Boxes!$B$BDon\'t wait too long, my $g boy : girl;! The Cataclysm is upon us!', `text0_1` = '', `BroadcastTextID0` = 49231, `lang0` = 0, `Probability0` = 1, `em0_0` = 5, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = '', `BroadcastTextID1` = 0, `lang1` = 0, `Probability1` = 0, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 17554;

