UPDATE `npc_text` SET `text0_0` = 'I\'m here to make sure the job gets done on time.$b$bBooty Bay is still trying to recover from the tidal wave!$b$bThe last thing we need is a horde of rampaging trolls, zombie trolls, poisonous serpents or crazed panthers attacking us.', `text0_1` = '', `BroadcastTextID0` = 51724, `lang0` = 0, `Probability0` = 1, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = 'I\'m here to represent Booty Bay\'s interest in this expedition.$b$bIf things go bad, Booty Bay is in trouble.$b$bWe are still recovering from the events of the cataclysm.', `text1_1` = '', `BroadcastTextID1` = 51725, `lang1` = 0, `Probability1` = 1, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = '', `BroadcastTextID2` = 0, `lang2` = 0, `Probability2` = 0, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = '', `BroadcastTextID3` = 0, `lang3` = 0, `Probability3` = 0, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = '', `BroadcastTextID4` = 0, `lang4` = 0, `Probability4` = 0, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = '', `BroadcastTextID5` = 0, `lang5` = 0, `Probability5` = 0, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = '', `BroadcastTextID6` = 0, `lang6` = 0, `Probability6` = 0, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = '', `BroadcastTextID7` = 0, `lang7` = 0, `Probability7` = 0, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 18024;

UPDATE `npc_text` SET `text0_0` = '', `text0_1` = 'In the nature of all things is the will to survive.', `BroadcastTextID0` = 51731, `lang0` = 0, `Probability0` = 2, `em0_0` = 0, `em0_1` = 0, `em0_2` = 0, `em0_3` = 0, `em0_4` = 0, `em0_5` = 0, `text1_0` = '', `text1_1` = 'What is war, but the preservation of life? Just as the seed struggles to push out of the soil, so do we fight for our own existence.', `BroadcastTextID1` = 52342, `lang1` = 0, `Probability1` = 2, `em1_0` = 0, `em1_1` = 0, `em1_2` = 0, `em1_3` = 0, `em1_4` = 0, `em1_5` = 0, `text2_0` = '', `text2_1` = 'Hello there! You\'re really growing on me.', `BroadcastTextID2` = 51730, `lang2` = 0, `Probability2` = 1, `em2_0` = 0, `em2_1` = 0, `em2_2` = 0, `em2_3` = 0, `em2_4` = 0, `em2_5` = 0, `text3_0` = '', `text3_1` = 'Will we win this war? Only thyme will tell.', `BroadcastTextID3` = 52344, `lang3` = 0, `Probability3` = 1, `em3_0` = 0, `em3_1` = 0, `em3_2` = 0, `em3_3` = 0, `em3_4` = 0, `em3_5` = 0, `text4_0` = '', `text4_1` = 'It\'s sweltering down here. Did someone tell them to turnip the heat?', `BroadcastTextID4` = 52345, `lang4` = 0, `Probability4` = 1, `em4_0` = 0, `em4_1` = 0, `em4_2` = 0, `em4_3` = 0, `em4_4` = 0, `em4_5` = 0, `text5_0` = '', `text5_1` = 'I like you! Weed make anise pear.', `BroadcastTextID5` = 52347, `lang5` = 0, `Probability5` = 1, `em5_0` = 0, `em5_1` = 0, `em5_2` = 0, `em5_3` = 0, `em5_4` = 0, `em5_5` = 0, `text6_0` = '', `text6_1` = 'Some people say I\'m corny, but I think I\'m rather sage.', `BroadcastTextID6` = 52348, `lang6` = 0, `Probability6` = 1, `em6_0` = 0, `em6_1` = 0, `em6_2` = 0, `em6_3` = 0, `em6_4` = 0, `em6_5` = 0, `text7_0` = '', `text7_1` = 'Oh, it\'s you again! Do you think we\'ll be able to mustard up the forces we need?', `BroadcastTextID7` = 52349, `lang7` = 0, `Probability7` = 1, `em7_0` = 0, `em7_1` = 0, `em7_2` = 0, `em7_3` = 0, `em7_4` = 0, `em7_5` = 0, `VerifiedBuild` = 0 WHERE `ID` = 18025;

