-- ----------------------------
-- Insert data quest_offer_reward
-- ----------------------------

INSERT INTO `quest_offer_reward`(`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (10496, 5, 1, 0, 0, 0, 0, 0, 0, 'I can\'t believe our lives are all but forfeit all because of a stupid medallion! And you\'re sure Anthion mentioned Bodley?$B$BWell, you\'ve done your job so let\'s get your reward out of the way.', 0);

INSERT INTO `quest_offer_reward`(`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (10497, 6, 1, 0, 0, 0, 0, 0, 0, 'This curse was bestowed upon us but for a mere medallion. Lord Valthalak certainly knows how to hold a grudge.$B$BWe\'ll endeavor to find the remaining pieces - hopefully before I meet an untimely demise. But before that, let us see about your reward.', 0);

INSERT INTO `quest_offer_reward`(`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (10498, 1, 2, 0, 0, 0, 0, 0, 0, 'I\'m going to miss you, $N. I owe you such a debt of gratitude; I think I\'ll never be able to repay it.$B$BI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.', 0);

INSERT INTO `quest_offer_reward`(`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (10499, 1, 2, 0, 0, 0, 0, 0, 0, 'I will truly miss you, $N. There is a debt that I owe you, which I may never be able to repay.$B$BEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!', 0);

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You need some Crab Cakes, do you? Well I might be able to cook some up for you...', `VerifiedBuild` = 12340 WHERE `ID` = 5;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good work, friend. You have earned your pay well. Who knows, perhaps Westfall will prosper once again.', `VerifiedBuild` = 12340 WHERE `ID` = 9;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I see you\'ve been busy! You have our thanks, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 11;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. My scout witnessed your valiant acts. You are proving yourself quite well so far.', `VerifiedBuild` = 12340 WHERE `ID` = 12;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your worth to The People\'s Militia has been validated by your brave acts thus far.', `VerifiedBuild` = 12340 WHERE `ID` = 13;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland. But there is hope for Westfall yet. As proven by your valor in battle, it is obvious to me that you serve our cause with honor. It is with great pride that I induct thee into The People\'s Militia. May the Light shine upon you.', `VerifiedBuild` = 12340 WHERE `ID` = 14;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks, $N! And come back if you want to trade again.', `VerifiedBuild` = 12340 WHERE `ID` = 16;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done $N, you\'ve proven your worth once again! The caps will be an interesting study, yon verily!$B$BAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...$B$BIf you are a skilled alchemist, then perhaps we might have some additional business to conduct. Regardless, I thank you for your assistance!', `VerifiedBuild` = 12340 WHERE `ID` = 17;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Tharil\'zun was a vicious, crafty orc. Well done - I\'m sure he didn\'t go down easy. Here is your reward, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 19;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These are just perfect, $N! Thank you so much. Farmer Saldean and I are going to feast tonight. And here is a little something for you, for the hard work. You didn\'t think I was going to let a $C like you go hungry, did you?', `VerifiedBuild` = 12340 WHERE `ID` = 22;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the paw of Ursangous! Your skill is impressive, $C; he is credited with numerous kills. The crescent on his paw is no doubt a sign that he was trained by the night elves that skulk about Ashenvale. Ursangous is... was one of the mightiest bears you\'d find in these parts. To have bested such a creature is a testament to your will and resolve.$b$bYour ancestors would be proud!', `VerifiedBuild` = 12340 WHERE `ID` = 23;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A victory for $N in the Ashenvale Hunt! Well done - the head of Shadumbra is a fitting trophy to claim for such an impressive fight, no doubt.$b$bShadumbra\'s savagery was well known throughout the post here. Any trip to the west, especially on foot trying to get out to the Zoram Strand, was wrought with danger because of this tiger. Thanks to you, this danger has abated.', `VerifiedBuild` = 12340 WHERE `ID` = 24;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yeah, I heard that someone tore up the lake out there like a dust devil through the Barrens. From the sound of it too, we might be able to set up a possible observation area out there to keep an eye on our Alliance friends. Well, that is if we can keep it on the down low...$B$BLooks like you ended up being quite useful after all; the transports between here and Stonetalon should have an easier time of it. Take this - you\'ve earned it.', `VerifiedBuild` = 12340 WHERE `ID` = 25;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This report... I\'ve dealt with these beasts before. Fizzledowser was wise to send this. and you, to me.$b$bThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face. Familiarize yourself with this name, $N: silithid. The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.$b$bIf only we were smart enough to see that before.', `VerifiedBuild` = 12340 WHERE `ID` = 32;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Finally the menace is laid to rest! Thank you, $N, you have done me a great service. The garden shall be in full bloom this season!', `VerifiedBuild` = 12340 WHERE `ID` = 34;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, murlocs have settled in and around the streams of eastern Elwynn. We don\'t know why they are here, but they are aggressive and at least semi-intelligent.', `VerifiedBuild` = 12340 WHERE `ID` = 35;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That Verna was always such a sweet lass. We\'ll miss her here in Westfall but between you and me, she\'s a city girl at heart and Stormwind will suit her just fine. But enough gossip! Now we can make Westfall Stew!', `VerifiedBuild` = 12340 WHERE `ID` = 36;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That Okra will thicken up this broth nicely! Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts. And we\'re done! For all your help, $N, I want you to take today\'s first batch of Westfall Stew!', `VerifiedBuild` = 12340 WHERE `ID` = 38;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I spoke with Remy. I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.$B$BYour concerns are noted, but unless I receive a military report of a murloc threat, we can\'t afford to send more troops east.', `VerifiedBuild` = 12340 WHERE `ID` = 40;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have the fins? Great! Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I\'d like to tell him that it\'s becoming under control.$b$bYour actions have helped realize that.', `VerifiedBuild` = 12340 WHERE `ID` = 46;

