UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks a lot for the help, $N. Something in the forest must be making these animals so bold.$B$BWhatever it is, I hope it stays there.', `VerifiedBuild` = 12340 WHERE `ID` = 52;

UPDATE `quest_offer_reward` SET `Emote1` = 94, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Aged in the barrel, filtered through coal$BIt passes your lips and right through your soul.$BSo lets us drink now, a toast to you$BAnd me while we\'re at it, Grimbooze Thunderbrew!', `VerifiedBuild` = 12340 WHERE `ID` = 53;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well, it says here that you\'ve been awarded Acting Deputy Status with the Stormwind Marshals. Congratulations.$b$bAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$b$bIt\'s hard to keep track of politics in these dark days...', `VerifiedBuild` = 12340 WHERE `ID` = 54;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Morbent Fel has been defeated. The dark riders are still at large, but a small piece of that which I had hoped beyond hope has come to pass.$b$bYou have done the impossible, and your deeds will forever live in the legends of Duskwood.$b$bGo, $N. And perhaps, one day, fate may bring you back to me...', `VerifiedBuild` = 12340 WHERE `ID` = 55;

