UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, $N, for your bravery and dedication. May the Light shine upon your ways.', `VerifiedBuild` = 12340 WHERE `ID` = 58;

