UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank goodness! That pig was getting so big she\'d have eaten our whole crop! Thank you, $N.$b$bNow, do either of these suit you?', `VerifiedBuild` = 12340 WHERE `ID` = 88;

