UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, a nice clutch of legs you have there! Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...$B$BAnd, although Dusky Crab Cakes are my specialty and I won\'t give out the recipe, here\'s the recipe for a dish that\'s almost as good.', `VerifiedBuild` = 12340 WHERE `ID` = 93;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I knew it! Fine work, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 97;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 16, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I know, $N: Stalvan is dead. I sensed a wave of hope ripple through the tainted forest. Once and for all, Duskwood is free from his blood thirst. My joy is hampered by thoughts of those who fell prey to the horrible beast. Nonetheless, you are a brave and cunning $c.', `VerifiedBuild` = 12340 WHERE `ID` = 98;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your persistence is commendable. With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone. Cheers to you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 99;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very wise of you, $N. This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond. When you feel threatened, hold this totem and take comfort in its magical aura. Be brave, fair $C. You will need all the courage you can muster for I see much bloodshed in your future.', `VerifiedBuild` = 12340 WHERE `ID` = 101;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. With valiant adventurers such as yourself fighting alongside The People\'s Militia, Westfall just might return to the prosperous breadbasket it once was. Please accept this in recognition of your tireless efforts.', `VerifiedBuild` = 12340 WHERE `ID` = 102;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done it! Araj... the lich is finally defeated!$B$BYou\'ve done a tremendous service to the Horde on this day, $N. Your bravery and perseverance are a testament to what it means to be a true hero. Please - accept this as a token for all to see and know that you have delivered the Horde a victory for the ages!', `VerifiedBuild` = 12340 WHERE `ID` = 105;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My heart goes out to those two poor souls, Maybell and Tommy Joe. I remember being young and in love, once.$b$bThere must be something I can do to help them! Let me think...', `VerifiedBuild` = 12340 WHERE `ID` = 107;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so my friend sent you here? How kind. $B$BWell the Stormwind Monarchy has abandoned our cause. Now it is up to the People\'s Militia to keep the land free from corruption. If our cause interests you, I can put your combat skills to use in the name of freedom.', `VerifiedBuild` = 12340 WHERE `ID` = 109;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'While our families are feuding, Tommy Joe and Maybell don\'t have much of a future, but... maybe we can get them together for just a little while.$B$BHm, what can we do...', `VerifiedBuild` = 12340 WHERE `ID` = 111;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got them. Good show! Now, just one moment while I concoct the potion...', `VerifiedBuild` = 12340 WHERE `ID` = 112;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh...my! I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.$b$bThank you, $N. I\'ll drink this liquor as soon as I have the chance and sneak away to my love.$b$bAnd for you... please take this.', `VerifiedBuild` = 12340 WHERE `ID` = 114;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. I\'ll send these to be destroyed immediately.', `VerifiedBuild` = 12340 WHERE `ID` = 115;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A job well done, $N! I know well the roads you had to journey to procure this fine array of liquor. But my patrons will be happy once again! $b$bMy wife is quite a seamstress. Please accept this cloak she made in return for your services.', `VerifiedBuild` = 12340 WHERE `ID` = 116;

UPDATE `quest_offer_reward` SET `Emote1` = 94, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hops and Barley, yeast and malt $bThe taste-buds feel a virtual assault, $bNo need to plead, no need to beg $bFor Thunderbrew Lager comes in a keg!', `VerifiedBuild` = 12340 WHERE `ID` = 117;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'At ease, $C.$b$bMagistrate Solomon is a noble leader. His words carry great weight with me. I shall seek the counsel of the King and make the situation clear to him. Assure the good judge that he has the Stormwind Army\'s support. Reinforcements will be sent as soon as word is given from His Majesty.', `VerifiedBuild` = 12340 WHERE `ID` = 120;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for your time, $C. For your service to Lakeshire and Stormwind I reward you with these coins.$b$bNow if you\'ll excuse me, I find this correspondence somewhat of a mystery. Something is amiss in our Kingdom. I fear this is the beginning of conflict, not the end.', `VerifiedBuild` = 12340 WHERE `ID` = 121;

