UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This matter might be more complex than Stoutmantle realizes.', `VerifiedBuild` = 12340 WHERE `ID` = 135;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Edwin VanCleef. . .I know the name well. To think that a man so industrious and talented could turn into such a scoundrel unnerves me. I\'ll need further proof before I believe this.', `VerifiedBuild` = 12340 WHERE `ID` = 141;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 25, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is indeed firm proof that VanCleef is in charge. Now all we need to know is where the Defias gang is hiding out.$b$bWe\'ve had a stroke of luck while you were gone. We captured a thief trying to steal Saldean\'s wagon. He has promised to lead us to the hideout in exchange for his life. I want you to defend the traitor so he can reveal the hideout. Return to me once you have uncovered the location.', `VerifiedBuild` = 12340 WHERE `ID` = 142;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good Messenger, you have served your master well.', `VerifiedBuild` = 12340 WHERE `ID` = 143;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I do say, this is not good at all. I did not realize that Stoutmantle\'s situation was not unlike ours here in Lakeshire. What action is so important that it calls the Stormwind Army away from its people? Bah, I should not ponder aloud.$b$bHere, messenger. Accept these coins in exchange for your service to the Township. I might call upon you again.', `VerifiedBuild` = 12340 WHERE `ID` = 144;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 6, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'By the Light! The Stormwind Army retreated from Westfall. And the Guard no longer protects Darkshire? There is some treachery abound. How could this be so? $b$bOh I forgot to reward your service, $C. Here are some coins. Now excuse me. Something is amiss in Stormwind and I must get to the bottom of it.', `VerifiedBuild` = 12340 WHERE `ID` = 146;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found him? Well done, $N. He won\'t be \"collecting\" from the Elwynn Mines again!$B$BAnd this ring you found is interesting... it\'s a membership ring for the old Stonemason\'s Guild in Stormwind. Why would a lowly thief have an artisan guild ring, and why are the Defias Thieves collecting money from our mines?$B$BDifficult questions. I hope one day we\'ll have answers.', `VerifiedBuild` = 12340 WHERE `ID` = 147;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Ghost Hair Thread is what you need, is it? I\'m afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.', `VerifiedBuild` = 12340 WHERE `ID` = 148;

