UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N.  It\'ll be nice to work our crafts without hearing so many growls and snorts outside the village.', `VerifiedBuild` = 12340 WHERE `ID` = 319;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That is quite a tale you have. And lightforge iron! Not for years have I worked with such a metal. It will be an honor to craft with it again. And you must return to me later with the story of your battle against the Necromancer.$b$bBut we get ahead of ourselves. First, your weapon against Morbent Fel...', `VerifiedBuild` = 12340 WHERE `ID` = 322;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your skill in combat, $N, can not be doubted. Your resolve may yet see us through to the end of Morbent Fel!', `VerifiedBuild` = 12340 WHERE `ID` = 323;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you found them! Now let\'s get this lightforge iron hammered into something useful, eh?', `VerifiedBuild` = 12340 WHERE `ID` = 324;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, this will be proof against the fiend Morbent Fel! Well done!$b$bYou are ready. Morbent Fel will fall.', `VerifiedBuild` = 12340 WHERE `ID` = 325;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so you\'ve seen Renato? Well here you are, $G sir:madam;. A bottle of our special pinot noir. You\'ll not find its equal in all of Azeroth!', `VerifiedBuild` = 12340 WHERE `ID` = 332;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It says here that Harlan\'s business is booming. That\'s good news, but I wonder why people have need of all that armor. I\'ve heard nothing of open war... is there something the nobles aren\'t telling us?$B$BWell, thank you for bringing the request. Here\'s your payment, and I\'ll see to it that Harlan gets his supplies.', `VerifiedBuild` = 12340 WHERE `ID` = 333;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Most excellent! These are fine samples indeed!', `VerifiedBuild` = 12340 WHERE `ID` = 335;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, thank you for bringing me this fine looking stout, servant. Here\'s a copper for you. Now, out of sight with you and let me enjoy my drink!', `VerifiedBuild` = 12340 WHERE `ID` = 336;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my! This book hasn\'t rested on these shelves since before the rebuilding of Stormwind, years ago. It will have to be restored of course, it\'s in bad shape, but I would be honored to place it within our rare books collection.$B$BThank you, $N. Please accept this as payment for returning the book!', `VerifiedBuild` = 12340 WHERE `ID` = 337;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve certainly saved me a heap of trouble, $N! I can\'t thank you enough. It shouldn\'t be long now until we see Master Nesingwary\'s book in libraries throughout the world!', `VerifiedBuild` = 12340 WHERE `ID` = 338;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Metallurgy? Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech! Now...which particular book was it the good brother needed?', `VerifiedBuild` = 12340 WHERE `ID` = 343;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Mr. Sheaf is wondering where his book is? Well this is a tad embarrassing. I have the book, but I\'m still making my copy and I\'m not quite ready to give the original up!', `VerifiedBuild` = 12340 WHERE `ID` = 344;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You need what?? Maybe you haven\'t noticed, but we\'re busy fortifying Lakeshire\'s defenses and repairing damage from recent orc attacks. If you need Rethban Iron Ore, you\'ll have to get it yourself!', `VerifiedBuild` = 12340 WHERE `ID` = 345;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s the one! Thank you, $N. May the Light shine brightly upon both your body and spirit!', `VerifiedBuild` = 12340 WHERE `ID` = 346;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, splendid! I can use this ore to make my dye, and then can finish copying The Stresses of Iron.$B$BThank you, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 347;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.$b$bYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!', `VerifiedBuild` = 12340 WHERE `ID` = 349;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 11, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re kidding? Shaw wants my help again? Of all the nerve...$b$bThe Defias Brotherhood, you say? Well, you\'re certainly the bearer of wonderful news, aren\'t you? Next you\'re going to tell me that Deathwing is still alive and attacking the city.$b$bAll right, tell me everything from the beginning. And don\'t leave out something you think might not be important. I need to know it all.', `VerifiedBuild` = 12340 WHERE `ID` = 350;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Aha! So Grimand finally finished my axe! I can\'t wait to try it against some troggs and kobolds!$b$bMany thanks, $N. It was a long distance to travel for this delivery.  Here are some coins for your efforts.', `VerifiedBuild` = 12340 WHERE `ID` = 353;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Magistrate Sevren wants a report? Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.$b$bWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.', `VerifiedBuild` = 12340 WHERE `ID` = 359;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...$b$bI see the confusion on your face. Let me try to explain our... situation... to you.$b$bWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step.', `VerifiedBuild` = 12340 WHERE `ID` = 363;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have performed your bidding well, young $C. You are proving yourself to be quite an asset to The Dark Lady\'s army.', `VerifiedBuild` = 12340 WHERE `ID` = 365;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done well, $N and I thank you for your efforts.', `VerifiedBuild` = 12340 WHERE `ID` = 367;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The scales are perfect, $N. Exactly what I needed for this concoction.', `VerifiedBuild` = 12340 WHERE `ID` = 368;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, this venom will do perfectly, $N. Everything else has been added to my concoction and boiled down. Finally, I am ready to try this new deadly agent!', `VerifiedBuild` = 12340 WHERE `ID` = 369;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Captain Perrine\'s death will undoubtedly please The Dark Lady.  You have performed your duty well, $c.', `VerifiedBuild` = 12340 WHERE `ID` = 370;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Captain Vachon\'s death will slow down the Scarlet Crusade\'s advancement in Tirisfal quite a bit.  But other threats loom.', `VerifiedBuild` = 12340 WHERE `ID` = 371;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done extremely well, $C. With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all. I have a good feeling about you, comrade.', `VerifiedBuild` = 12340 WHERE `ID` = 372;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 2, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you\'ve killed him then? Pardon me in saying, but I\'m somewhat surprised. He was a peerless fighter in his younger years. Let\'s see what he finds the need to write to me about after so many years.$b$b<Baros peruses the letter.>$b$bEdwin... I see the years haven\'t changed you a bit, an idealist as ever, and a romantic. He doesn\'t care who he hurts, $N. Revenge has consumed him. But then, I\'m not sure I can blame him.', `VerifiedBuild` = 12340 WHERE `ID` = 373;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Varimathras would be proud.  You serve your leaders well, $c.', `VerifiedBuild` = 12340 WHERE `ID` = 374;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I appreciate your efforts, $N. May Slyvanas recognize your bravery one day. . . .', `VerifiedBuild` = 12340 WHERE `ID` = 375;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. This armor should help you out.$b$bHopefully, it should do you more good than the last one to wear it...', `VerifiedBuild` = 12340 WHERE `ID` = 376;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So Dextren Ward finally paid for his crimes against humanity? Good riddance to the scum I say. And cheers to you, my friend! Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles. Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny.', `VerifiedBuild` = 12340 WHERE `ID` = 377;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death? Good. Serves the cowardly Dark Iron scum right. You have done well, $C. The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest. Their families will have the peace of knowing Deepfury got the punishment he deserved. Longbraid\'s brother\'s death has been avenged.', `VerifiedBuild` = 12340 WHERE `ID` = 378;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent, the power source is yours. Now, it isn\'t completely designed for use in a science kit like that, so you\'ll only have a limited amount of time before all the data you collect will go kablooey!$B$BWhen you collect everything you need for whatever it is you are doing, bring it to me and I\'ll shut it down properly. You\'ll have at most two hours to get what you need to get done, done.$B$BIf you don\'t get it done in time, I can always sell you another power source to try again. You heard me - sell!', `VerifiedBuild` = 12340 WHERE `ID` = 379;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm, well, it\'s a start. It\'ll take a few weeks or months to fully clean out the infestation. After that, we\'ll have to get down there with some torches to burn away the webbing.$b$bYou\'ve done your duty well, $N, I\'m sure I can find something else for you to do.', `VerifiedBuild` = 12340 WHERE `ID` = 380;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'If only they listened to reason, eh, $N? Perhaps we could sit them down for reasonable discourse... ha!$b$bLight-blinded fools.', `VerifiedBuild` = 12340 WHERE `ID` = 381;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Malt is brewed, the Boars are dead$BAnd before all is done and anything said$BWe will have to fight for first dibs$BOn these savory Beer Basted Boar Ribs!', `VerifiedBuild` = 12340 WHERE `ID` = 384;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well now, these are excellent specimens you collected, $N. Good money for high quality materials, that\'s for sure.', `VerifiedBuild` = 12340 WHERE `ID` = 385;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Targorr the Dread has finally met his fate. I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death\'s ruthless grip. You have done well, $N. Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics.', `VerifiedBuild` = 12340 WHERE `ID` = 386;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your efforts in The Stockade were valiant, $N. It\'s obvious this problem is bigger than the both of us. But you have performed well and for that I am thankful.', `VerifiedBuild` = 12340 WHERE `ID` = 387;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. $b$bBut alas, I cannot return to the past.  Just know, $N, that you have brought my family justice through your deeds.', `VerifiedBuild` = 12340 WHERE `ID` = 388;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What in the Light do you want? Can\'t you see we have a crisis here?$b$bBazil Thredd?! Why would you want to speak with that bastard? How am I supposed to know you\'re not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren\'t open, I might throw you in one for a while!', `VerifiedBuild` = 12340 WHERE `ID` = 389;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.$B$BI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.$B$BI\'d guess, then, that you didn\'t get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd\'s activities.', `VerifiedBuild` = 12340 WHERE `ID` = 391;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm. Maelik? No, the name doesn\'t sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think.', `VerifiedBuild` = 12340 WHERE `ID` = 392;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What? What\'s this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.$b$bRegardless, he is an assassin and I know a good deal about him.$b$bMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind.', `VerifiedBuild` = 12340 WHERE `ID` = 393;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 11, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'He is dead, then? Your justice was swift, $N. I pray to the Light that I never become your quarry!$b$b<He laughs and claps you on the shoulder.>$b$bI mean no criticism, $N. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you.', `VerifiedBuild` = 12340 WHERE `ID` = 394;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s good to see you, $N. I have heard that Lord Gregor Lescovar was found dead not long ago.$b$bIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef\'s revenge.', `VerifiedBuild` = 12340 WHERE `ID` = 395;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You are to be commended for the service you have done for Stormwind, $N. If VanCleef had been successful in his machinations, he would no doubt have done considerable harm to the kingdom--something we must obviously avoid.$B$BTake this, $C, as a token of the my appreciation.', `VerifiedBuild` = 12340 WHERE `ID` = 396;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Maggot Eye\'s dastardly acts have finally been avenged. Maybe your acts of valor will send a clear message to those who wish to bring harm to our people. On behalf of the town of Brill I thank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 398;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, thank you, $N! It\'s of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks.', `VerifiedBuild` = 12340 WHERE `ID` = 399;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have defeated Lillith Nefara, proving you are an enemy of the Scourge. Incredible.$b$bI had believed I was the only Undead with free will, but you have shown me there are others who have broken the Lich King\'s domination.', `VerifiedBuild` = 12340 WHERE `ID` = 409;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie\'s schematics for the Recombobulation Device.  Once I add some hydrolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new.', `VerifiedBuild` = 12340 WHERE `ID` = 412;

UPDATE `quest_offer_reward` SET `Emote1` = 7, `Emote2` = 4, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Mountaineer Barleybrew tastes the Shimmer Stout...>$B$BOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!', `VerifiedBuild` = 12340 WHERE `ID` = 413;

UPDATE `quest_offer_reward` SET `Emote1` = 7, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Now, let me have a taste...$b$bMagni\'s Beard! This stuff gets your head turning! And it lightens the limbs, too.$b$bI feel like I can fly!', `VerifiedBuild` = 12340 WHERE `ID` = 414;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N! You know that Shimmerweed you brought me? Well I used it in a few recipes I\'ve been working on, and one of them turned out great!$b$bHere, try it out and tell me what you think...', `VerifiedBuild` = 12340 WHERE `ID` = 415;

UPDATE `quest_offer_reward` SET `Emote1` = 34, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 1000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ugh! When I asked for those ears I didn\'t realize they\'d smell so bad!$b$bHere\'s your reward, $N. Well done.', `VerifiedBuild` = 12340 WHERE `ID` = 416;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is grim news, for Hildelve was a good friend. And I wish I could have been there with you when you found the beast, Mangeclaw!$b$bThank you, $N. Your deed will be remembered by the pilots of the Ironforge Siege Brigade.', `VerifiedBuild` = 12340 WHERE `ID` = 417;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Trust me, it seems a lot harder than it looks, but...$b$bOh, I\'ve never known someone to take much interest in the making of sausages, but I\'ll give you the recipe just in case. Here you go, mind you eat them fresh!', `VerifiedBuild` = 12340 WHERE `ID` = 418;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have served me well, $C. It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal\'s curse.', `VerifiedBuild` = 12340 WHERE `ID` = 421;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is precisely the spell I was in search of, $C. If your dedication to The Dark Lady\'s cause remains infallible you will find you have quite a future amongst The Forsaken.', `VerifiedBuild` = 12340 WHERE `ID` = 422;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I hope I can acquire enough energy from such a limited sample. Perhaps I should have had you get more shackles.$b$bNonetheless, you showed great skill in collecting these, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 423;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Most excellent, $C. Your skill in the art of combat is undeniable.', `VerifiedBuild` = 12340 WHERE `ID` = 427;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well, that makes me feel a little better...$b$bBut I won\'t be happy until they\'re all dead! All of them!', `VerifiedBuild` = 12340 WHERE `ID` = 432;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So it is done? Good. Thank you greatly for your discretion, $N. You\'ve proven worthy on more than one count. I\'ll be sure to keep my eyes on you and your progress within the Alliance.$B$BBe sure to keep your nose clean.', `VerifiedBuild` = 12340 WHERE `ID` = 434;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for the aid, $N. I had feared Erland was overcome by the dangers of Silverpine. With your help, I see that he has not.', `VerifiedBuild` = 12340 WHERE `ID` = 435;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Jern wants to know what the slowdown is, eh?$b$bIronband is putting together his latest progress report with details, but I can tell you this:$b$bIt\'s the Troggs!!', `VerifiedBuild` = 12340 WHERE `ID` = 436;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, this ring was my wife\'s. Her fate was the fate of all who fail to endure these harsh times. I feel nothing for her death, nor for the story you tell of her body\'s abduction.$b$bSuch feelings have long since grown cold within me. But desire does still burn in my dead heart, $N.$b$bDesire for revenge.', `VerifiedBuild` = 12340 WHERE `ID` = 441;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, how good of Apothecary Johaan to send his research. With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades. Which reminds me, I need to get those samples off to the Necropolis soon.$b$bBut you must excuse my rambling. Extend your stay in Silverpine, $N. We could use an able bodied $C like you around here.', `VerifiedBuild` = 12340 WHERE `ID` = 445;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This scroll is laced with powerful magic. I\'ve never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle.', `VerifiedBuild` = 12340 WHERE `ID` = 446;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'How good of Apothecary Renferrel to send you to me, $N. These samples will indeed prove useful to the cause. I will begin studying their toxic and contaminable properties at once.', `VerifiedBuild` = 12340 WHERE `ID` = 447;

