UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello $N. You\'re here about the task I have, eh? It\'s good to see a young $R like yourself whose blood burns at the prospect of adventure!', `VerifiedBuild` = 12340 WHERE `ID` = 467;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, $C! You\'re here for the scouting mission, are you? Very good!$b$bI hope your gear is in good condition, because this \"scouting\" mission has changed into something more messy...', `VerifiedBuild` = 12340 WHERE `ID` = 468;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm, this is from Einar, right? Hasn\'t delivered his skins to me in person for almost a week now. No doubt it\'s some differences with the wife!$b$bMaybe I\'ll have my wife go speak with Sida sometime...', `VerifiedBuild` = 12340 WHERE `ID` = 469;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm... Don\'t suppose you\'d be interested in becoming my apprentice, would you?$b$bHah! No, I\'m just kidding. You\'re much too old, for one thing. Besides - from the looks of you, it would seem that you have other ambitions in life. Nonetheless, these are some fine skins you\'ve procured, and I\'ll be able to put them to good use.', `VerifiedBuild` = 12340 WHERE `ID` = 471;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What brave $C sends word from Menethil? Ah $N, they call you.$b$bYou bring hope to a hopeless situation. \'Tis good news indeed that young Harlo survived. While fleeing he received a grievous wound. We had but little time to send him on his way on the back of the only surviving steed with the regiment.$b$bBut now we face a perilous situation. Dun Modr has fallen and we are but a shadow of the great regiment we once were.', `VerifiedBuild` = 12340 WHERE `ID` = 472;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N. Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz. You\'re a $R of worth.$b$bAnd I have a task for you.', `VerifiedBuild` = 12340 WHERE `ID` = 473;

