UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nice work you\'ve done here, $N. The quality of these skins is superb. I\'ll have to get them into the curing process as soon as possible. Oh, but before I get to that, there\'s some other work I need done that I think you might be able to take care of.', `VerifiedBuild` = 12340 WHERE `ID` = 484;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N you have proven yourself a most worthy and able $C. A night elf who follows the path of honor as sure as you do is certain to find great glory in this world.$b$bMay the forest spirits protect you wherever your travels may take you.', `VerifiedBuild` = 12340 WHERE `ID` = 486;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have served the good people of Dolanaar and Darnassus well, brave $C. As a member of the Sentinel force of Teldrassil I salute your efforts.', `VerifiedBuild` = 12340 WHERE `ID` = 487;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, most excellent. Apothecary Renferrel has my utmost respect. I am anxious to study his work.', `VerifiedBuild` = 12340 WHERE `ID` = 493;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The raven\'s cry from the west doth beckon?$b$bSuperb news! Hillsbrad is ripe for attack. We can carry out our plan of destruction now. Varimathras will be pleased.', `VerifiedBuild` = 12340 WHERE `ID` = 494;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These specimens are perfect. Well, $N, you have managed to bring me the slightest hint of joy on yet another miserable day. Your efforts are appreciated.', `VerifiedBuild` = 12340 WHERE `ID` = 496;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So the humans thought to turn our warriors into slaves, did they? We\'ll show them!$b$bIt would seem that they have taken Gol\'dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...$b$bWhen we have a lead, I will be sure to tell you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 498;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Superb collecting, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 501;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. I led the expedition from Durotar under the Warchief\'s orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...$b$bWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now.', `VerifiedBuild` = 12340 WHERE `ID` = 503;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The nerve of those overbearing humans! We\'ll show them that the orcs shall never submit to their will!$b$bThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other.', `VerifiedBuild` = 12340 WHERE `ID` = 506;

UPDATE `quest_offer_reward` SET `Emote1` = 20, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'No, no please don\'t hurt me! I never meant your people any harm, he\'s had me against my will! Please... spare me!', `VerifiedBuild` = 12340 WHERE `ID` = 507;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, $N, no doubt the Warchief will be glad to hear of your success.', `VerifiedBuild` = 12340 WHERE `ID` = 508;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the horrible reek of Mudsnout Blossoms. At least those filthy Gnolls are good for something.', `VerifiedBuild` = 12340 WHERE `ID` = 509;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Apothecary Lydon sent you? Ah, why didn\'t you say so!$b$bDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.$b$bThe good chap sends Mudsnout Composite! I know what our friend in Hillsbrad is up to now. And I like the way he thinks. The Dark Lady would be most impressed with the progress he is making toward the new plague.', `VerifiedBuild` = 12340 WHERE `ID` = 513;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, encryption! A specialty of mine. Let me see here...', `VerifiedBuild` = 12340 WHERE `ID` = 514;

