UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Mission accomplished, $C. And carried out quite skillfully, I might add.', `VerifiedBuild` = 12340 WHERE `ID` = 529;

