UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks for helping me out with my little plan, $N. I\'ve been itching for months to get back at that snooty, stuck-up boy, and I\'d say we did a pretty good job! Here, have this, you\'ve earned it.', `VerifiedBuild` = 12340 WHERE `ID` = 531;

