UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.', `VerifiedBuild` = 12340 WHERE `ID` = 630;

UPDATE `quest_offer_reward` SET `Emote1` = 18, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my, the news is grave....', `VerifiedBuild` = 12340 WHERE `ID` = 632;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The remaining bridge is saved! You have done a great service to King Magni and the people of Khaz Modan.$B$BNow if we can only hold out long enough for reinforcements to show...', `VerifiedBuild` = 12340 WHERE `ID` = 633;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My condolences go out to Longbraid and his brave soldiers. The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.$b$bBut Stromgarde has fallen! Hence our presence here at Refuge Pointe. We are faced with retaking our own great city.$b$bHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own...', `VerifiedBuild` = 12340 WHERE `ID` = 634;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You say you saw my Sully pinned beneath the icy waters? Say it isn\'t so!$B$BLet me read what he wrote....', `VerifiedBuild` = 12340 WHERE `ID` = 637;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'How you doing, $C? The task set before us by Vol\'jin will be a difficult one, and any assistance you might provide will be appreciated and necessary.', `VerifiedBuild` = 12340 WHERE `ID` = 638;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol\'kalar for ourselves.', `VerifiedBuild` = 12340 WHERE `ID` = 643;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul\'Gurub will be no more.$b$bYour assistance has been great, $N, and the Darkspear trolls are indebted to you.$b$bI will be sure that the sword is delivered to Nimboya at Grom\'gol.', `VerifiedBuild` = 12340 WHERE `ID` = 646;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, nothing like Foggy MacKreel\'s Moonshine to warm you up on a brisk day! And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend! Many thanks indeed!', `VerifiedBuild` = 12340 WHERE `ID` = 647;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, YOU\'RE the great savior of OOX-17/TN! I cannot even begin to express my thanks for your assistance! My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!$b$bPlease, take your choice of any of these items I have. Hopefully, you will make good use of one of them. Thank you again for your generous assistance, my robots and I are in your debt!', `VerifiedBuild` = 12340 WHERE `ID` = 648;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh yeah, about the ripple dad wants! He wants to sell the ripple to a tavern here in Orgrimmar, but we\'ll get more money if it is in its original packaging. I know someone who can do that, and he\'s in the Hinterlands where the ripple is. But he\'s, um, a high elf.$b$bWell, he\'s a good high elf, as he\'s not a part of the Alliance. Well, he\'s not so much a good high elf as he is a drunken high elf. He loves, and I mean LOVES the hooch.', `VerifiedBuild` = 12340 WHERE `ID` = 649;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so you know Malton? He is an old drinking companion of mine. You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol. Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.$b$bAlas, something tells me that your visit here is not to learn of alcohol\'s redeeming values, now is it.', `VerifiedBuild` = 12340 WHERE `ID` = 650;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Lady told me of your coming, $C. You are welcome in my abode for you, like I, serve a higher cause.', `VerifiedBuild` = 12340 WHERE `ID` = 653;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Gor\'mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.$B$BGor\'mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall.', `VerifiedBuild` = 12340 WHERE `ID` = 655;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'If it brings Phin peace, I\'ll destroy every single one of the Forsaken personally. He\'s done so much for us since the plague. We never thought we\'d find friends or family again.$B$BWhen you\'re prepared, come let me know. We\'ll get started right away.', `VerifiedBuild` = 12340 WHERE `ID` = 657;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent!$B$BLet\'s see what this is about...', `VerifiedBuild` = 12340 WHERE `ID` = 658;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Try and stay as quiet as possible, traveler.$B$BOrcs don\'t take too well to being spied on, and there is more to this farm than meets the eye.', `VerifiedBuild` = 12340 WHERE `ID` = 659;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done a great service for us, $N. Thank you.$B$BI hope Kin wasn\'t too much of a handful down there. She\'s very friendly, but can be just as deadly when you\'re her enemy.', `VerifiedBuild` = 12340 WHERE `ID` = 660;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, the two troublemakers are all right after all? Haha, I\'m glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.$B$BBut... it\'s more important I thank you properly for your help. Here. Take this along with my group\'s thanks.$B$BWith any luck, we\'ll figure out what the Forsaken are up to, and put an end to it.', `VerifiedBuild` = 12340 WHERE `ID` = 661;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahoy, matey.$b$b\'Twas a horrible mess. Seahorn will have my ship if he finds out what went down.$b$bOne of the Professor\'s contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden\'s Folly to follow suit.$b$bThen the sea rumbled. The tides lowered and the two ships crashed into the reef.$b$bIt\'s not just a reef. Something\'s down there....$b$bHelp my crew out and you\'ll be rewarded handsomely.', `VerifiedBuild` = 12340 WHERE `ID` = 663;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nice work out there, $N.$b$bThose scum deserved what they got. While nothin\' will ever bring me ship or me crew back, the death of those naga gives me some solace.', `VerifiedBuild` = 12340 WHERE `ID` = 664;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The goggles work perfectly now! Well done, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 665;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Most superb, $N! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!', `VerifiedBuild` = 12340 WHERE `ID` = 666;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We survived the attack!$b$bWe could not have done it without you, $N.$b$bWe\'ll be heading out as soon as the tide rises. If you weren\'t such a promising hero I\'d offer you a place on my crew. But I can tell you have bigger fish to fry.$b$bEven if you are a puny $r....', `VerifiedBuild` = 12340 WHERE `ID` = 667;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!', `VerifiedBuild` = 12340 WHERE `ID` = 668;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, leave it to good old Shakes O\'Breen! I knew that he was the right Captain for the mission!', `VerifiedBuild` = 12340 WHERE `ID` = 669;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders.', `VerifiedBuild` = 12340 WHERE `ID` = 670;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet.', `VerifiedBuild` = 12340 WHERE `ID` = 672;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, $n. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.', `VerifiedBuild` = 12340 WHERE `ID` = 673;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor\'mul to his once proud self. The amulet\'s power was not great enough to show him our newfound power.', `VerifiedBuild` = 12340 WHERE `ID` = 675;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you think you\'re strong enough to help Hammerfall? So be it.$b$bTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you\'re strong enough to aid us. Either way, you\'re here now and I am in need of more soldiers in our fight against the constant attacks.$b$bIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you\'re ready. There\'s no shortage of fighting to be had.', `VerifiedBuild` = 12340 WHERE `ID` = 676;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.', `VerifiedBuild` = 12340 WHERE `ID` = 677;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You are as strong as a kodo, and your lust for battle does your people proud.', `VerifiedBuild` = 12340 WHERE `ID` = 678;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You do your people proud, $N. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands.', `VerifiedBuild` = 12340 WHERE `ID` = 679;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done me a great service, $N. Know that my husband\'s life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage.', `VerifiedBuild` = 12340 WHERE `ID` = 680;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N. With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.$b$bPerhaps our cause yet has hope.', `VerifiedBuild` = 12340 WHERE `ID` = 681;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. We will inform the families of these fallen soldiers that they were killed in battle.$b$bIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.', `VerifiedBuild` = 12340 WHERE `ID` = 682;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You took down Marez Cowl? Well done, $N. Well done indeed!$b$bMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power. We are glad to see she\'ll longer ply her powers against us.', `VerifiedBuild` = 12340 WHERE `ID` = 684;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Falconcrest and Otto? Wonderful!$b$bHere is your reward, $N. I am happy to pay it.', `VerifiedBuild` = 12340 WHERE `ID` = 685;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So King Magni Bronzebeard himself sent ye?$B$BMy, my! This must be important!', `VerifiedBuild` = 12340 WHERE `ID` = 686;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 5, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello. Hello, hello hello hello hello HELLO!$B$BI\'m sorry - wait, no I\'m not! Don\'t be rude!$B$BOh no...that was crazy talk.$B$BBut...sometimes being crazy is my only solace.', `VerifiedBuild` = 12340 WHERE `ID` = 687;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome, $C. The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss...', `VerifiedBuild` = 12340 WHERE `ID` = 688;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Perfect! Better than I could have imagined!$B$BAnd I have quite an imagination you know...', `VerifiedBuild` = 12340 WHERE `ID` = 689;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, Malin sent ye? I don\'t care if Muradin rose up from the dead and whisked ye here on a dragon. I\'m busy! Talk to Kryten if you need somethin\'.', `VerifiedBuild` = 12340 WHERE `ID` = 690;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Incredible! I can see why Malin asked you to come join us - very well done indeed!$B$BAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.$B$BI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you\'re ready.$B$BIt looked as though he might have had a bit of a scuffle with the ogres. Don\'t mention that to him, though; he\'s very sensitive about criticisms to his skills at scouting.', `VerifiedBuild` = 12340 WHERE `ID` = 691;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you found them! Good work, $N! These might be the only chance we have against the evil of Myzrael!$b$bJust let me find my scrap-ratchet and see if I can re-attach these fragments...', `VerifiedBuild` = 12340 WHERE `ID` = 692;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Brilliant, $N. One item down an\' three more to go, based on my list. The other three items are all in Stromgarde.$B$BTake a rest an\' get your strength back--the next phase of my plan\'ll require a little more time an\' effort. Come back to me after you\'ve gotten a warm meal an\' some rest.', `VerifiedBuild` = 12340 WHERE `ID` = 693;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You amaze me, $N. Well done again.$B$BGive me a moment to cast the proper spell to enchant the gem, an\' you\'ll be ready.', `VerifiedBuild` = 12340 WHERE `ID` = 694;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Malin couldn\'t\'ve asked a worthier person to come here an\' aid us, $N. You\'ve done a grand job!$B$BHe\'ll be pleased to see what an overwhelming success our mission\'s been.', `VerifiedBuild` = 12340 WHERE `ID` = 696;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Archmage Malin opens the letter, and his eyes grow wide.>$B$BBy the Light, you\'ve done it. How wonderful. Trelane will be so pleased. I\'m sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.$B$BThank you, $N. Please, take this to help you in your journeys.', `VerifiedBuild` = 12340 WHERE `ID` = 697;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah! Wonderful. Fresh meat for the fire tonight. Thank you, $N.$b$bYou\'ve helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.$b$bIts a pleasant surprise to have you bring us a shipment; Dar\'s not the most attractive orc anyone\'s laid eyes upon, but at least his attitude reeks far less than his smell.', `VerifiedBuild` = 12340 WHERE `ID` = 698;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Glad to see you\'re alive and well, $N.$b$bThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we\'ll be.$b$bI\'ll get started on your weapon as soon as possible. It will only take a short time. I\'ve become quite adept and quick at their production.', `VerifiedBuild` = 12340 WHERE `ID` = 699;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The granite seems but a small token compared to a great dwarf\'s life. But no dwarf shall last on this planet for eternity.$B$BLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future. Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives.', `VerifiedBuild` = 12340 WHERE `ID` = 700;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor\'mul with the fiery strength and intelligence of the raptor.', `VerifiedBuild` = 12340 WHERE `ID` = 701;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done! With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.$B$BYou have done a great deed for the Prospectors, $N. Your efforts will not be forgotten. And neither will Agmond.', `VerifiedBuild` = 12340 WHERE `ID` = 704;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!', `VerifiedBuild` = 12340 WHERE `ID` = 706;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So Stormpike sent you, did he?  Good.$B$BI have a big task for you...', `VerifiedBuild` = 12340 WHERE `ID` = 707;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, fortune is with us! Thank you! We may yet be saved!', `VerifiedBuild` = 12340 WHERE `ID` = 709;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These shall do nicely, $N. Thank you. Hmm, a bit more sand than I\'d anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil.$B$B<Mumbling to himself, Lotwil puts one fist into the palm of his other hand and stares at them as if fascinated.>', `VerifiedBuild` = 12340 WHERE `ID` = 710;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, simply amazing! I would have thought it\'d take half a dozen tauren to bring all these to me.', `VerifiedBuild` = 12340 WHERE `ID` = 711;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, have you ever considered becoming a research assistant? No? I\'m not sure what I\'ll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package.', `VerifiedBuild` = 12340 WHERE `ID` = 712;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don\'t last a century, then I\'ll give all my belongings to Servo.$B$BAll the mages of the Assembly will be in such awe after I finish this, $N. You just wait and see.', `VerifiedBuild` = 12340 WHERE `ID` = 713;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'HA!$b$b<Lotwil grabs the gyrochronatom from you.>$b$bPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you\'ve helped me create. It\'ll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We\'ll see...', `VerifiedBuild` = 12340 WHERE `ID` = 714;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'YES!$b$bI mean, thank you, $N. These will be helpful while traveling through the Badlands.', `VerifiedBuild` = 12340 WHERE `ID` = 715;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here you go, $N. Try these on.', `VerifiedBuild` = 12340 WHERE `ID` = 716;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased.', `VerifiedBuild` = 12340 WHERE `ID` = 717;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks so much, $N. While you were gone, I... er... swallowed a mouthful of sand. It...$B$BWell, enough of that, we\'ll go out and get some food tonight. Eat like kings!', `VerifiedBuild` = 12340 WHERE `ID` = 718;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ye\'re me savior, $C. I\'m glad someone could teach those Shadowforge a lesson or two. Thanks for yer help.', `VerifiedBuild` = 12340 WHERE `ID` = 719;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hammertoe\'s alive?! This is amazin\', $N!', `VerifiedBuild` = 12340 WHERE `ID` = 720;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes? Ah\'m sorry... <cough> Feel so weak. Can ye come closer, $C?$B$BRyedol sent ye? Muradin be praised, that boy\'s not as slow in the head as I once thought. <cough>', `VerifiedBuild` = 12340 WHERE `ID` = 721;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 273, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ha! <cough cough>$B$BAh knew you\'d find me amulet, $N.$B$B<weeze> Well done indeed, $N. <cough>', `VerifiedBuild` = 12340 WHERE `ID` = 722;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hammertoe\'s amulet? I think my spirits were higher when I thought he was dead. Knowin\' fer sure only makes the pain worse. This amulet was his life\'s work. I can\'t let his death be in vain.', `VerifiedBuild` = 12340 WHERE `ID` = 723;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 25, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh! Well, this is a different matter entirely. You probably don\'t realize the gravity of this matter yet, do you?$B$BI care deeply about Hammertoe\'s demise, but if he sent you here with his amulet, then he understood what\'s at stake.$B$BWe will have to take time to mourn his death later.$B$BLet me show you one of the reasons this amulet is so valuable.', `VerifiedBuild` = 12340 WHERE `ID` = 724;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, word from Historian Karnik. Excellent.$B$BI always have time for his business.$B$B<Advisor Belgrum opens the note and begins to read.>', `VerifiedBuild` = 12340 WHERE `ID` = 725;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re treating this matter with an urgency I\'d expect from the king himself, $N.$B$BAll right, then. I know what\'ll bring the Shadowforge down.$B$BTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress.', `VerifiedBuild` = 12340 WHERE `ID` = 726;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh. Greetings, brother.$B$BAnd praise to the dwellers beneath.', `VerifiedBuild` = 12340 WHERE `ID` = 727;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Be discrete with your signs, $C. There are those who do not believe the righteousness of our pledge.$B$BAnd there are those who would see us fail if they knew of us.$B$BWe must always be careful. And watchful. And patient.', `VerifiedBuild` = 12340 WHERE `ID` = 728;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hollee. is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.$b$bHey, you\'re not Hollee! Don\'t suppose you\'ve seen my stone brush?$b$bNever mind that now! I promised the League I\'d send the mysterious fossil I found. Where did Hollee go?$b$bSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...$b$bAnd who are you... \'tis no matter, so long as you\'re here to help.$b$bLet me know when you\'re ready to start looking.', `VerifiedBuild` = 12340 WHERE `ID` = 729;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I\'m so glad Chief Archeologist Greywhisker sent for us.... ', `VerifiedBuild` = 12340 WHERE `ID` = 730;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can\'t believe he insisted on staying there with all of those horrible creatures lurking about.', `VerifiedBuild` = 12340 WHERE `ID` = 731;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good tidings you bring bearing the Sign, $N. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing\'s ruthless lieutenants, the twins Blacklash and Hematus.', `VerifiedBuild` = 12340 WHERE `ID` = 732;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s a start, $N, and it\'ll have to do until we hear word from Ironforge or the Explorers\' League.$B$BNow, if only I could find some salt somewhere for my quenching barrel...', `VerifiedBuild` = 12340 WHERE `ID` = 733;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Cog #5, huh? Yeah, this isn\'t going to be good.', `VerifiedBuild` = 12340 WHERE `ID` = 734;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You are resourceful, $C. If it truly is your charge to begin a new chapter of our order, then I believe you will run it well.', `VerifiedBuild` = 12340 WHERE `ID` = 735;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am impressed! You possess great skill, or great fortune, to have gained these relics. Either way, you are an asset to us.', `VerifiedBuild` = 12340 WHERE `ID` = 736;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 1, `Emote4` = 5, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got it! Oh, hope glimmers!$B$BYour efforts may yet save us, $N. A monument they should make of you! A shrine they should build! May your name be praised until your grandchildren have grandchildren!$B$BUnless...THEY are freed and rise to the surface.  If that happens then you can forget about children.$B$BIf THEY are freed, then we\'re all worm food.', `VerifiedBuild` = 12340 WHERE `ID` = 737;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is sobering news, $N. But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come! Although he was killed by those cursed troggs I\'m sure he took a lot of them down with him.', `VerifiedBuild` = 12340 WHERE `ID` = 739;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my! Leave it to Prospector Remtravel to discover such a find!', `VerifiedBuild` = 12340 WHERE `ID` = 741;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome to the new frontier, $N. Ashenvale is a land of opportunity, one where a young $C like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.$B$BYour presence here tells me that you\'ve come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know.', `VerifiedBuild` = 12340 WHERE `ID` = 742;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.$B$BI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.$B$BBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard.', `VerifiedBuild` = 12340 WHERE `ID` = 762;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, perfect. Stand back while I prepare to make more history!$b$b<Lotwil continues to work feverishly.>', `VerifiedBuild` = 12340 WHERE `ID` = 777;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. That was quite an ordeal, wasn\'t it?$b$bI\'m not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.$b$bPerhaps a little token of appreciation for all your hard work...', `VerifiedBuild` = 12340 WHERE `ID` = 778;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Word of your bravery travels fast, $C. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.', `VerifiedBuild` = 12340 WHERE `ID` = 784;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.$B$BAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.$B$BYou have served your people well, $c.', `VerifiedBuild` = 12340 WHERE `ID` = 786;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Another one of Eitrigg\'s recruits, hm?$B$BA sorry state of affairs we find ourselves in if this is the best the Horde can produce.  No matter.  By the time we think you\'re ready to leave the Valley, you\'ll be a proud warrior of the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 787;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Most excellent, $N. Any good $C will surely find a use for this bag on the battlefield.$b$bI salute your vigor and willingness to die in the name of the Horde!', `VerifiedBuild` = 12340 WHERE `ID` = 791;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done well, $N.$b$bAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.', `VerifiedBuild` = 12340 WHERE `ID` = 792;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You retrieved it! Well done!$b$bYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials. But I fear they have further aims in our land.$b$bWe have not seen the end of them.', `VerifiedBuild` = 12340 WHERE `ID` = 794;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hm... your report comes at a bad time. The Burning Blade is not seen here in Sen\'jin, but their evil has taken seed off the coast, on the Echo Isles.$b$bThe orcs are friends of the Darkspear Trolls. Honorable friends. We want to help the orcs, but... we need help too.$b', `VerifiedBuild` = 12340 WHERE `ID` = 805;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Aha! You got him!$b$bYou do your clan proud, $N. And because of you, Durotar is free of one more agent of evil.', `VerifiedBuild` = 12340 WHERE `ID` = 806;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Neeru wants the Demon Seed destroyed, does he? Strange...$b$bVery well. If he wishes the seed gone, then I will tell you how to remove it.', `VerifiedBuild` = 12340 WHERE `ID` = 809;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, you\'ve saved my life. Thank you.$B$BPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won\'t be usin\' it anytime soon. Kor\'ghan is gonna march me through more of his rituals until I prove myself. More killin\' boars, more gatherin\' scorpid tails... <sigh>', `VerifiedBuild` = 12340 WHERE `ID` = 812;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here is the antidote, $N. Take it to Rhinag as soon as you can, and be cautious.', `VerifiedBuild` = 12340 WHERE `ID` = 813;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You might be weak, but at least you\'re not clumsy, $N.$b$bHere, take this and get outta my way. I\'ve got cooking to do.', `VerifiedBuild` = 12340 WHERE `ID` = 815;

UPDATE `quest_offer_reward` SET `Emote1` = 18, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, my son... my beautiful son.$b$bUncertain of my son\'s fate, I have tormented myself since he left. Now that I know what\'s happened, perhaps I can finally begin to mourn.$b$bThank you, $N. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it.', `VerifiedBuild` = 12340 WHERE `ID` = 816;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am pleased, $N. Because of your help, our people will be protected, and not go cold as the seasons change.$b$bThank you.', `VerifiedBuild` = 12340 WHERE `ID` = 817;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, young one... well done indeed.', `VerifiedBuild` = 12340 WHERE `ID` = 818;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well, I\'ll be...$B$BThis was one of Chen Stormstout\'s kegs. He traveled with Rexxar a long time ago. I haven\'t seen or heard about him in a kodo\'s age. I appreciate you bringing this to me, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 819;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Haha... I never thought I\'d make more of this stuff ever again.$B$BYou\'ve stirred in me a great sense of nostalgia, $N. Kind of reminds me of the last time I blacked out from too much trogg ale. Thank you. The memories warm my stomach.', `VerifiedBuild` = 12340 WHERE `ID` = 821;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Haha! I knew you couldn\'t resist some of this brew. Come back again anytime you want some more, $N. Just bring me more of the ingredients I had you collect.', `VerifiedBuild` = 12340 WHERE `ID` = 822;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes? You have something to report? Well then, let\'s have it!', `VerifiedBuild` = 12340 WHERE `ID` = 823;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This globe... it is most disturbing. Many of the more powerful elementals receive their power and energy through such devices. To find one like this nearly intact is one thing - to find it so tainted is another.$b$bI will see that this globe is studied properly by the Earthen Ring. Perhaps we can bring an end to this corruption of the elements. Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring.', `VerifiedBuild` = 12340 WHERE `ID` = 824;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your recovery mission was a success, $C. I will see to it that these tools get to Orgrimmar with the next caravan.$b$bNicely done.', `VerifiedBuild` = 12340 WHERE `ID` = 825;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome, $N. Word reached me of your coming, and of your exploits in Durotar.$b$bYou are a $C of growing skill and renown.$b$bStay on the pure path, and your future will be great indeed.', `VerifiedBuild` = 12340 WHERE `ID` = 828;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This does not bode well at all. You were wise to bring this information to my attention.', `VerifiedBuild` = 12340 WHERE `ID` = 830;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.$b$bYou have served the Horde honorably, young $C.$b$bNow excuse me, I must counsel Thrall on these matters at once....', `VerifiedBuild` = 12340 WHERE `ID` = 831;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Examines the Eye of Burning Shadow>$b$bIntriguing. The voice you heard mentioned my name? I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out. Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.$b$bI must study this pendant. I must study and, and must ponder the meaning of its message.$b$bThank you for bringing this to my attention, $N. You have done your people a great service.', `VerifiedBuild` = 12340 WHERE `ID` = 832;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, YOU\'RE the great savior of OOX-09/HL! I cannot even begin to express my thanks for your assistance! My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!$b$bPlease, take your choice of any of these items I have. Thank you again for your generous assistance $N, my robots and I are in your debt!', `VerifiedBuild` = 12340 WHERE `ID` = 836;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, $C, the High Executor mentioned you might be the one to trust in the matter of the key. I\'ve dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.$b$bThis task will not be easy, but such tasks seldom are. You most assuredly look like the type to know this as fact.', `VerifiedBuild` = 12340 WHERE `ID` = 838;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, so Takrin sent you? He\'s an excellent scout, I\'m not sure what I\'d do without him.$b$bI\'ll sign your recruitment letter, but what we really need is someone at the Crossroads.', `VerifiedBuild` = 12340 WHERE `ID` = 840;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N. With the plainstriders gone we\'ll have an easier time keeping our supply chains intact. And I hope you learned a few tricks out there in the Barrens, for your next prey has a little more fire in its blood than the plainstriders...', `VerifiedBuild` = 12340 WHERE `ID` = 844;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Not bad, $N. Those zhevra hold a lot of strength in their legs. A sharp kick from them can knock even a tauren on its haunches!$B$BIt looks like you have some strength in you too. Are you ready for a real challenge?', `VerifiedBuild` = 12340 WHERE `ID` = 845;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I see you are quite industrious, $C.$B$BNo doubt we shall soon have a fitting surprise for those dwarves.', `VerifiedBuild` = 12340 WHERE `ID` = 846;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'When the enchantment wears off, I will speak with Gor\'mul. My thanks to you for your help in returning Gor\'mul to the land of the living. I have no doubt he thanks you greatly as well.', `VerifiedBuild` = 12340 WHERE `ID` = 847;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done well, $N! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe.', `VerifiedBuild` = 12340 WHERE `ID` = 849;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. The centaur are low, brutish creatures, but a few have the wit and vision to lead. And those are the most dangerous.$B$BBarak was such a centaur. It is good that he is dead.', `VerifiedBuild` = 12340 WHERE `ID` = 850;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I commend you, $N. These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless. In defeating them, your valor is proven.', `VerifiedBuild` = 12340 WHERE `ID` = 852;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nicely done. I\'m sure you\'ve struck fear into the surviving centaurs, $N. If they have sense, they\'ll now calm themselves and stop their advances.$B$BBut I don\'t think they will, and that is unfortunate.$B$BUnfortunate...for them.', `VerifiedBuild` = 12340 WHERE `ID` = 855;

UPDATE `quest_offer_reward` SET `Emote1` = 15, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'At last, the power is mine again! Mine I say!', `VerifiedBuild` = 12340 WHERE `ID` = 857;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I will analyze this data immediately. Perhaps Keever\'s insanity will prove to be my genius after all.$B$BAs for you... you are useful to me, and I reward quite well those who remain useful. Take this item, this coin, and most importantly my thanks along with them.$B$BCheck back with me from time to time - I wager that our working together on this project is not at an end.', `VerifiedBuild` = 12340 WHERE `ID` = 864;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, these are nice. Real nice... Good job, $N. I look forward to seeing more of your work in the future.', `VerifiedBuild` = 12340 WHERE `ID` = 867;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found a fissure in the earth, with gases bubbling from it? Strange. This may be an answer to our questions, but we cannot yet be sure.$B$BBut it is a clue. And I am grateful that you found it.', `VerifiedBuild` = 12340 WHERE `ID` = 870;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done well, $N. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored.', `VerifiedBuild` = 12340 WHERE `ID` = 871;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. With Kreenig\'s death, there will be a definite decline in the attacks on our caravans.$B$BYour people should be proud to count you among them.', `VerifiedBuild` = 12340 WHERE `ID` = 872;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You now are one with Isha Awak, $N. His spirit is with you. He lurks in your eyes...$B$BEyes that, one day, will learn to see.', `VerifiedBuild` = 12340 WHERE `ID` = 873;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My brother sent you, did he? Then you must have proven yourself to him. If you have earned the respect of Jorn, then you have my respect as well.$B$BAre you ready to tread farther down the hunter\'s path?', `VerifiedBuild` = 12340 WHERE `ID` = 874;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent work my friend. I think you\'ll go far within the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 875;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'HA! Well done, $N! Very well done... I wasn\'t sure you were up to the task, but you\'ve proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.', `VerifiedBuild` = 12340 WHERE `ID` = 876;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your findings are amazing! The seeds I gave you were dried, and dead. Whatever rests under these oases can create life from nothing!$B$BWe must study this more...', `VerifiedBuild` = 12340 WHERE `ID` = 877;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. Studying the beasts of an area can tell much about the area itself. We shall see what tale these shells tell.$B$BPlease accept my gratitude for your aid ... and perhaps you can use these coins. I find that I do not need them.', `VerifiedBuild` = 12340 WHERE `ID` = 880;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve beaten Echeyakee, and though his days of hunting are over... his spirit is with you. He will show you the strength found in subtlety, and the honor in mercy.$B$BYour path is still long, $C. Let\'s hope you stride it well.', `VerifiedBuild` = 12340 WHERE `ID` = 881;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This fang is merely a token, but what it represents is profound.$B$BIshamuhale\'s strength is in you, $N. May you use it with temperance. That is your burden.$B$BThat is your honor.', `VerifiedBuild` = 12340 WHERE `ID` = 882;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Lakota\'mani is called Earthshaker in our language, and his steps are like gathered thunder. He is with you now, and his courage mingles with yours. Together there is no conflict you cannot face.$B$BWalk tall, $N. Walk tall, Earthshaker.', `VerifiedBuild` = 12340 WHERE `ID` = 883;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The thunder lizard Owatanka is called Bluebolt by the tauren, for within him resides a speed that belies his size. It is said that lightning struck Bluebolt long ago and, fed from the sky\'s rage, the great beast\'s energy is without limit.$B$BMay his energy flow through you, $N. For you now keep pace with Owatanka.', `VerifiedBuild` = 12340 WHERE `ID` = 884;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.$B$BBut Washte Pawne, called Spirit Biter in Taurahe, can bring neither... or both.$B$BThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs. The sting you felt is the pain of regret.$B$BBut I can see you have conquered this. You have learned that regret turns to wisdom, and that through pain one gains strength.$B$BYou have learned much, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 885;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did good, kid. A little more work like that, and it\'ll be one less thing I\'ll have to worry about. Hopefully they\'ll be convinced that they should relocate their operation elsewhere.$B$BIn the meantime, there is the small matter of getting back the goods they stole from me!', `VerifiedBuild` = 12340 WHERE `ID` = 887;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Alas, the righteous Alliance guns have been silenced. You shall be rewarded for your aid, $N.$B$BNow to tend to the grim task of recovering the bodies of the dead....', `VerifiedBuild` = 12340 WHERE `ID` = 891;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'No dice, eh? I guess it must have been the Freebooters then... Dizzywig\'s on the level, I\'m sure he wouldn\'t cheat me like that. After all, he is on the payroll.$B$BLooks like I\'ve got some goods to get back, $N. What do you say?', `VerifiedBuild` = 12340 WHERE `ID` = 892;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent, excellent specimens indeed.$B$BThe quilboar are further along than I had expected.$B$BHere, $C, take this and get out of my way. I\'d better take a closer look at these weapons. We may have underestimated our enemy, and that\'s the kind of mistake we can\'t afford to make.', `VerifiedBuild` = 12340 WHERE `ID` = 893;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Look at the size of that thing, $N! We\'re going to be rich! Let\'s see, according to the rates I\'ve seen on gems going into Undermine, I should be able to figure out your cut--fifty percent, don\'t worry!$B$BNow let\'s see... I think this should do about right. Pleasure doing business with you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 896;

UPDATE `quest_offer_reward` SET `Emote1` = 274, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can tell nothing of the nature of this beast, for its spirit has fled. But as you guessed, it does not belong in the Barrens. I fear it may herald a grim future for our people...$B$BBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature.', `VerifiedBuild` = 12340 WHERE `ID` = 897;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'And to think, we thought Firebough was long dead!$B$BYour heroics have earned you a place of honor with the Thalo\'dan Privateers, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 898;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$C, you take my task seriously, and for that I thank you.$B$BAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves.', `VerifiedBuild` = 12340 WHERE `ID` = 899;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, I see you\'ve been busy, lurking in the grasses and hunting prowlers. Do you think, then, it is time to face a champion among them?', `VerifiedBuild` = 12340 WHERE `ID` = 903;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Is your task finished? Ponder the life of the Scytheclaw as you do it. There are important lessons within every creature\'s lifespawn. $B$BSome of the others believe I have been too heavy handed in my lesson. I know that you are simply following my orders, but I want you to consider the life of the creatures you are slaughtering. $B$BThough they are at times a nuisance, they only become threatening when we seek their slaughter. This days defilement will cause us more trouble than it will solve problems...', `VerifiedBuild` = 12340 WHERE `ID` = 905;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 4, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found the Razormane leader and killed him yourself, $N? Amazing.$B$BI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.$B$BI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 906;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is good to see you return with proof of victory. And it is good to know you have done so with your bones unbroken.', `VerifiedBuild` = 12340 WHERE `ID` = 907;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wow, Ashenvale is where real adventure happens! Have you ever fought in Ashenvale, $N? When I become a hero when I grow up, I wanna come to Ashenvale and fight for the glory Horde!$B$BThank you for taking me to the frontier, $N. You\'re the best!', `VerifiedBuild` = 12340 WHERE `ID` = 911;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You, like the thunderhawk, should be proud. You have bested every foe we set you before, and have done so with strength, courage and honor.$B$BBut your path, $N, continues. In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.$B$BNow, it is time to move on.', `VerifiedBuild` = 12340 WHERE `ID` = 913;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done it, $N. You killed the leaders of the Druids of the Fang. My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.$b$bI thank you, $N. I thank you for myself, for the druids of Thunder Bluff, and for the land.', `VerifiedBuild` = 12340 WHERE `ID` = 914;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders. It is my belief that it will have properties linked to the recent growth of our new world tree.', `VerifiedBuild` = 12340 WHERE `ID` = 916;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, very good. I will have this egg and the venom transported to Darnassus, then return there when my studies are done here. I expect to find out a great deal from these specimens, $N. You have been a great help to me.', `VerifiedBuild` = 12340 WHERE `ID` = 917;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got them. This is good!$b$bI will plant these seeds in special soil I have prepared. I believe the seeds will sprout into timberlings who are much more docile. Perhaps later you can see the results!', `VerifiedBuild` = 12340 WHERE `ID` = 918;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s a lot! I\'m afraid they\'re spreading at a dangerous rate. I hope I can solve the riddle of what is tainting them.$b$bThank you for your help, $N. The land is a cleaner place from your efforts.', `VerifiedBuild` = 12340 WHERE `ID` = 919;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, $N. I was hoping you\'d be prompt in answering my summons. I have an important task that I would like you to perform.', `VerifiedBuild` = 12340 WHERE `ID` = 920;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.', `VerifiedBuild` = 12340 WHERE `ID` = 921;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, a timberling seed? I wanted to try growing one of these to help Denalan with his studies.$b$bBut I\'m afraid I\'ve discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent\'s taint. They are beyond my talents to repair.$b$bDenalan is very skilled with things that grow. He may find a cure for future timberlings. He may be their only hope.', `VerifiedBuild` = 12340 WHERE `ID` = 922;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done! These tumors are the symptom of the timberling\'s disease. They are filled with a poison that we must cleanse from our new land.$b$bI will dispose of these tumors. Thank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 923;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.$B$BI think we\'d best get started.', `VerifiedBuild` = 12340 WHERE `ID` = 928;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.$B$BIt was in this trying time that the Betrayer was freed from his prison, and Shan\'do Stormrage disappeared. A dark time for all.', `VerifiedBuild` = 12340 WHERE `ID` = 929;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found this on Teldrassil? Intriguing... this fruit is exotic. Perhaps its seeds were brought here from far off. Perhaps even as far as Azeroth! And there\'s something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.$b$bThank you, $N. Now if you\'ll excuse me, I must study this further...', `VerifiedBuild` = 12340 WHERE `ID` = 930;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Where did you get this? I haven\'t seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago! It\'s amazing that a specimen made its way to Teldrassil. And it\'s grown to such a size!$b$bThank you, $N. Forgive my shortness of words, but there is a test I would like to perform on this frond...', `VerifiedBuild` = 12340 WHERE `ID` = 931;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Shan\'do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.$B$BWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree.', `VerifiedBuild` = 12340 WHERE `ID` = 933;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.$B$BNonetheless, I can finally get back to my work then. The weight of Teldrassil\'s problems fall upon my shoulders. A yoke I would wish to soon be rid of.$B$BTake this, you may find some use for it.', `VerifiedBuild` = 12340 WHERE `ID` = 935;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $C; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.', `VerifiedBuild` = 12340 WHERE `ID` = 936;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am impressed by what you have accomplished here in so short a time, $N. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.$b$bI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.', `VerifiedBuild` = 12340 WHERE `ID` = 937;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I sense the suffering of ancient ones, $N...$B$BHolding these items is almost unbearable...', `VerifiedBuild` = 12340 WHERE `ID` = 939;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.$b$bI fear my work on Teldrassil shall never be completed, and our immortality never restored.$b$bNonetheless, you have done the Oracle Tree\'s task well, and should be rewarded for your diligence.', `VerifiedBuild` = 12340 WHERE `ID` = 940;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my! You say this came from the distant lands of Kalimdor?$B$BAmazing! Simply amazing!', `VerifiedBuild` = 12340 WHERE `ID` = 942;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Most excellent, $N!$B$BNow to see if I can use the stone to decipher the powers of the fossils.', `VerifiedBuild` = 12340 WHERE `ID` = 943;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Many thanks, $N. These mushrooms are fine specimens!$b$bAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?$b$bThe Ancients are wise, but I had hoped that, this time, they were wrong.', `VerifiedBuild` = 12340 WHERE `ID` = 947;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.$B$BThank you, $N. With your help, my work here is finished, and I will be able to deliver a full report to the Circle.', `VerifiedBuild` = 12340 WHERE `ID` = 953;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahh... To what could I possibly owe the exceedingly special honor of a $r such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.$b$bBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment.', `VerifiedBuild` = 12340 WHERE `ID` = 954;

UPDATE `quest_offer_reward` SET `Emote1` = 15, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am freed, $N! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.$B$BI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance.', `VerifiedBuild` = 12340 WHERE `ID` = 957;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again.', `VerifiedBuild` = 12340 WHERE `ID` = 958;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.$B$BThank you, $N. Nicely done, I say!', `VerifiedBuild` = 12340 WHERE `ID` = 959;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $n. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.$b$bPlease, I would be alone with my grief...', `VerifiedBuild` = 12340 WHERE `ID` = 963;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This\'ll work, $N! My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.$b$bThe next step will be to get an appropriate mold for the key. I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items. He works for whom goblins usually work for - the highest bidder.', `VerifiedBuild` = 12340 WHERE `ID` = 964;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it.', `VerifiedBuild` = 12340 WHERE `ID` = 965;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Many thanks, $n. This should shed some light on this warlocks\' gathering...$b$bHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.$b$bThere is no more time to delay. Warning must be delivered to Delgren immediately.', `VerifiedBuild` = 12340 WHERE `ID` = 966;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'If you don\'t mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let\'s see what he has to say...$B$BThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.$B$BAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies.', `VerifiedBuild` = 12340 WHERE `ID` = 967;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, a copy of The Powers Below. An interesting text, this is. And some might find it useful...$B$BBut this one\'s in sad shape. And look here! There are notes in the margin of almost every page!$B$BHm...I know this copy. I sold it to Bolgar last year. Are you...a friend of his? Yes, I thought you were. You have that same fire behind your eyes!$B$BWell, by definition, a friend of Bolgar\'s is a friend of mine. And we take care of our own, yes?', `VerifiedBuild` = 12340 WHERE `ID` = 968;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahh, yes... I will make da charm for ya now. Just you wait!', `VerifiedBuild` = 12340 WHERE `ID` = 969;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found the manuscript! What a joyous day this is! Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!$B$BYour service to us is more than you know, $N. But I hope that this gift shows you the gratitude we extend to our allies.', `VerifiedBuild` = 12340 WHERE `ID` = 971;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It was a grand thing you did today, $n. You should be quite proud of yourself for having faced down a warlock of such power.$b$bNow, let\'s see what we can learn from Ilkrud\'s writings.', `VerifiedBuild` = 12340 WHERE `ID` = 973;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I\'ll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm...', `VerifiedBuild` = 12340 WHERE `ID` = 974;

