UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I knew you would be up to the task, $N.$B$BI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, $N, as well as this gift.', `VerifiedBuild` = 12340 WHERE `ID` = 981;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done us here in Auberdine a great service, lad. We\'ll make sure that their effects are properly taken care of.$b$bAs for you, please have this. It is the least I can do for someone with the bravery to set things right.', `VerifiedBuild` = 12340 WHERE `ID` = 982;

UPDATE `quest_offer_reward` SET `Emote1` = 18, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is terrible news indeed, $N.$B$BWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.$B$BThank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 984;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wash the blood from your garments, $N, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss.', `VerifiedBuild` = 12340 WHERE `ID` = 985;

