UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, it\'s here! I have waited for this rare earth for quite some time. I hope it\'s still fresh...$b$bThank you for bringing it to me, $N. You are a $R who is generous with $Ghis:her; time.', `VerifiedBuild` = 12340 WHERE `ID` = 997;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $C.$b$bI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$b$bOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.', `VerifiedBuild` = 12340 WHERE `ID` = 1000;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $c.$b$bI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$b$bOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.', `VerifiedBuild` = 12340 WHERE `ID` = 1004;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I felt the anguish of the Dor\'danil Barrows lessen, and knew you had completed your task.$B$BIt was grim work you did, $N, for the spirits you destroyed were merely victims of the Forsaken\'s evil. But with their destruction, let us hope the other maddened spirits find peace.', `VerifiedBuild` = 12340 WHERE `ID` = 1012;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, $N. Your tenacity shall be rewarded.', `VerifiedBuild` = 12340 WHERE `ID` = 1014;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What makes you think I wish to be pestered by the likes of you, $C? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.$B$BThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?', `VerifiedBuild` = 12340 WHERE `ID` = 1015;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay.', `VerifiedBuild` = 12340 WHERE `ID` = 1016;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Now I can see that repugnant smile wiped from his face forever. You have done very well, $N. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing.', `VerifiedBuild` = 12340 WHERE `ID` = 1017;

