UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I bid you greetings. You are here seeking council?', `VerifiedBuild` = 12340 WHERE `ID` = 1063;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Magatha sent word of your coming, $N. Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.$b$bThe Forsaken are eager to offer what help we can.', `VerifiedBuild` = 12340 WHERE `ID` = 1064;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A note from Zamah? Her needs must be great to send word from so far. Let us see what she says...$b$bAh, splendid! I know exactly what to do!', `VerifiedBuild` = 12340 WHERE `ID` = 1065;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good!  I trust the Syndicate gave you little trouble?$B$BAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.$B$BNow hold a moment while I create my concoction...', `VerifiedBuild` = 12340 WHERE `ID` = 1066;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A toxin from Apothecary Lydon? Very good. If I know Lydon, then this toxin will be quite effective against the Venture Company...', `VerifiedBuild` = 12340 WHERE `ID` = 1067;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, $N. With their loss, let us hope the Venture Company will remove itself from these mountains.$b$bFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead.', `VerifiedBuild` = 12340 WHERE `ID` = 1068;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got them! Thank you!$B$BI\'ll have these sent to Dizzywig and get them shipped to Booty Bay. I can already taste the profits!$B$BHere is your cut, $N. I couldn\'t have made this deal without you.', `VerifiedBuild` = 12340 WHERE `ID` = 1069;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you\'ve come from Ashenvale at the behest of Thenysil -- how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I\'m proud of her.$B$BIt is a pleasure to meet you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1070;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks so much for your help, $N. You\'re actually back just in time.$B$BI think I\'ve got the perfect plan. Explosives. No, that\'s not the plan, but it\'s part of the plan.$B$BSee, I\'ve been using high explosives--don\'t worry, they\'re not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd \'em pretty good with a few key detonations along the mountains\' edges, but I\'ve been low on supplies now for a few days.', `VerifiedBuild` = 12340 WHERE `ID` = 1071;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahhh. Gaxim sent you, huh? How do I know you\'re not lying to me?! Hmm? Hmm?', `VerifiedBuild` = 12340 WHERE `ID` = 1072;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This\'ll do nicely.$B$BIf I didn\'t know better, stranger, I\'d say you knew somethin\' about alchemy. Good, good... the world\'s not all about swords and sorcery, you know?', `VerifiedBuild` = 12340 WHERE `ID` = 1073;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your task has been done flawlessly, $N.$B$BNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.$B$BWhat? Yes, dynamite... wagons of it. It\'s the perfect distraction, I tell you... just wait and see.', `VerifiedBuild` = 12340 WHERE `ID` = 1074;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is perfect, $N! Well done.$B$BThis spell, mixed with the NG-5, shall make the perfect remote explosive.$B$BWe\'ll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.\'s letters and engineering plans.$B$BThat will surely slow down their deforestation acts.', `VerifiedBuild` = 12340 WHERE `ID` = 1077;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is perfect, $N. Thank you greatly.$B$BPerhaps one day in the future I\'ll be able to help you as you have helped me.', `VerifiedBuild` = 12340 WHERE `ID` = 1078;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Truly amazing! This is a huge blow to the Venture Co.$B$BWe\'ll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed.', `VerifiedBuild` = 12340 WHERE `ID` = 1079;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Incredible, $N! Kaela and the Sentinels will be so happy. With your skill and my creations, we\'re unstoppable.', `VerifiedBuild` = 12340 WHERE `ID` = 1080;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, $N. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.$B$BYou would do me a great honor if you would accept this as a gift of appreciation.', `VerifiedBuild` = 12340 WHERE `ID` = 1081;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. You have done a service to the Sentinels.$B$BI\'m glad to see Kaela... and even Gaxim, are doing well.$B$BYou\'ve earned our appreciation.', `VerifiedBuild` = 12340 WHERE `ID` = 1082;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The remains of our enemy... your strength serves us well, $N. Thank you.', `VerifiedBuild` = 12340 WHERE `ID` = 1083;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N.$B$BThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away.', `VerifiedBuild` = 12340 WHERE `ID` = 1084;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Treacherous...treacherous and dangerous, that\'s what this land is.$B$BBut I\'m here to show the night elves that it\'s a little safer with the help of good ole engineering and a dash of magic.$B$BSee, swearing off magic completely won\'t help the night elves -- they need it. The world needs it. And with engineering and alchemy to boot, you can\'t go wrong. The possibilities are endless.', `VerifiedBuild` = 12340 WHERE `ID` = 1085;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found the port? Well done, $N! I am sure the goblins were quite surprised from your delivery! Let us hope that toxin finds its way to their headquarters.$B$BYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company. They are deserving of far worse.$B$BAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:$B$BDo not shy from dark paths... if those paths lead to victory.', `VerifiedBuild` = 12340 WHERE `ID` = 1086;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks, $N. It was looking a little dicey there for a second and we\'ve probably drawn far too much attention to ourselves.$b$bThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible.', `VerifiedBuild` = 12340 WHERE `ID` = 1090;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is interesting indeed.$B$BYou and Gaxim have done very well, $N. Thank you.', `VerifiedBuild` = 12340 WHERE `ID` = 1091;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I\'m sure the engineers in Undermine will be most interested to look at this...$b$bOf course I\'ll want to keep a little piece for myself, but what they don\'t know won\'t hurt them, yes?', `VerifiedBuild` = 12340 WHERE `ID` = 1092;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Eliminate Gerenzo? Now there is a prospect that I have no objections to.$b$bGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces.', `VerifiedBuild` = 12340 WHERE `ID` = 1095;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Look at that thing... it\'d take a gnome to come up with something like that. I can\'t understand why you\'d cut off an arm, and replace it with that, when you could just keep both arms and add a third!$b$bGnomes, I tell you...$b$bAt least Gerenzo\'s out of commission. Hopefully that\'ll be enough proof, and Sputtervalve will assign me to one of the Tinkers\' Union workshops in Gadgetzan or maybe even Undermine.', `VerifiedBuild` = 12340 WHERE `ID` = 1096;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re here to help with my delivery? Very good!', `VerifiedBuild` = 12340 WHERE `ID` = 1097;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages...', `VerifiedBuild` = 12340 WHERE `ID` = 1100;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The crone has been laid to rest. This is fantastic news, $N.$B$BIn these times of peril, it is refreshing to see one as brave as yourself.$B$BWith Razorflank\'s minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.$B$BHowever, I fear the answer to that question lies in treachery as well...', `VerifiedBuild` = 12340 WHERE `ID` = 1101;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'All right! This venom is going to work great! Thanks, $N!$b$bNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat! Where are my notes!?', `VerifiedBuild` = 12340 WHERE `ID` = 1104;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 5, `Emote3` = 11, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got them! Thanks, $N!$B$BWow, these shells are harder than I thought! When I work with them I\'ll probably need a whole box full of tools!', `VerifiedBuild` = 12340 WHERE `ID` = 1105;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Fizzle sent you? Well that changes things! Of course I\'ll help you. Fizzle and his brother are two of the few people who don\'t want me dead!$b$bSo Fizzle wants to make pistons, eh? Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!', `VerifiedBuild` = 12340 WHERE `ID` = 1106;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N! After I grind these down and fuse them with a few other ingredients, the composite will be ready. And after that, the car will be safe from its own speed.$b$bSafe, as long as it doesn\'t hit anything...', `VerifiedBuild` = 12340 WHERE `ID` = 1107;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, these will do fine. Now let\'s put them in some heat and see how they fare...', `VerifiedBuild` = 12340 WHERE `ID` = 1108;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Whoa, look at all that! There\'s some good stuff in that heap of junk. I\'m sure I can pawn it off for a hefty sum.$b$bAnd... is that an ear I see squashed between those two sheets of metal?? Ouch! Heh, I sure wouldn\'t want to be that pilot!$b$bThanks, $N. Here\'s your pay. And here\'s some advice, free of charge...$b$bIf you look hard enough, you can always find profit in someone else\'s tragedy.', `VerifiedBuild` = 12340 WHERE `ID` = 1110;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you got them! Now we need to get them to the gnomes. But first...$b$bLet\'s take out one small item...', `VerifiedBuild` = 12340 WHERE `ID` = 1112;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'There they are! My hydro ratchets and repeater bolts! These will do just fine. Thank you!', `VerifiedBuild` = 12340 WHERE `ID` = 1114;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful! Fizzlebub came through! I\'ll remember that next time I see him.$b$bAnd thank you, $N. You\'re doing a great job, and we both stand to make a lot of money from this...', `VerifiedBuild` = 12340 WHERE `ID` = 1119;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.$B$BI appreciate your interest and eagerness to assist the Cenarion Circle. The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade. The preservation of Azeroth is a common goal we both share.$B$BYou are among friends here, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1123;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Rabine sent you, did he? Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.$b$bI wasn\'t alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past. With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago.', `VerifiedBuild` = 12340 WHERE `ID` = 1124;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise. It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.$b$bI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know. When you\'re ready, however, I\'d like to ask for your assistance once more...', `VerifiedBuild` = 12340 WHERE `ID` = 1125;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What the... what is it?$b$bIt has the shape of a... box, maybe? It\'s encrusted over something fierce. Wait, there a portion here that\'s exposed... is that a book underneath all this gunk?$b$bI think you\'ve stumbled across quite the find here, $N... well, at least I hope it is. Perhaps it is a journal or a log from ancient times, preserved in this shell.$b$bI think I know a way to find out what this is.', `VerifiedBuild` = 12340 WHERE `ID` = 1126;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, $N, you have come. Now, are you prepared to journey through distant lands?$B$BIf so, young $C, then listen on...', `VerifiedBuild` = 12340 WHERE `ID` = 1130;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.$b$bAnd that, $N, is your lesson this day.', `VerifiedBuild` = 12340 WHERE `ID` = 1131;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.$B$BYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings\' venom.', `VerifiedBuild` = 12340 WHERE `ID` = 1134;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Both strength and cunning were needed to find and defeat Frostmaw, $N. You have both.$b$bYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac. It will one day lead you through all the Earthmother\'s lands, for such is the way of the hunter.', `VerifiedBuild` = 12340 WHERE `ID` = 1136;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, you\'re back! You found Martek? You spoke with him? What did he say? Can he help??$b$bTell me, tell me, tell me!!', `VerifiedBuild` = 12340 WHERE `ID` = 1137;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wow, these fine crab chunks are what I need.  Thanks $N!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don\'t make any good crab dishes.$B$BI told you all about crabs, right?', `VerifiedBuild` = 12340 WHERE `ID` = 1138;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.>$B$B$N, this is amazing. I shall have this brought to the king\'s mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you.', `VerifiedBuild` = 12340 WHERE `ID` = 1139;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.$B$BNonetheless, with the soulgems destroyed, Athrikus\' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult.', `VerifiedBuild` = 12340 WHERE `ID` = 1140;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Them\'s some real nice groupers, $N!  Thanks for helping me out!$B$BYou\'re at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don\'t do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole.', `VerifiedBuild` = 12340 WHERE `ID` = 1141;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat.', `VerifiedBuild` = 12340 WHERE `ID` = 1143;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Don\'t mind the thundering echoes off the mountains\' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.$B$BBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant.', `VerifiedBuild` = 12340 WHERE `ID` = 1146;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ha! That ichor you\'re covered in actually makes you prettier, $N! It certainly does make you reek at the same time though. Don\'t stand too close to the kodo; you\'ll either start a stampede or cause them to go into heat.$B$BI think my companions would agree that your smell alone is proof you\'ve done your part to help us against those insect creatures. Thank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1147;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahh, you\'ve seen Moktar recently? He always be lookin\' out for me. I\'m sorry to hear he spends his time watching over his little war band instead of seeing battle, but I\'m sure he be takin\' great joy in killing members of the Explorers\' League.$B$BYou be smart to bring me these specimens, $N. Along with the eggs we be findin\' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin\'.', `VerifiedBuild` = 12340 WHERE `ID` = 1148;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.$b$bIf you are willing, then the next of your tests is ready.', `VerifiedBuild` = 12340 WHERE `ID` = 1149;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Grenka was powerful, even by troll standards. You should be proud of your accomplishment this day.$b$bDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test.', `VerifiedBuild` = 12340 WHERE `ID` = 1150;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed.', `VerifiedBuild` = 12340 WHERE `ID` = 1151;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world\'s pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.$b$bNow you stand before Braug.', `VerifiedBuild` = 12340 WHERE `ID` = 1152;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A good sample, $N. A good sample indeed.$B$BThose travelers can no longer lord over me the ore they found, now that you have been successful.$B$BI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.$B$BI shall not forget your help, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1153;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is the book I named. There is hope you will answer my question correctly then... unless you\'ve forgotten to study its contents.$b$bWhen you are prepared, speak to me again and I shall ask a question of you.', `VerifiedBuild` = 12340 WHERE `ID` = 1154;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 274, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 2000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Braug sent you? Impossible.$b$b<Parqual looks you up and down.>$b$bBraved Dor\'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You\'re probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1159;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is the book I sent you to search for.$b$b<Parqual slowly caresses his hand over the top of the book as he stares down at it.>$b$bSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!', `VerifiedBuild` = 12340 WHERE `ID` = 1160;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You stand before me as a figure of vengeance, and I bow down before you in thanks.$B$BWith that cow\'s death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.', `VerifiedBuild` = 12340 WHERE `ID` = 1164;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, it\'s good to see you again, $N! The strangest things have been happening around here, I\'m glad you showed up!$B$BIt was very strange, $N. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What\'s going on?', `VerifiedBuild` = 12340 WHERE `ID` = 1167;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Why you tell me \'bout dragons? Me no like dragons. Me like it here. No dragons here.', `VerifiedBuild` = 12340 WHERE `ID` = 1170;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That cowardly fat mass Mok\'Morokk fled like a scared child. You have done a great service, $N.$B$BNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.', `VerifiedBuild` = 12340 WHERE `ID` = 1173;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I hope you didn\'t kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I\'d rather not have to take a shovel out to clean up.', `VerifiedBuild` = 12340 WHERE `ID` = 1175;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah!  Longbeard sent you with a load of helmets!  Hooray!$B$BNow maybe we can talk a pilot into driving our car...', `VerifiedBuild` = 12340 WHERE `ID` = 1179;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Shipments to Ratchet? Let me just check the logbooks...$b$bNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn\'t been much else, other than building supplies and tools. Definitely no race parts.', `VerifiedBuild` = 12340 WHERE `ID` = 1180;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hey, it\'s you again! Well, I mean you - as in the you that is $N! Yes - that you!$B$BHey, let me start over!$B$BThat object you found in Silithus - it was in fact a book. It was a journal written in a very ancient dialect of what we now call the Darnassian tongue. It\'ll take a while, but I\'m going to go over it very thoroughly. I thought you should know that what you found was extremely valuable for the Circle.$B$BThe den mother\'s all excited and everything!', `VerifiedBuild` = 12340 WHERE `ID` = 1185;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re the $R that\'s been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.$b$bNow look at me! The goblin racing team\'s pilot extraordinaire!', `VerifiedBuild` = 12340 WHERE `ID` = 1186;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I\'ll be around the track so fast I\'ll beat the gnomes twice!', `VerifiedBuild` = 12340 WHERE `ID` = 1187;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.$B$BMy thanks, $N. Now I must begin to decipher the mysteries you have brought to me.', `VerifiedBuild` = 12340 WHERE `ID` = 1197;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You are no doubt of brave and noble blood, $N. The Argent Dawn commends you for your efforts against evil.', `VerifiedBuild` = 12340 WHERE `ID` = 1199;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 66, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Kelris has eluded us for quite some time.$B$BIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.$B$BBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.$B$BBy the light! To sacrifice someone to a servant of an Old God for one\'s personal gain is beyond reproachful!$B$BYou have done a great deed, $N. I salute you on behalf of the Argent Dawn.', `VerifiedBuild` = 12340 WHERE `ID` = 1200;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I commend you, $N. This was not an easy mission. But the documents you gained are valued greatly by our superiors.', `VerifiedBuild` = 12340 WHERE `ID` = 1202;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 36, `Emote3` = 4, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s a good blade. It has a good swing. It\'s a good swing blade. Thank you. Thank you, thank you, thank you!!! Now I want to try it....$B$BLater. I\'ll try it later. But like I was saying... thanks.', `VerifiedBuild` = 12340 WHERE `ID` = 1203;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These will do fine! Thank you, $N!$B$BNow I\'ll try different cooking techniques on these tongues to find the best way to bring out their flavor.$B$BEventually I\'ll have a dish worthy of serving at the Blue Recluse in Stormwind!', `VerifiedBuild` = 12340 WHERE `ID` = 1204;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N.$b$bI am sure the hunt was not easy, but it is good to know the beast\'s pain has finally ended.', `VerifiedBuild` = 12340 WHERE `ID` = 1205;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 3, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got the eyes! You got the eyes! Tasty, tasty spider eyes!$B$BSome eyes... when you stare at them they stare back. Eat those last. They keep you company... out in the swamp.$B$BHello, little spider eyes. Hello! You taste like chicken. Gooey, salty chicken!$B$BMmmh.', `VerifiedBuild` = 12340 WHERE `ID` = 1206;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, that\'s the spice!  Now here\'s some swampy good stew.', `VerifiedBuild` = 12340 WHERE `ID` = 1218;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hm... I can\'t read orcish very well, but this looks like a report... written by an orc spy!', `VerifiedBuild` = 12340 WHERE `ID` = 1219;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A report from an orc spy!  How did you find this?  No matter -- let\'s see what it says...', `VerifiedBuild` = 12340 WHERE `ID` = 1220;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you got them! I can sell these to my contacts for a bundle!$B$BThanks for the delivery, $N! You are a great partner.', `VerifiedBuild` = 12340 WHERE `ID` = 1221;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Mr. Ignatz was just here with the bogbean leaves, and he told me you helped him out of some real trouble.$B$BThank you, $N.  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind.', `VerifiedBuild` = 12340 WHERE `ID` = 1222;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good work, $N. Our agent, Marg Nighteye, was stationed outside Theramore. He was charged to spy on the city. $b$bThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...', `VerifiedBuild` = 12340 WHERE `ID` = 1238;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is the head of Marg Nighteye! As I feared, he is dead.$b$bLook at the wound on his neck! Could a weapon have made that ragged cut, or did some beast slay our agent?$b$bThis is a mystery we must solve, $N. We must discover if Marg\'s death was at the hands of the Alliance!', `VerifiedBuild` = 12340 WHERE `ID` = 1239;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, I now see. The spirit of this orc is bound in our world, boiling with rage from a task yet undone.$b$bWell, let us have words with this angry orc...', `VerifiedBuild` = 12340 WHERE `ID` = 1240;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm... <Jorgen looks up at you through squinted eyes.>$b$bAll right. I\'ll help ya, but not because I want to, but because I\'m obligated.$b$bAnd let\'s get one thing straight: you\'re knowin\' far more than you should to begin with. Let\'s keep this our little secret, and don\'t go blabbin\' at any taverns about anything you find out. Understand?', `VerifiedBuild` = 12340 WHERE `ID` = 1241;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I\'m sorry, a letter for me? Well, I\'ll be... not often you get a delivery that\'s not a crate or barrel when all you do is work. Let\'s see what this is about.$B$B<Elling looks up at you while he opens the letter.>$B$BYou look a little tense, you okay, $N?', `VerifiedBuild` = 12340 WHERE `ID` = 1242;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 11, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, Trias sent you, huh? That\'s a little different.$B$BFeel free to fight whatever monstrosities come at you from the darkness. I\'m sure you\'ll be able to handle it pretty easily if you\'re the type to be hanging around with the likes of him.$B$BSo, what does my friend need of me on such a gloomy day as this?', `VerifiedBuild` = 12340 WHERE `ID` = 1243;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re back safe and sound. Couldn\'t ask for much more than that, could you?$B$BNow, let\'s see what we have here. This looks pretty official as far as any Defias documents I\'ve seen. But it could be a dupe just to throw you off track of whatever it is you\'re looking for.', `VerifiedBuild` = 12340 WHERE `ID` = 1244;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.$B$BSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what\'s this? Fist? That\'s a familiar name.', `VerifiedBuild` = 12340 WHERE `ID` = 1245;

UPDATE `quest_offer_reward` SET `Emote1` = 14, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What?!$B$BYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with.', `VerifiedBuild` = 12340 WHERE `ID` = 1246;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good to see you\'re still alive, $N. So, it went well with Dashel then, huh?$B$BI\'ve been reading up more on this plan of theirs, and although it doesn\'t state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.$B$BThis Slim that Dashel mentioned doesn\'t have any other name written here, but if you say he\'s in Menethil, then that\'s a start.', `VerifiedBuild` = 12340 WHERE `ID` = 1247;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 1, `Emote3` = 6, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome, welcome, welcome, $N. Good of you to join us. Perhaps an ale today? Or some mutton?$B$BName your pleasure and I\'ll see to it that you\'re taken care of. My name is Mikhail, and I look forward to serving you.$B$BHmm? What\'s that? Trias? Keep your voice down, my friend. This isn\'t something for the whole tavern to hear about.', `VerifiedBuild` = 12340 WHERE `ID` = 1248;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 6, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Caught him, huh? Good for you. I\'m surprised that was Slim.$B$BI\'ll be honest, I never thought I\'d miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don\'t mention that to Elling--he\'d probably try and get me to come back to Stormwind if he heard I missed the action.$B$BI\'m glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask.', `VerifiedBuild` = 12340 WHERE `ID` = 1249;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'THE KING?! I mean... the king? The real king? Are you joking? You didn\'t mention you were looking for the king\'s kidnappers. I didn\'t even hear he was missing--that would explain his son being crowned some.$B$BI\'ll send word to Elling right away. He\'ll want to know you\'re on the trail.$B$BI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue\'s got to have honor when it comes to some things.$B$BThe key now is to find this Hendel. And I think I can help with that.', `VerifiedBuild` = 12340 WHERE `ID` = 1250;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s never good news when a guard\'s badge is brought to me.$b$bSometimes it\'s a man or woman who\'s fallen in battle, and I\'m left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it\'s even worse than that.', `VerifiedBuild` = 12340 WHERE `ID` = 1252;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hm, I\'m no expert with the construction of arms and armor. Their use, yes, but not their making.$b$bThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.', `VerifiedBuild` = 12340 WHERE `ID` = 1253;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These are wonderful specimens, $N! The shells are in perfect condition, and the meat is pink and tender. The blood of a chef is in your veins, I\'m sure of it!', `VerifiedBuild` = 12340 WHERE `ID` = 1258;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, my uncle sent you, did he?$b$bWell I\'ve been researching recipes and I have some leads, but I need help.$b$bHelp from someone willing to get his feet wet.', `VerifiedBuild` = 12340 WHERE `ID` = 1260;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This pendant was worn by a soldier of Stormwind??$B$BThank you, $N. You have revealed the secret of Marg\'s death. But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 1261;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A pleasure to meet you, $N. I am Commander Samaul. I\'m in charge of Miss Proudmoore\'s forces here in Theramore.$B$BAlthough I\'m quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there\'s no reason for me to be rude if you need my help.$B$BIf you plan on traveling out of the city, I\'d suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons.', `VerifiedBuild` = 12340 WHERE `ID` = 1264;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice.', `VerifiedBuild` = 12340 WHERE `ID` = 1265;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, citizen. This is a dangerous place to be wandering about. I wouldn\'t hang around too long if you value your life.$B$BIf you keep your questions short, I\'ll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there\'s a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we\'ve had little progress.', `VerifiedBuild` = 12340 WHERE `ID` = 1266;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Let me be first to thank you for all you\'ve done, $n. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn\'t make your acquaintance under better circumstances.$b$bUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.$b$bWhen you visit Theramore in the future, seek me out and I shall try to keep you appraised of the situation.$b$bThank you again, $n.', `VerifiedBuild` = 12340 WHERE `ID` = 1267;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My nephew said you aided him with his research in Dustwallow, and that you helped his associate out of a tight spot.  Well, we Sterns stick together and we don\'t ignore our friends!$B$BSo wash your hands, $N, because we\'re about to throw a party in your honor!', `VerifiedBuild` = 12340 WHERE `ID` = 1271;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, $N. I am Bishop DeLavey.$B$BNo doubt if you\'re asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.$B$BI\'m afraid I don\'t have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.', `VerifiedBuild` = 12340 WHERE `ID` = 1274;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have traveled far and undoubtedly faced great peril.$B$BYour actions have been selfless. \'Tis for the good of all Azeroth that you help me with my research. I thank you, $N, for all that you have done.$B$BNow if you\'ll excuse me I have much work to do....', `VerifiedBuild` = 12340 WHERE `ID` = 1275;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'James Hyal\'s his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...$B$BMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.$B$BJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We\'re investigating, but haven\'t had much luck. If you want to help out, see what you can find in the rubble.', `VerifiedBuild` = 12340 WHERE `ID` = 1282;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.$b$bI\'ll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.', `VerifiedBuild` = 12340 WHERE `ID` = 1284;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Missing? That would be Tesoran\'s kind way of saying traitor.$b$bNo doubt he\'s one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn\'t that a delicious irony? The deserters accuse us of betraying the Alliance.', `VerifiedBuild` = 12340 WHERE `ID` = 1285;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.', `VerifiedBuild` = 12340 WHERE `ID` = 1287;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'James? Oh, he left quite some time ago.$B$BFelt the second wind of patriotism, I suppose. Not hard to see why he would. With all the insanity in Lordaeron, many people joined up with Jaina Proudmoore when she went across the sea.', `VerifiedBuild` = 12340 WHERE `ID` = 1301;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'James Hyal, James Hyal... Why does that name sound so familiar?$b$bOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He\'s handling the investigation.', `VerifiedBuild` = 12340 WHERE `ID` = 1302;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it\'s certainly not my work.', `VerifiedBuild` = 12340 WHERE `ID` = 1319;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s not much information to work on, but we\'ll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.', `VerifiedBuild` = 12340 WHERE `ID` = 1320;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I assure you, we\'re all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we\'ll see about finding the King.$B$BI\'m sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment.', `VerifiedBuild` = 12340 WHERE `ID` = 1324;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, a request from one of the Stormpikes. That\'s a proud clan, full of quality dwarves. Rich ones, too.$B$BThank you, $N. I\'ll get to work on Mountaineer Stormpike\'s shield by the end of the day.', `VerifiedBuild` = 12340 WHERE `ID` = 1338;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s right.  I have a task that I can\'t do while I\'m guarding.  In fact, it\'ll take you far from Loch Modan.$B$BYour perfect chance for adventure!', `VerifiedBuild` = 12340 WHERE `ID` = 1339;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, very good. If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.$b$bThis is a welcome delivery, $N. Your reward is well earned.', `VerifiedBuild` = 12340 WHERE `ID` = 1358;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, the heart samples of which Renferrel spoke. I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered.', `VerifiedBuild` = 12340 WHERE `ID` = 1359;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, I feel complete again - thank you kindly.$B$BSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!', `VerifiedBuild` = 12340 WHERE `ID` = 1360;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You are here on orders from Regthar? Then you are here to deal with the centaur. Good.$B$BI hope you\'re rested. I don\'t know how our campaign against the centaur will end, but I know the struggle will be long.$B$BHave a seat, and listen.', `VerifiedBuild` = 12340 WHERE `ID` = 1362;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done. This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.$B$BThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others.', `VerifiedBuild` = 12340 WHERE `ID` = 1365;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'By now, the centaur must know your name. I\'m sure they know it, and respect it, and fear it. And just as they know you, they know the banner under which you ride.$B$BThe banner of the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 1366;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Splendid, $N! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.$B$BGive me but a moment to prepare the pois - I mean prepare the truth serum.', `VerifiedBuild` = 12340 WHERE `ID` = 1383;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the ears. Well done.$B$BYour service to the Alliance is unquestioned, $N. The blood you spilled in Desolace will, no doubt, save countless lives.', `VerifiedBuild` = 12340 WHERE `ID` = 1387;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I knew old Faustin would come up with something good! You were a tremendous help, no doubt.$B$BNow let\'s get down to business, shall we?', `VerifiedBuild` = 12340 WHERE `ID` = 1388;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. We, are in your debt.', `VerifiedBuild` = 12340 WHERE `ID` = 1389;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A drink for me? How kind. It\'s been days since they\'ve allowed me to drink. Let me drink this down and then I\'ll tell you what I\'ve learned....', `VerifiedBuild` = 12340 WHERE `ID` = 1391;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, $N. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.$b$bAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end.', `VerifiedBuild` = 12340 WHERE `ID` = 1394;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the powerstones! The mages will be happy to see these!$B$BMany thanks, $N. I know your trip from Darkshire was not an easy one.', `VerifiedBuild` = 12340 WHERE `ID` = 1395;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The sounds of animals are now faint, more distant. Thank you, $N. Now let\'s hope they don\'t return!', `VerifiedBuild` = 12340 WHERE `ID` = 1396;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This wood is light, but tough. Thank you, $N. It will work nicely.', `VerifiedBuild` = 12340 WHERE `ID` = 1398;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Helgrum wants a report, eh? I sent an outrunner to Stonard not three days past. Did he fail his mission? If Stonard does not have my report, then it appears he did fail.$b$bLet\'s hope the next runner I send has more skill, or more luck.', `VerifiedBuild` = 12340 WHERE `ID` = 1418;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s a nice collection of jawbones, $N. Now those coyotes won\'t be tearing through our supplies for scraps.$B$BWell done. The coyotes of the Badlands aren\'t easy prey. Your deed shows me that you might just survive here.', `VerifiedBuild` = 12340 WHERE `ID` = 1419;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. From Neeka\'s report, I see the Alliance is not without its own problems. And we may find that some enemies are shared between us.', `VerifiedBuild` = 12340 WHERE `ID` = 1420;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you found them! With these, the wizards in Nethergarde may continue their work. I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance.', `VerifiedBuild` = 12340 WHERE `ID` = 1421;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Be silent a moment, $C. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men.', `VerifiedBuild` = 12340 WHERE `ID` = 1422;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, thank you $N! So many supplies are lost from Darkshire to here. It\'s good to see that some are recovered.', `VerifiedBuild` = 12340 WHERE `ID` = 1423;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your diligence in collecting the Atal\'ai artifacts is worthy of praise, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1424;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What? A package from Biggs\' caravan? We thought it, and he, were lost.$B$BThank you, $N. With luck, these supplies will carry the much needed reagent, Azoran Crystals. Our stock is running low...', `VerifiedBuild` = 12340 WHERE `ID` = 1425;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you\'ve caused, and that is good.$B$BLet their gurgling screams overshadow the sea\'s roar long into the night. I shall smile every time I hear one of them silenced.$B$BReturn to me if you wish to slay more of the fish men. I will gladly reward you again.', `VerifiedBuild` = 12340 WHERE `ID` = 1426;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, $N, you\'ve returned. Good. I\'ve finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar\'s face, I offer one of them to you.', `VerifiedBuild` = 12340 WHERE `ID` = 1427;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $C. I call for more of their blood. Let all the fish men perish.', `VerifiedBuild` = 12340 WHERE `ID` = 1428;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You bring me the summoning artifacts of the Atail\'ai?$b$bI see Jammal\'an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?', `VerifiedBuild` = 12340 WHERE `ID` = 1429;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, this should be perfect. I can\'t wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious.', `VerifiedBuild` = 12340 WHERE `ID` = 1430;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Putanni, noble $C. I am Keldran, student of magic... and other mystical arts.$b$bThe business Craven sent you here to speak to me about requires a touch more subtlety than you\'ve previously needed, but that does not mean you can not still aid our cause.$b$bPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.$b$bIt starts with appearances, $N. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us.', `VerifiedBuild` = 12340 WHERE `ID` = 1431;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $C. You bring news from Orgrimmar; that is good.$b$bThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.$b$bIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 1432;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, yes. Aid from those loyal to the Warchief is always appreciated.$b$bMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.$b$bCome, come closer, $C. I shall explain to you my plan for removing the festering boil that is the Burning Blade.', `VerifiedBuild` = 12340 WHERE `ID` = 1433;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done well, $c. You have shown honor and dedication.$B$BWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.$B$BI thank you.', `VerifiedBuild` = 12340 WHERE `ID` = 1434;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you\'ve returned successful. That is good. Give me the gems and I shall put them someplace safe....$B$BMy tasks for you are complete, $C. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace.', `VerifiedBuild` = 12340 WHERE `ID` = 1435;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have returned from Desolace more than successful, $N. Thank you.$B$BThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.', `VerifiedBuild` = 12340 WHERE `ID` = 1436;

UPDATE `quest_offer_reward` SET `Emote1` = 20, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank Elune someone has finally come to help. Please, $C, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!$B$BI knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land\'s demon infestation.$B$BI fear the worst for him.', `VerifiedBuild` = 12340 WHERE `ID` = 1438;

UPDATE `quest_offer_reward` SET `Emote1` = 18, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 3000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is terrible! But I suppose it was necessary. If it wasn\'t by your hand, it would have surely been by that of my people\'s. I suppose I should thank you--please forgive me if it doesn\'t seem sincere. I mean no offense.$B$BWith the knowledge of my brother\'s fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.$B$BWhen you are ready, we can make our way to safety.', `VerifiedBuild` = 12340 WHERE `ID` = 1439;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. Dalinda made it safely back here to Nijel\'s Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you\'re well?$B$BIt pains me to know that both Tyranis and Dalinda didn\'t return, but the embarrassment of Tyranis\' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus.', `VerifiedBuild` = 12340 WHERE `ID` = 1440;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It has been quite some time since we spoke, $C. I hope your journey was successful.$b$bWhat knowledge did you gain from the exiled Atal\'ai in the Hinterlands?', `VerifiedBuild` = 12340 WHERE `ID` = 1444;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Brave $C, you have proven yourself to be a great champion of the Horde.$b$bNow this collection of fetishes of Hakkar must be dealt with at once!', `VerifiedBuild` = 12340 WHERE `ID` = 1445;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Jammal\'an\'s reckless trust of false visions led my people to their eternal doom.$b$bI thank you, $C, for avenging my exile. I mourn for my people. I have no home to return to.', `VerifiedBuild` = 12340 WHERE `ID` = 1446;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you came to me for a reason. What is it you need?', `VerifiedBuild` = 12340 WHERE `ID` = 1447;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Temple of Atal\'Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?$B$BAn amazing discovery, $C. But obviously something has gone terribly wrong.', `VerifiedBuild` = 12340 WHERE `ID` = 1448;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What do you want, laddy? Can\'t you see I\'ve got problems to take care of here? Who has time to stand around yapping with some $R chatterbox?$B$BThere are trolls coming out of the woodwork! Make it snappy.', `VerifiedBuild` = 12340 WHERE `ID` = 1449;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, yes. Of course I remember sending one of my gryphon riders to lend a hand to Brohann Caskbelly.$B$BAlways had a soft spot in my heart for the Explorers\' League. My father helped with the initial excavation team that discovered Uldaman as a matter of fact.$B$BI sent who I thought was my best gryphon rider at the time with Brohann. He was a chap by the name of Rhapsody Shindigger.$B$BAnd what a gryphon jockey he was! Well until...', `VerifiedBuild` = 12340 WHERE `ID` = 1450;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 14, `Emote3` = 33, `Emote4` = 5, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hiccup!$B$BI\'m a-lookin\' right at you but you keep bobbing up and down. Makin\' me dizzy. Hoho!$B$BHiccup!$B$BWhoa! Did ya feel that? Ground is a-shakin\', my friend. I need a drink.$B$BHiccup!', `VerifiedBuild` = 12340 WHERE `ID` = 1451;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 33, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.$B$BIt won\'t take but a moment for me to extract what I need from these gizzards and livers. Hiccup!$B$BThen I can distill me a fierce ol\' drink and finally tell ya what ya wanna know.$B$BHiccup!$B$BGetting shivers just thinking about that ol\' swamp.$B$BHiccup!$B$BLemme whip up a drink real fast.', `VerifiedBuild` = 12340 WHERE `ID` = 1452;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Glad to see the Reclaimers aren\'t in short supply of work, or adventurers willing to help out.$B$BI\'m Kreldig, $N. You\'ve made a smart move helpin\' out the Reclaimers. Everyone needs something these days: they\'ve lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there\'s no reason, for the right price, everyone can\'t find what they\'ve lost. ', `VerifiedBuild` = 12340 WHERE `ID` = 1453;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome back to Nijel\'s Point, $N. So, tell me what you found.$B$BWhat!? Nothing? An empty chest ain\'t gonna get us paid, I\'m afraid.$B$BTell me more about these marks you saw... these slashes.', `VerifiedBuild` = 12340 WHERE `ID` = 1455;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is great, $N! You found Karnitol\'s belongings!$B$BThose blasted naga, always causing trouble. I think I\'d rather spend my life at war with the Horde than have to go against their kind. You\'ve done a great service to the Reclaimers.', `VerifiedBuild` = 12340 WHERE `ID` = 1456;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the Karnitol business in Desolace. Excellent!$B$BSo, the chest was destroyed, but the items are all here, huh? Well, I\'ll let him be the judge of that. One good part about this business I got going on here is that if they\'re not satisfied, I can tell \'em to shove it! They\'re relyin\' on us to find their stuff... not make sure it\'s all pretty and in good shape when they get it back.$B$BGood work, $N. Let\'s see about gettin\' you paid.', `VerifiedBuild` = 12340 WHERE `ID` = 1457;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good good, $N. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.$B$BWhat say you to getting on with the next item on his list?', `VerifiedBuild` = 12340 WHERE `ID` = 1458;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your help here\'s a boon, $N. You\'re cutting my time spent here in Desolace by half at least. I\'ll be back in Ironforge warming my feet in no time with your help.$B$BWhen we get this list taken care of, and I\'m back home, look me up, I\'ll buy you an ale for sure.$B$BBut until then, let\'s get the rest of these reagents gathered.', `VerifiedBuild` = 12340 WHERE `ID` = 1459;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 6, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Infuriating! This entire fiasco!$B$BThe two of them were warned about how dangerous coming here would be. Now they\'re both missing... or worse.$B$BYou said you saw tracks heading to a fort nearby? That may be our best bet.$B$BFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde\'s beliefs, but they are evil and will slay you on sight if you\'re caught spying.', `VerifiedBuild` = 12340 WHERE `ID` = 1465;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Honestly? I wouldn\'t have thought it. You\'re amazing, $N. Taking on demons for a mage\'s experiments, and coming back in one piece to boot. Great job!$B$BI\'m personally gonna tell Roetten about you when I get back to Ironforge.', `VerifiedBuild` = 12340 WHERE `ID` = 1466;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the package for Leftwitch from Desolace. Excellent. I \'preciate the work, and your timeliness, $C. Glad to have you aboard for at least this small bit of work.$B$BI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week\'s work.', `VerifiedBuild` = 12340 WHERE `ID` = 1467;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Um... hi. My name is Randis and I guess you\'re looking after me? You\'re an adventurer, like my mom and dad were. I\'m happy to meet you.$B$BI hope we\'ll have a lot of fun together. I have some things I\'d like to do and the matron says you\'ll be like a big $gbrother:sister; to me during this week. I\'d like that a whole bunch, yes $gsir:lady;.', `VerifiedBuild` = 12340 WHERE `ID` = 1468;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Rhapsody Shindigger! That\'s right... how could I forget such a name?$B$BSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.$B$BBut this Atal\'ai artifact! Why, it\'s quite a find!', `VerifiedBuild` = 12340 WHERE `ID` = 1469;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Atal\'ai Tablets! Thank you, $N!$B$BOnce I deliver these to the Explorers\' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful.', `VerifiedBuild` = 12340 WHERE `ID` = 1475;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Andromath sent you? Very good. I have an important task for you...', `VerifiedBuild` = 12340 WHERE `ID` = 1477;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good, I see Ageron managed to find you, $n. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn.', `VerifiedBuild` = 12340 WHERE `ID` = 1478;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmm, these runes are indeed a language, $N, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon\'s signature: Lord Azrethoc.', `VerifiedBuild` = 12340 WHERE `ID` = 1480;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The shadowstalkers were unable to slay you, $c. Impressive... most impressive.$B$BThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.$B$BI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts.', `VerifiedBuild` = 12340 WHERE `ID` = 1481;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A precious oracle crystal... flawless... beautiful. Indeed.$B$BWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.$B$BTake a step back, $c, and let us see what this demon is, and where he may be found.', `VerifiedBuild` = 12340 WHERE `ID` = 1482;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he\'s up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor.', `VerifiedBuild` = 12340 WHERE `ID` = 1484;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your efforts shall not go unnoticed in gathering these hides, $N.$b$bThank you for your dedication.', `VerifiedBuild` = 12340 WHERE `ID` = 1486;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'As a Disciple of Naralex, I commend your bravery, $N.$b$bYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.$b$bThank you and may you prosper.', `VerifiedBuild` = 12340 WHERE `ID` = 1487;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A mighty victory for us all, $N. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.$B$BThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again.', `VerifiedBuild` = 12340 WHERE `ID` = 1488;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I bid you greetings, $N. You are welcome here, and I suggest you gather all your strength. For the task we now set before you ... is a dire one.', `VerifiedBuild` = 12340 WHERE `ID` = 1489;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, it is true. I know of the druids in the Wailing Caverns. I have seen their twisted, scaled faces. I know their crimes, and I know their plans.$b$bYou must stop them, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1490;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you got it! I can\'t wait to try it out. This is going to make me a fortune, I just know it!$B$BThank you, $N. Take this, and after I\'m rich I\'ll send you more, I promise!', `VerifiedBuild` = 12340 WHERE `ID` = 1491;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A small enough crate. Yes, I should be able to find room for this aboard the ship. It sails with the next tide, I trust this is soon enough? Excellent. Let me just enter it into my ledger.$B$BAll taken care of! Good day to you, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1492;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, apologies! I didn\'t realize you were here to help resupply our troops. The stuff you made will be a big help!$B$BHere are plans for some armor. I hope you find them useful.', `VerifiedBuild` = 12340 WHERE `ID` = 1578;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can\'t believe you found them! You must be the luckiest $R in Kalimdor!', `VerifiedBuild` = 12340 WHERE `ID` = 1579;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can\'t believe it! You found them! You are the best fisherman I\'ve ever seen!$b$bThank you, $N. And here, take these. Although you\'re so good and you probably don\'t need them, they will help you with your fishing.', `VerifiedBuild` = 12340 WHERE `ID` = 1580;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.$B$BHere, $N. Let me show you the pattern to make the Moonglow Vest.', `VerifiedBuild` = 12340 WHERE `ID` = 1582;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. This will help me out tremendously. With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I\'m always fixing armor and making new weapons for our troops.$B$BThe supplies you brought will give me a moment\'s peace. I will have enough time to teach you something...', `VerifiedBuild` = 12340 WHERE `ID` = 1618;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh ho! Have a drink with me, $N. You look tough on the outside, but let\'s see if your gut can handle a few mugs of the Pig and Whistle\'s strongest!!$B$BOr... were you here for a lesson?', `VerifiedBuild` = 12340 WHERE `ID` = 1638;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, fancy $gboy:girl;! What\'s a prissy thing like you doing in the Pig and Whistle? Be careful, or you might break a nail...', `VerifiedBuild` = 12340 WHERE `ID` = 1639;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re a lot tougher than you look!', `VerifiedBuild` = 12340 WHERE `ID` = 1640;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.', `VerifiedBuild` = 12340 WHERE `ID` = 1641;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 6, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello again, $N. How goes your studies of the Tome of Divinity?$B$BThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.$B$BBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.', `VerifiedBuild` = 12340 WHERE `ID` = 1642;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, hello, luv. How go your adventures? Oh, I\'m so glad to hear you\'re doing well.$B$BOh, me? Thank you for asking--I\'m doing well, all things considered.$B$BThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it\'s been tougher to make clothing for the children at the orphanage, but we\'ll manage. By \"we\" I mean my husband and I. He\'s up in Ironforge trying to seek help from the citizens there.', `VerifiedBuild` = 12340 WHERE `ID` = 1643;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N, thank you so much!$B$BThe children will be so pleased, and you\'ve saved me so much time. I\'ll now be able to focus on the children\'s other needs, and hopefully my John will be able to return home sooner than we thought.$B$BThank you again, $N. I knew I could rely on the charity of others. The Light be with you.', `VerifiedBuild` = 12340 WHERE `ID` = 1644;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 6, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here in Ironforge, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.', `VerifiedBuild` = 12340 WHERE `ID` = 1645;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 2, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'THE ORPHANAGE OF STOR... oh, sorry, didn\'t mean to shout at you, sir.$B$BMy name is John Turner. How are you?$B$BGood, good, glad to hear things go well for you. I\'ve had a long day of work already, and I miss my wife terribly, but that\'s the price you have to pay when there are mouths to feed and backs to clothe.', `VerifiedBuild` = 12340 WHERE `ID` = 1647;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is so wonderful of you, $N. Thank you again.$B$BYou\'re a noble man for doing this for me. It\'s no wonder you\'ve chosen to follow the Light. I wish there was some way I could repay you for all you\'ve done... what\'s that? It\'s the least you could do? See? That\'s what I\'m talking about, $N, noble to the end.$B$BBe safe, and may the Light protect you in your travels.', `VerifiedBuild` = 12340 WHERE `ID` = 1648;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 6, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you wish to petition me for a test of valor. Splendid.$B$BThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a man with your skills.$B$BThis test should not be taken lightly, $N. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.$B$BAre you prepared?', `VerifiedBuild` = 12340 WHERE `ID` = 1649;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 24, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, $N. I\'m assuming by all that armor and weapon of yours, you\'re either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan\'s gone.$B$B Well, let me introduce myself: I\'m Daphne Stilwell. It\'s a pleasure.$B$BNow, you\'re not too late... I\'ve only killed a half dozen of the scum since last sun up. They\'ve been a little slow getting \'round the bend up there, but they probably saw you coming, which means they\'ll probably be here any minute.', `VerifiedBuild` = 12340 WHERE `ID` = 1650;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We\'ve done it, $N! Thank you for your help. You were truly amazing out there. I never thought a $C could handle so many enemies at once.$B$BYou\'ve truly shown bravery in the face of overwhelming odds.', `VerifiedBuild` = 12340 WHERE `ID` = 1651;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 4, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, we meet again, $N, and you are in high spirits, I see.$B$BThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.$B$BDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.$B$BFor your valor, you will be rewarded.', `VerifiedBuild` = 12340 WHERE `ID` = 1652;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 6, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good day, $n. The Light is with you, I trust?$b$bWhat\'s that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she\'s... oh, thank goodness. I\'m so glad that she\'s safe. The Defias were a threat long before these attacks, but now the King\'s advisors cannot deny it.$b$bWhat else did Duthorian have to say?$b$bYou\'re the one that was sent to protect my wife? Then I thank you again, $n. I couldn\'t think of a better test of valor than that.', `VerifiedBuild` = 12340 WHERE `ID` = 1653;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is wonderful! You\'ve gotten all the items.$B$BI should have no problem forging you a grand weapon with these. I\'ve actually had the plans for doing this for some time. I just never had the opportunity to gather the goods. Thank you, $N.$B$BIt feels good to have my father\'s hammer again...and a Kor gem. I never thought I\'d see one of these myself.', `VerifiedBuild` = 12340 WHERE `ID` = 1654;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yup yup, this is it. Ha! If I\'d known you were really gonna head out there and fight some o\' them ogres, I woulda given you a list of things to get instead of just this one thing. But, you\'re not here doin\' business for me, are ya?.$B$BA deal\'s a deal; Jordan wanted a shipment of me alloy, that\'s what he\'s gonna get.$B$BTell \'em hello fer me, and be safe, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1655;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, well done! I hope the Alliance chokes on the foul gift we\'ve given them, much like we were forced to choke on the yoke of enslavement to the Scourge!$B$BYou\'ve kept the ideas of Hallow\'s End true, $N, and for that I salute you. As an extra bonus, let me share some of these Hallow\'s End treats I have with you. I think you might find them to be quite the enjoyable diversion!', `VerifiedBuild` = 12340 WHERE `ID` = 1657;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. The Wickerman Festival will continue to be trouble so long as the abominable Forsaken are allowed to haunt the remnants of Lordaeron. It is NOT a fitting tribute to that once proud kingdom, let me tell you...$B$BHere\'s some coin for any repairs you might need, and in the spirit of the season I\'ve also included some treats you might like. Happy Hallow\'s End - let\'s keep it as safe as possible here in Southshore.', `VerifiedBuild` = 12340 WHERE `ID` = 1658;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'There it is! He sure didn\'t want to part with it, but you were persuasive. Well done.$B$BNow for your lesson...', `VerifiedBuild` = 12340 WHERE `ID` = 1665;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Who\'s that?$B$BBurlguard, is that you?$B$BYou\'ll have to step a little closer. My eyes aren\'t what they used to be.$B$BWalking up like that, I thought you were a gnoll!', `VerifiedBuild` = 12340 WHERE `ID` = 1666;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you found it! I feared it was gone forever, used by the Defias to impersonate a Stormwind official. Well that won\'t happen now, thanks to you.$B$BHere are some weapons I used when I was a Marshal. I kept them in great shape--take your pick!', `VerifiedBuild` = 12340 WHERE `ID` = 1667;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I bid you greetings, $N. Your name rings loudly in Darnassus, for you show promise. But we shall soon see if you possess the strength of will to follow the path of the $C.', `VerifiedBuild` = 12340 WHERE `ID` = 1684;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.$B$BNo matter.$B$BYou\'ve gone too long without training, and a warlock without training isn\'t like to keep his head on his shoulders for long.', `VerifiedBuild` = 12340 WHERE `ID` = 1685;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Surena was talented, but not enough so to gain mastery of $C magic on her own. It\'s a shame to see talent wasted, but sometimes it is necessary.$B$BI hope my investment in you will bear different results.', `VerifiedBuild` = 12340 WHERE `ID` = 1688;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did better than I expected, $N, but as well as I\'d hoped. Now, you can learn to command your subjugated voidwalker, an ally you will find valuable in the trials that are sure to stand before you.$B$BI have nothing more to teach you at the present, but I am far from done with you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1689;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Now that\'s what I call efficiency!  You\'ve helped thin out the nomad\'s numbers enough now that we can start to think about how we can win back those water wells.$B$BThe Gadgetzan Water Company thanks you for your help, but we\'re far from done in dealing with those foul nomads.  Listen close - here\'s what we need next...', `VerifiedBuild` = 12340 WHERE `ID` = 1690;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Top notch work, $N... top notch! You\'ve thinned down the nomad population to a point where we can actually take the fight to them!$b$bIf you haven\'t already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!', `VerifiedBuild` = 12340 WHERE `ID` = 1691;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 25, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hah! So you heard of my challenge, did you?$B$BWell sit down and listen. Have a drink, and savor it... because it might be your last.', `VerifiedBuild` = 12340 WHERE `ID` = 1698;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You made it! Well done! Three cheers for $N!', `VerifiedBuild` = 12340 WHERE `ID` = 1699;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Furen wrote this? How dare he! Why, I taught him everything he knows! To think he could teach me something is outrageous! Outrageous!$B$BHm... but there is something in his notes that I\'d like to try...', `VerifiedBuild` = 12340 WHERE `ID` = 1700;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got it all? Amazing! I was afraid those chimaeras would eat you up for sure!$B$BWell let\'s get started on that armor...', `VerifiedBuild` = 12340 WHERE `ID` = 1701;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 273, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Barleybrew Scalder. Great stuff! So you\'ve been to see Yorus, eh?$B$BI can get you a shield, yes sir! You won\'t find a better one, and that\'s no lying!', `VerifiedBuild` = 12340 WHERE `ID` = 1702;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These are interesting, very interesting indeed. My dwarven colleague Furen has made quite a grand discovery!$B$BThank you, $N. It will be an honor to apply his new techniques to my own craftings.', `VerifiedBuild` = 12340 WHERE `ID` = 1703;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my! These notes are amazing! And what\'s more... they\'re incredible and they\'re stupendous and they make my knees go all a-wobbly!$B$BFuren had a breakthrough! A real breakthrough! I can\'t wait to try out his new technique!', `VerifiedBuild` = 12340 WHERE `ID` = 1704;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nice work! Now if you\'ll excuse me, I have some work to do myself...', `VerifiedBuild` = 12340 WHERE `ID` = 1705;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can barely believe it! Furen\'s technique was a success, and this armor should withstand tremendous levels of stress.$b$bHere you are, $n. And thank you. I wouldn\'t have believed Furen\'s discovery if you hadn\'t gathered the materials I needed to test it myself.', `VerifiedBuild` = 12340 WHERE `ID` = 1706;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent - the more water pouches we are able to reclaim, the further away from disaster we\'ll all be!  Keep \'em coming, and I will be sure to reward you for every five water pouches you bring me.', `VerifiedBuild` = 12340 WHERE `ID` = 1707;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s the stuff! Well done! Now let me get this smelted and hammered so I can apply Furen\'s technique with my own and then we can see what happens!$B$BOh my, oh my! I just know the armor will be very very very tough!', `VerifiedBuild` = 12340 WHERE `ID` = 1708;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here\'s your armor, $N. Furen\'s process worked brilliantly! Perfectly! Marvelously, truly!$B$BYou could run this armor over with a siege engine and it would spring right back into shape!', `VerifiedBuild` = 12340 WHERE `ID` = 1709;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, thank you. These will work splendidly!$B$BI will begin fashioning the armor immediately...', `VerifiedBuild` = 12340 WHERE `ID` = 1710;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I have finished with your piece of armor, and I am quite pleased. Furen\'s new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.$B$BThank you, $N. And may this serve you well in future battles.', `VerifiedBuild` = 12340 WHERE `ID` = 1711;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have gathered the items for my spell, and have shown me your strength and cunning. But the next stage of our quest is even more perilous.$b$bLet us hope your strength does not falter.', `VerifiedBuild` = 12340 WHERE `ID` = 1712;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did it! You defeated Cyclonian and gained the Whirlwind Heart!', `VerifiedBuild` = 12340 WHERE `ID` = 1713;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There\'s only so much room and so many teachers in Stormwind. With all the increased traffic, we\'re sure to attract attention sooner or later.', `VerifiedBuild` = 12340 WHERE `ID` = 1715;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.$B$BNo matter.$B$BYou\'ve gone too long without training, and a warlock without training isn\'t like to keep his head on his shoulders for long.', `VerifiedBuild` = 12340 WHERE `ID` = 1717;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello, $N. It\'s good to see you made it to Fray Island. I hope you find it to your liking...', `VerifiedBuild` = 12340 WHERE `ID` = 1718;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. You have passed The Affray!$B$BYou are a worthy warrior, and I am honored to teach you...', `VerifiedBuild` = 12340 WHERE `ID` = 1719;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I can tell this will do nicely, let me just work with it for a moment...$B$BTakar is a resourceful fellow to have around, isn\'t he? If only I could persuade him to move back to civilization.', `VerifiedBuild` = 12340 WHERE `ID` = 1738;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, well done, $N. I see we\'ve done right in deciding to train you. Your performance certainly does not disappoint.$B$BI\'ve no qualms in showing you the way to control your newly bound succubus. Observe carefully.', `VerifiedBuild` = 12340 WHERE `ID` = 1739;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you\'ve returned so quickly, huh? And what pray tell have you accomplished in your time away from here?$B$BWere you able to help a noble cause? Perhaps you\'ve learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Impressive, $N, those are surely the actions of one who follows the Light.$B$BSuch sacrifice will always be rewarded in time.', `VerifiedBuild` = 12340 WHERE `ID` = 1778;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 2, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '*cough*$B$BGood day to ya, $C. Don\'t mind me wounds, the good priest \'ere\'ll take care of ol\' Muiredon in time. Not needin\' the power of that Symbol of Life ya got there quite yet.$B$BSo, me wife sent ya o\'er to speak to me, huh? Fair \'nough. I\'ll take the time to talk to ya-I\'ll tell ya exactly wut happened to Muiredon and his best friend Narm, a $C jus\' like yerself.', `VerifiedBuild` = 12340 WHERE `ID` = 1779;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve returned so quickly, $N. And what have you accomplished in your time away from the Cathedral?$B$BHave you helped a noble cause? Perhaps you\'ve learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how... Well, I\'m impressed, $N, those are surely the actions of one who follows the Light and values others above oneself.$B$BSuch sacrifice will always be rewarded in time.', `VerifiedBuild` = 12340 WHERE `ID` = 1780;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 2, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '*cough*$B$BPleasure to meet you, $R. Don\'t mind my wounds, the good priest here can take care of ol\' Gazin this time. I won\'t be needing the power of that Symbol of Life you\'ve got there... not yet anyway.$B$BSo, Duthorian sent you to speak to me, huh? Fair enough. I\'ll tell you exactly what befell me and my friend Henze. And with any luck, and some skill on your part, perhaps you can still help us all.', `VerifiedBuild` = 12340 WHERE `ID` = 1781;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here\'s your armor, $N. This will stand up to the strongest assaults or my name isn\'t Furen Longbeard!$B$BAnd I have to thank you. I learned a lot while working with the materials$Byou brought me. I think I\'ll have another breakthrough one day!$B$BI\'m going to send what I learned to other$Bblacksmiths of the Alliance.$B$BI\'ll tell them you were a big help, and maybe they\'ll want to return the favor.', `VerifiedBuild` = 12340 WHERE `ID` = 1782;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can\'t thank you enough, $gbrother:sister;.$B$BI can only assume that Tiza and Muiredon sent you here to aid me if you carry the Symbol of Life.$B$BIt\'s true, I fell to the Dark Iron while trying to attain one of the scripts: I was able to hold on long enough to allow Muiredon to escape, but the Light had almost embraced me fully when you came along. The fact that you were powerful enough to use the Symbol means great things for you, but there\'s time to speak of that later.', `VerifiedBuild` = 12340 WHERE `ID` = 1783;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Haha! You\'ve done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin\' o\' the Light if I ever saw one... not includin\' me wife o\' course.$B$BThank ya again, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1784;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done all of Ironforge a great favor today, $N. I\'m proud to count you among us, and if you feel you\'re ready, I would like to bless you with this scroll. The Symbol of Life would only have worked when used by a $C who was ready for one of the Light\'s greatest blessings-the power to restore the dead back to life.$B$BI will teach you the ability to resurrect your companions. Use it wisely, $N, and thank you, on behalf of myself, my husband, and Ironforge.', `VerifiedBuild` = 12340 WHERE `ID` = 1785;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $Gbrother:sister;.$B$BSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?$B$BI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.$B$BBut you were able to bring me back: the ability to use the Symbol doesn\'t come to just anyone, $N. It bodes well for you that you were able to empower it with your own faith.', `VerifiedBuild` = 12340 WHERE `ID` = 1786;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful! You made it, and saved Henze. The Light is with you for sure, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 1787;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done well this day, $N. You should take some pride in what you\'ve accomplished.$B$BEven more so, you should be proud of your abilities. Not everyone can use the power of the Symbol of Life. Calling upon the Light to bring back the dead means you\'re prepared for one of the $C\'s greatest honors: the power of resurrection.$B$BYou shall have the power to bring back fallen companions much like you did for Henze.$B$BBe well, $N. The Light shines upon you and you should welcome it wholly.', `VerifiedBuild` = 12340 WHERE `ID` = 1788;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Make haste, $N, more than one life hangs in the balance if you fail.$B$BIf for some reason you fail to help Muiredon and Narm, then return to me and I will give you another Symbol of Life for your travels.$B$BDon\'t mistake my aid as simple charity, you must prove yourself worthy like any other $C and continual failure may reflect upon you later.', `VerifiedBuild` = 12340 WHERE `ID` = 1789;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Make haste, $N, more than one life hangs in the balance if you fail.$B$BIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.$B$BDon\'t mistake my aid as simple charity, you must prove yourself worthy like any other $C and continual failure may reflect upon you later.', `VerifiedBuild` = 12340 WHERE `ID` = 1790;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have traveled far, young $C. I see fire in your eyes. You seek a weapon of great power, yes?$B$BI can help you with your quest. And you can help me with mine.', `VerifiedBuild` = 12340 WHERE `ID` = 1791;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I have the whirlwind heart, and am ready to place it within your vessel of choice.$B$BChoose your weapon, $N, and know that its power is the power of Cyclonian.', `VerifiedBuild` = 12340 WHERE `ID` = 1792;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It has been proven that the Light is with you, $N, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?$B$BBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.', `VerifiedBuild` = 12340 WHERE `ID` = 1793;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This will do nicely, $N.$B$BAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on.', `VerifiedBuild` = 12340 WHERE `ID` = 1796;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, so Menara sent you. Fair enough... I suppose you may stay as my guest for the time being. But you must be on some pressing business - perhaps you\'re here seeking lost power? Maybe I\'m mistaken. Maybe corruption isn\'t too far away from you after all.', `VerifiedBuild` = 12340 WHERE `ID` = 1799;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That throne room was scary, $N! Even though it was empty, it felt like a great evil had happened there. I felt mad... but I also felt sad too. I understand why the matrons tell us such stories; I will never betray my people like that!$B$BThank you for taking me to the throne room, $N. I learned a lot.', `VerifiedBuild` = 12340 WHERE `ID` = 1800;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here it is, $N. A weapon worthy of a champion of the Light such as yourself. I\'ve named it after a great dwarven paladin who was a friend of mine. His name was Verigan... Bosch Verigan.$B$BPlease take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land.', `VerifiedBuild` = 12340 WHERE `ID` = 1806;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hmmm, now this is interesting. You\'ve more than proved your worth with this, $n. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think.', `VerifiedBuild` = 12340 WHERE `ID` = 1858;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have been sent to aid me in my task, $n?  Good.  It is heartening to see young mages eager to help in our cause...$b$bWhat cause, you ask?  In time, young one.  You shall know... in time.', `VerifiedBuild` = 12340 WHERE `ID` = 1860;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. I will test this water for magical properties. Let us hope that it contains none, or we may find that those who drink from Mirror Lake for too long will be adversely affected.$B$BHere, $N. Take this orb or staff as a token of your service. May it serve you well.', `VerifiedBuild` = 12340 WHERE `ID` = 1861;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent - the more water pouches we are able to reclaim, the further away from disaster we\'ll all be! Keep \'em coming, and I will be sure to reward you for every five water pouches you bring me.', `VerifiedBuild` = 12340 WHERE `ID` = 1878;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, I can see you have promise, yes you do! But it takes more than promise to be a good $c.  And if you\'re not a good $c, then you\'re a bad $c.  And bad mages are part of the problem, yes they are!$b$bOops, I\'m getting ahead of things.  Let\'s begin at the start!', `VerifiedBuild` = 12340 WHERE `ID` = 1879;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, splendid day!  When I made the gizmonitor I never realized how dependent on it I would become.  Now I can begin my studies anew!$b$bThank you, $n!  And here--these were my first tools as a $c.  They\'re a little scratched but they\'re well tested.  Take your pick--I\'m sure you\'ll find either of them useful.', `VerifiedBuild` = 12340 WHERE `ID` = 1880;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $n.  You were wise to answer my call, and wiser still if you heed what I next say...', `VerifiedBuild` = 12340 WHERE `ID` = 1881;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You find a nasty ball of water and decide to bring it to me? Who am I, the Earthen Ring or something?$b$bActually, that does give me an idea... perhaps you do need the Earthen Ring for this. I mean, if it helps clear up the situation at the lake for good, then I\'m all for it.$b$bYou know who the Earthen Ring are, $N?', `VerifiedBuild` = 12340 WHERE `ID` = 1918;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, I have a mission for you, here in the $C district. Listen closely, for there is no time to waste.', `VerifiedBuild` = 12340 WHERE `ID` = 1919;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well done!  I will study these creatures and, with diligence and luck, determine how they slipped into our world.$B$BYour value to the society of mages grows, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 1920;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, these are great pieces of linen.  I can make a fine robe with them.  And after I weave the rift gems into it, we\'ll have a garment fit for a $C!', `VerifiedBuild` = 12340 WHERE `ID` = 1921;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.$B$BIt is good to see that he did not, and that the seals we placed on Ur\'s Treatise on Shadow Magic still hold.', `VerifiedBuild` = 12340 WHERE `ID` = 1938;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $N. I am pleased to see you, and hope you have time to listen to an old man\'s words...', `VerifiedBuild` = 12340 WHERE `ID` = 1939;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nice specimens, these. I\'ll get right to work!', `VerifiedBuild` = 12340 WHERE `ID` = 1940;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here is your robe.  It\'s one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!', `VerifiedBuild` = 12340 WHERE `ID` = 1941;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 11, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your garment is ready!  And that silk you gathered was so nice... you don\'t mind if I made it a little short so that I\'d have some silk left over for me, do you?$B$BI\'m only joking.  It\'ll fit you great, and will be perfect for both adventure and formal dining.  Enjoy!', `VerifiedBuild` = 12340 WHERE `ID` = 1942;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Quiet!  I\'m in a delicate juncture and mustn\'t be disturbed!$B$BOne moment...', `VerifiedBuild` = 12340 WHERE `ID` = 1947;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Aha! You got the jade and made the bramble! Well done!$B$BIs that smoke I see rising from your ears? You might have gotten too close when the lightning struck the totem sticks, but don\'t worry. Being hit by lightning is good luck!', `VerifiedBuild` = 12340 WHERE `ID` = 1948;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 25, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What?  Speak up!  These old ears aren\'t as sharp as they used to be.$B$BWell, I hope you\'re here with a fresh mug of ale or some hot tips on the next race!  If not, then you best keep walking... because I have a polymorph wand with your name on it!', `VerifiedBuild` = 12340 WHERE `ID` = 1949;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, now I remember...$B$BI had forgotten about that little curse I put on Johnson.  I can\'t remember why I did it but I\'m sure it served him right, the little ingrate!', `VerifiedBuild` = 12340 WHERE `ID` = 1950;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s it!  It\'s just what I need to prepare for the ritual to create your wand!  I hope it wasn\'t too much trouble to find...', `VerifiedBuild` = 12340 WHERE `ID` = 1951;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here are the wands I made.  Take your pick!', `VerifiedBuild` = 12340 WHERE `ID` = 1952;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, yes.  You are here for an orb or a staff, $N?  Very well.  I will aid you in its construction.$B$BBut be forewarned--the process is a perilous one and could mean your death.$B$BOr my death.  Definitely someone\'s death... $B$BBut let\'s hope it\'s someone else\'s death, eh?', `VerifiedBuild` = 12340 WHERE `ID` = 1953;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, that\'s a nice one!  No, I don\'t mean it\'s \"nice\" like cool juice is nice on a hot day.$B$BIn fact, it\'s very NOT nice now that I think about it.  Not the juice.  The orb!$B$BFocus, $N!  We\'ll need you focused if we\'re ever to finish our task!', `VerifiedBuild` = 12340 WHERE `ID` = 1954;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Nicely done, $N! You gave that demon a lesson he won\'t soon forget.$B$BHe\'ll think twice before he sticks his ugly head back in this world, looking for the stupid mortal who beat him. Probably with friends this time. Big, scaly friends who\'d want nothing more than to tear you into little $R pieces.$B$BI didn\'t scare you, did I...$N?', `VerifiedBuild` = 12340 WHERE `ID` = 1955;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did it?  Well done!$B$BI was chatting with some of my colleagues and when your name came up they said, \"You know that $N sure works well under stress!\"$B$BBut when I told them I sent you to Uldaman against the obsidian sentinel, they said I was crazy!  They said, \"Tabetha, you\'re crazy!  There\'s no way $N could take on that sentinel!\"$B$BAnd I said, \"We\'ll see,\" and then they said \"Yeah, we\'ll see...\"$B$BWell we sure showed them, didn\'t we!', `VerifiedBuild` = 12340 WHERE `ID` = 1956;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did it!  I never doubted you for a second!  Ok, maybe for just a second, or two... but basically I didn\'t have much doubt.$B$BHonest.', `VerifiedBuild` = 12340 WHERE `ID` = 1957;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You should be proud of yourself, $N.  Many mages have fallen to the creatures you faced.$B$BThe Celestial Orb is ready.  Or if you\'d like I can mount it atop a staff.  It\'s up to you.  I\'d prefer the orb, but who am I to judge?', `VerifiedBuild` = 12340 WHERE `ID` = 1958;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done the movement a great service, $N. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!', `VerifiedBuild` = 12340 WHERE `ID` = 2038;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So Gnoarn doesn\'t trust my reconnaissance abilities? I wonder why...$b$bNevermind that, I need your assistance! Nay! The movement needs your assistance!', `VerifiedBuild` = 12340 WHERE `ID` = 2039;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. Thanks to you, Gnomeregan is one step closer to its day of liberation!', `VerifiedBuild` = 12340 WHERE `ID` = 2040;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Do you bring word from central command?', `VerifiedBuild` = 12340 WHERE `ID` = 2041;

UPDATE `quest_offer_reward` SET `Emote1` = 397, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yarrr... Ye be provin\' yerself to be more than a yella sea dog, landlubber.$B$BThe Cap\'n may promote ye to poop deck swabby if ye be keepin\' this up...', `VerifiedBuild` = 12340 WHERE `ID` = 2078;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin\' order and them beasties won\'t know what hit em!$B$BHrm, have ye seen me first mate?', `VerifiedBuild` = 12340 WHERE `ID` = 2098;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Our work has only just begun, $N. Are you prepared for your next task?', `VerifiedBuild` = 12340 WHERE `ID` = 2118;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Rest and relaxation for the tired and cold -- that\'s our motto! Please, take a seat by the fire and rest your weary bones.$B$BWould you like to try a sampling of some of our fine food and drink?', `VerifiedBuild` = 12340 WHERE `ID` = 2158;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.$B$BWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one\'s peace of body and mind is a sure path to failure.$B$BSo... rest.', `VerifiedBuild` = 12340 WHERE `ID` = 2159;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, at last, the supplies from Hands! I was beginning to worry, we\'ve had scarce word from Anvilmar ever since the troggs overran the pass.$b$bThanks for bring this to me, $N. And please, make yourself comfortable. You must be tired after your journey.', `VerifiedBuild` = 12340 WHERE `ID` = 2160;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, this is the food Ukor brought to the Valley of Trials. Did they not need it? Well, I guess they like to starve you heroes in training. Builds spirit, they say!$b$bThank you for returning the food. I\'ll stick it back on the shelves... but here, let me offer you some refreshment first!$b$bAnd don\'t forget to rest here in the inn. You may be a brave $C ready to take on the world, but if your energy is sapped you won\'t be doing yourself, or the Horde, much good.', `VerifiedBuild` = 12340 WHERE `ID` = 2161;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Fantastic! Try it and tell me what you think, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 2178;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes... I am the jeweler who made this necklace. I also am not in the business of handing out information as though it were free. Information is never free, friend. If I am going to help you out, you need to help ME out first.', `VerifiedBuild` = 12340 WHERE `ID` = 2198;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re all right in my book; I don\'t care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.$B$BNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the \"evil taint\" present at an excavation site in the Badlands called Uldaman.$B$BWell... that paladin died in Uldaman, and that was just the beginning of my woes.', `VerifiedBuild` = 12340 WHERE `ID` = 2199;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn\'t quite over just yet.$B$BNo, I\'m not trying to pull a fast one here, silly $C.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give.', `VerifiedBuild` = 12340 WHERE `ID` = 2201;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done $N, you\'ve proven your worth once again! The caps will be an interesting study, you betcha.$B$BAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...$B$BIf you are a skilled alchemist, then perhaps we might have some additional business to conduct. Regardless, I thank you for your assistance!', `VerifiedBuild` = 12340 WHERE `ID` = 2202;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years.', `VerifiedBuild` = 12340 WHERE `ID` = 2203;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well I\'ll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!$B$BYou\'re excited, aren\'t you?  All tingly with anticipation?  Now where did I put that spell focus at...', `VerifiedBuild` = 12340 WHERE `ID` = 2204;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found me - and by looking at you, I\'d say the run and subsequent search may have been a great strain on your system, both mentally and physically.$B$BWould you like Renzik to show you the way to an inn or are you ready for some work?', `VerifiedBuild` = 12340 WHERE `ID` = 2205;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper $C. Take this blade, $N. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.$B$BYou won\'t see us coming but you\'ll feel it when we get there...', `VerifiedBuild` = 12340 WHERE `ID` = 2206;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So ye think yer a right scoundrel? Destined to be one o\' Blackbeard\'s chosen few - an officer o\' the Hidden Circle?$B$BOnly a good fer nothin\' scallywag would think so highly o\' hisself.$B$BThat\'s exactly what we be lookin\' fer! Welcome aboard, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 2218;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Shhhh! Keep it down you daft fool. They\'ll hear us. ', `VerifiedBuild` = 12340 WHERE `ID` = 2238;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Long route? In the name o\' me own beard!$B$BYe done good, $N. Take this dagger and be gone with ye. The Circle will call upon ye again when step three be ready to be set into motion.$B$BWhat\'s step three? It comes right after step two - me putting me boot up yer backside.$B$BInterested?', `VerifiedBuild` = 12340 WHERE `ID` = 2239;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have seen the Chamber of Khaz\'mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.$B$BThank you, $N.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz\'mul will be ours!', `VerifiedBuild` = 12340 WHERE `ID` = 2240;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, well done! These should last me for a little while, at least. Here is your pay as promised.$B$BIf you\'re interested, I have some more reagents I could use. These, however, are only found in the depths of the Uldaman excavation. They will not be easy to get, but I will make it worth your while if you are interested in helping me again.$B$BPerhaps something more than some shiny coins, yes?', `VerifiedBuild` = 12340 WHERE `ID` = 2258;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What do you have there... oh my.  You found this where?$B$BNo, really?$B$BYou spoke to whom about what?$B$BNO, REALLY?!$B$BMy fine $C, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves\' enchanted creation!', `VerifiedBuild` = 12340 WHERE `ID` = 2279;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so your fingers are a little fat, eh? Don\'t worry, $N, I\'ve turned more useless thieves than you into accomplished rogues.', `VerifiedBuild` = 12340 WHERE `ID` = 2281;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Cracked it open, did you? Nice work, $N.$B$BIf you die now, we can rest easy knowing it was due to your own stupidity and not inexperience.', `VerifiedBuild` = 12340 WHERE `ID` = 2282;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You seem to have found the remains of the paladin that Dran had mentioned from before. Searching the remains uncovers what would appear to be his journal. The book is in poor condition, as dried blood has stained most of the text in the book. What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.$b$bYou will need the book translated if you are to glean any knowledge from it.', `VerifiedBuild` = 12340 WHERE `ID` = 2284;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s always good to have one of Hulfdan\'s rogues among our ranks!', `VerifiedBuild` = 12340 WHERE `ID` = 2298;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Keep yer voice down, $N, the guards may hear ye.', `VerifiedBuild` = 12340 WHERE `ID` = 2299;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Are you ready to get to work or do you need to take a nap before we get started?', `VerifiedBuild` = 12340 WHERE `ID` = 2300;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Mighty $C, I know what you are doing out here in the Badlands. I know you seek my gift of tongues. You\'re after the parts to that necklace you found in Uldaman.$b$bSurprised? Don\'t be - it\'s my job to know such things. Instead, let\'s discuss what you\'re going to do for a translated journal. Trust me - I\'m the only one you\'ll find that can translate it.$b$bBetter still, let me make you a better offer than Dran Droffers is, and it\'ll let you still complete your deal with them. Interested now, yes?', `VerifiedBuild` = 12340 WHERE `ID` = 2318;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You know a good deal when you see one - I knew I could count on you.$b$bIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand. I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld. Now, let\'s get this started...', `VerifiedBuild` = 12340 WHERE `ID` = 2338;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well done, $C.  Now the fruits of our redirection will pay themselves out handsomely.  I\'m finished with the necklace itself, and I am confident I can duplicate the construction process consistently.$B$BBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do.', `VerifiedBuild` = 12340 WHERE `ID` = 2339;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yep, it\'s all here. Say, mind if we keep the bag too? No? Thanks, appreciate it! Har!$b$bThis necklace will be our greatest haul yet! Don\'t feel too bad though; I\'m sure the necklace wouldn\'t fit you anyway. Har again!$b$bA deal is a deal, so here\'s your fee for the salvage. Our business is done here for now; check back later to see if we have more work. Until then, beat it!', `VerifiedBuild` = 12340 WHERE `ID` = 2340;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The power source you gave me exceeded every expectation I had for it. I was able to make both you and me a necklace, and I have enough left over to make at least three more. They will fetch quite the fee, with Droffers and Son Salvage none the wiser.$b$bHere you go, my friend. I give you my thanks on a splendid job... and something quite special for your trouble.', `VerifiedBuild` = 12340 WHERE `ID` = 2341;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'To deny Ravenholdt the artifact, would be to deny one\'s own existence. Well done, $C. You may yet walk among the assassins of Ravenholdt.$B$B As a young rogue adventuring in Darkshore, I discovered a tea that replenishes energy in combat. It has served me well throughout the years and now I pass on a taste of the thistle tea to you. Drink of it when you tire, $N, and fight with vigor once more!$B$B', `VerifiedBuild` = 0 WHERE `ID` = 2358;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This would explain the Defias drones you and Kearnen saw outside of the tower, $N. It would also explain the Venture Company\'s involvement with the Defias and the strange shipments out of Duskwood.$B$BAccording to this book, the Zanzil trolls in Stranglethorn have discovered a way to raise the dead through potions... or to be more specific: poison.$B$BYou\'ll be of no use to SI:7 without a firm understanding of poisons, $N -- especially with the recipe to create undeath at our fingertips.', `VerifiedBuild` = 12340 WHERE `ID` = 2359;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Mathias finally sent another agent to back me up, eh? Well I hope he\'s ready to hear some bad news.', `VerifiedBuild` = 12340 WHERE `ID` = 2360;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I gladly give you this necklace, mighty $C.  You have done me an invaluable service, and for that I thank you.  Wear it with pride, and make sure you mention loudly and repeatedly who made it for you!$B$BAlso, if you could toss in the fact that it really isn\'t cursed, that would be great.', `VerifiedBuild` = 12340 WHERE `ID` = 2361;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s about time you showed up! I was in danger of losing a bet with Olaf!$B$BHe wagered that his beard would grow to his knees before he saw another living $R. Well here you are, and as you can see Olaf\'s beard has a few more inches to go.$B$BThanks, $N. I\'ll split the winnings with you.', `VerifiedBuild` = 12340 WHERE `ID` = 2398;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s great, you found some!  Thanks a lot, $N.  You\'re the most dependable $r I\'ve met!$B$BI can\'t wait to try these on some devices I\'ve been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going...', `VerifiedBuild` = 12340 WHERE `ID` = 2418;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2438;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'As yes, a voucher from the Explorers\' League... and quite the valuable one, might I add.$B$BThe Explorers\' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward.', `VerifiedBuild` = 12340 WHERE `ID` = 2439;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Now I can repair my dreamcatcher. Thank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2459;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.$b$bI have discovered something quite disturbing!', `VerifiedBuild` = 12340 WHERE `ID` = 2498;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 200, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I knew you were more than capable of ridding the lake of that horrible beast.$B$BIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.$B$BThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.$B$BThank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2499;

