UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N.$b$bWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment.', `VerifiedBuild` = 12340 WHERE `ID` = 2541;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'How do you feel, $N? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!$b$bUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet.', `VerifiedBuild` = 12340 WHERE `ID` = 2581;

