UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The spirit of the boar illuminates your being, $N! I wonder, do you believe yourself to be as invulnerable as these beasts?', `VerifiedBuild` = 12340 WHERE `ID` = 2583;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I must warn you, $N, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null.', `VerifiedBuild` = 12340 WHERE `ID` = 2584;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Fascinating. This has been the most difficult of all assays to analyze.$b$bTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness.', `VerifiedBuild` = 12340 WHERE `ID` = 2585;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Fine work, $N. Here is one sample of the assay for you and the remaining nine will be used in my research.$b$bAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal.', `VerifiedBuild` = 12340 WHERE `ID` = 2586;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is wondrous, $N! My offering to you is a taste of the inner workings of the redstone basilisk.$B$BShould the compound be to your liking, more can always be made... for a price.', `VerifiedBuild` = 12340 WHERE `ID` = 2601;

