UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s about time! Just put the cheese on the table and skedaddle. Osborne will pay you on the way out.', `VerifiedBuild` = 12340 WHERE `ID` = 2607;

