UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Indeed, you have honored us all. Our thanks alone are not sufficient.', `VerifiedBuild` = 12340 WHERE `ID` = 2702;

