UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This troll tablet must be the \"secret\" that Rin\'ji was talking about.$B$BCovered with strange markings, you can not decipher what the tablet says.', `VerifiedBuild` = 12340 WHERE `ID` = 2742;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I will help you. Although, I do not think you fully understand what you are up against.', `VerifiedBuild` = 12340 WHERE `ID` = 2744;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 6, `Emote4` = 5, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What the...?! Don\'t sneak up on me like that! And keep your voice down! What in the name of the Shadow are doing sneakin\' up on me for? Can\'t you see I\'m busy, you daft fool?$b$bWhat do you mean, what am I doing? I\'m waiting for the next Dark Portal to open, what the heck do you think I\'m doing? Speak your peace and be off with you... \'fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain.', `VerifiedBuild` = 12340 WHERE `ID` = 2745;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These will do nicely, $N. Great job.$b$bI have the rest of the gear I\'ll need in my pack... thank the Light I just got a tailor friend of mine to make me a silk bag. I was running out of room carrying all my gear around.$b$bBefore Spybot heads in, let\'s get the details set so you know what you have to do.', `VerifiedBuild` = 12340 WHERE `ID` = 2746;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well now, you have one--amazing!$B$BI hope you always remember the good you have done today.', `VerifiedBuild` = 12340 WHERE `ID` = 2747;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N. I will be sending this egg to Darnassus where I hope it will soon hatch!$B$BPlease accept this as a symbol of my gratitude.', `VerifiedBuild` = 12340 WHERE `ID` = 2748;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you have found an ordinary egg, $N? Please give it to me... And we can only hope for the best.$B$BI don\'t have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there.', `VerifiedBuild` = 12340 WHERE `ID` = 2749;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am afraid I have bad news for you, $N. This egg is too far gone. I can take it from you so that it may be disposed of properly.$B$BPlease don\'t be discouraged; we cannot save them all. If you find yourself in Feralas again, please try again. Bring another egg for the Super Egg-O-Matic!', `VerifiedBuild` = 12340 WHERE `ID` = 2750;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It seems you are but another complacent lemming of the Warchief, $N. How disappointing.$b$bHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!', `VerifiedBuild` = 12340 WHERE `ID` = 2756;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'By Blackhoof\'s back hair -- finally, one worthy of the Mithril Order!$b$b', `VerifiedBuild` = 12340 WHERE `ID` = 2757;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N! Listen and learn.$B$BBlacksmithing never comes from here! <Hank points to his hammer.>$B$BBlacksmithing never comes from here! <Hank points to the anvil.>$B$BBlacksmithing only comes from here! <Hank points to his heart.>$B$BAnd now you know the origin of blacksmithing.', `VerifiedBuild` = 12340 WHERE `ID` = 2758;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'By Blackhoof\'s back hair -- finally, one worthy of the Mithril Order!', `VerifiedBuild` = 12340 WHERE `ID` = 2759;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, many years it has been since one has been worthy of the mithril order\'s initiation. We will start now!', `VerifiedBuild` = 12340 WHERE `ID` = 2760;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your work ethic is impeccable, $N! You are starting to understand the ways of Galvan mineralogy! Take this and learn from it all that you can.', `VerifiedBuild` = 12340 WHERE `ID` = 2761;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'She\'s a cruel mistress, is she not, $N? I\'m speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!', `VerifiedBuild` = 12340 WHERE `ID` = 2762;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'One can barely keep their eyes from leaving its splendor, $N. Aye, citrine is a glorious gem.$B$BPay attention and learn what such a discovery may teach us!', `VerifiedBuild` = 12340 WHERE `ID` = 2763;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Galvan the Ancient sent you??$B$B<Trenton bows.>$B$BIt is a great honor to meet another of the master\'s pupils!', `VerifiedBuild` = 12340 WHERE `ID` = 2764;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is only fitting that you receive a trinket of far greater power than the one you sacrificed to get here. Use it in good health, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2765;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, YOU\'RE the great savior of OOX-22/FE! I cannot even begin to express my thanks for your assistance! My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!$b$bPlease, take your choice of any of these items I have. Thank you again for your generous assistance $N, my robots and I are in your debt!', `VerifiedBuild` = 12340 WHERE `ID` = 2767;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found it!  Well done, $N!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!', `VerifiedBuild` = 12340 WHERE `ID` = 2768;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you want to help me?  Great!$B$BThere\'s a part I want for an experiment I\'m working on, and I need a brave $C like you to help me get it!', `VerifiedBuild` = 12340 WHERE `ID` = 2769;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting\'s demise, this might be just the thing to finally push those squatters off of Gadgetzan\'s water wells!$B$BBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You\'ve done a great service for us all.', `VerifiedBuild` = 12340 WHERE `ID` = 2781;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This tablet... Quite unusual... Where did you find this, $N?', `VerifiedBuild` = 12340 WHERE `ID` = 2782;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!$B$BAnd now, please choose from what I am able to offer you for your service!', `VerifiedBuild` = 12340 WHERE `ID` = 2821;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, excellent! These hides, when given a special treatment, are as resilient as iron I tell you! It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.$b$bAs for you, $N... your assistance has proven invaluable to me. Please take your choice from these items I have crafted.', `VerifiedBuild` = 12340 WHERE `ID` = 2822;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, I am so glad you found me! I must admit, I am a bit lost... But isn\'t this a beautiful place?', `VerifiedBuild` = 12340 WHERE `ID` = 2844;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful!  You found it!  And what\'s just as important--Velratha no longer has it!  Thank you, $N.  I am forever in your debt!$B$BAnd if I sounded a little... mean before, pay it no mind.  You\'ll find me a much nicer person to those who haven\'t stolen from me.', `VerifiedBuild` = 12340 WHERE `ID` = 2846;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well $N, I\'m glad to have you on board. You\'ve made a smart decision as a leatherworker; those who wear leather armor will be clamoring to you once you learn how to make any of the Wild Leather armor pieces.$B$BLet\'s get to work - where do you want to start?', `VerifiedBuild` = 12340 WHERE `ID` = 2847;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These armor kits are of solid quality, $N. If there is one thing I demand in not only my work, but the work of those in my employ, it is quality.$B$BYou\'ve done well to earn this pattern; I hope it brings you the rewards it has brought me.', `VerifiedBuild` = 12340 WHERE `ID` = 2848;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These are some very nice pieces here, $N. The craftsmanship and care put in to making these alone would fetch several silver more than the average piece made.$B$BYou\'ve filled my order, and with that comes your reward. The knowledge of making Wild Leather vests is now yours!', `VerifiedBuild` = 12340 WHERE `ID` = 2849;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This Nightscape equipment you have supplied fills the order perfectly, $N. I expect no less from a leatherworker of your caliber.$B$BYou have definitely earned this pattern. I give it to you freely, and hope you will profit from it accordingly.', `VerifiedBuild` = 12340 WHERE `ID` = 2850;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Once again, you\'ve filled a complex order with the skill of a seasoned professional. You have earned this pattern, as well as my thanks.', `VerifiedBuild` = 12340 WHERE `ID` = 2851;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Again, you\'ve filled an order without flaw. Perhaps some day I will come to YOU seeking knowledge, eh $N?$B$BHere is the pattern for the leggings, along with my thanks. Commit this lore to your knowledge, and let your finished products tap into your impressive skills!', `VerifiedBuild` = 12340 WHERE `ID` = 2852;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah yes, Pratt sent you. Though he is a human, he reminds me of us night elves sometimes. His dedication and his talents with leather are impressive. For him to compliment you so in this letter, it is a sign of respect I acknowledge.$B$BI am aware that he has taught you the art of Wild Leather. Allow me to finish your training with this pattern. Make good use of it; few in the world know the secrets of Wild Leather cloaks.', `VerifiedBuild` = 12340 WHERE `ID` = 2853;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s right. I do have a bone to pick with a troll. A few bones. All her bones!$b$bWant to help me?', `VerifiedBuild` = 12340 WHERE `ID` = 2861;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is proof of a good start, $N. Your skills as a soldier are to be commended.$B$BYou are not the only one I ask that task of. Many before you have fought them, and in times past our efforts have kept them at bay. Recently though, their attempts to push northward into our area of influence have increased dramatically. Their attacks have also become more savage... almost as if they were desperate.$B$BI have a plan though, $N, that might settle things once and for all against them...', `VerifiedBuild` = 12340 WHERE `ID` = 2862;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done as I have asked, and for that I salute you. Take this small reward as compensation for your efforts, $N.$B$BWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp. This doesn\'t conclude the issue at hand, however...$B$BThere must be some reason why the gnolls have been whipped into such a frenzied state. Before they have a chance to regroup though, I want to find out what is causing it.', `VerifiedBuild` = 12340 WHERE `ID` = 2863;

UPDATE `quest_offer_reward` SET `Emote1` = 3, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hello!$B$BOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...$B$BScarab shells, you say?  Well... let me tell you a story...', `VerifiedBuild` = 12340 WHERE `ID` = 2864;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, great!  You got them!$B$BThanks, $N.  You\'re a real lifesaver!', `VerifiedBuild` = 12340 WHERE `ID` = 2865;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome back, $N.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.$B$BIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I\'d like to offer you the task, if you are so inclined.  There is much to do.', `VerifiedBuild` = 12340 WHERE `ID` = 2867;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 25, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.$B$BAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity.', `VerifiedBuild` = 12340 WHERE `ID` = 2869;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well played, $N! Lord Shalzaru\'s demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.$B$BHere is more bounty money from the stronghold treasury - you\'ve earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.$B$BOne more thing before you depart, $N... if you could...', `VerifiedBuild` = 12340 WHERE `ID` = 2870;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro\'s right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn\'t of naga design... not something as alien as this.$B$BIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.$B$BHere, take one of these extra items we have; I hope you\'ll find some use for it!', `VerifiedBuild` = 12340 WHERE `ID` = 2871;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so you\'ve been speaking with MacKinley, have you?$B$BIt\'s not what he thinks!  I\'m not afraid to give him some Steamwheedle Bilge Rum...$B$BI just don\'t have any rum to give him!', `VerifiedBuild` = 12340 WHERE `ID` = 2872;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager.', `VerifiedBuild` = 12340 WHERE `ID` = 2873;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hm, let\'s try this...$b$bI can\'t believe it! This stuff is... terrible! That\'s great!$b$bWell I guess Stoley can keep the money he owes me. He\'s true to his word about Steamwheedle bilge rum. That stuff is as thick as gravel and burns like lava!', `VerifiedBuild` = 12340 WHERE `ID` = 2874;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Andre\'s head.  So I guess he\'ll make his trial after all!$B$BMuch appreciated, $N.  Now if you\'ll just sign here, I can issue you payment for services rendered.$B$BDon\'t worry about the small print.  It\'s harmless, and... I don\'t think there\'s a magnifying glass small enough to read it anyway.', `VerifiedBuild` = 12340 WHERE `ID` = 2875;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!$B$BYou say you got this from a pirate?  Well that\'s disturbing news...$B$BThank you, $N.  I\'m glad you took it from him, and I\'m glad that pirate\'s eating dirt right now!', `VerifiedBuild` = 12340 WHERE `ID` = 2876;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, this is wonderful!  Thank you, $N!  I\'ll get to work immediately!!$B$BPoor, poor Techbot... Don\'t feel bad.  We\'ll get you fixed.$B$BNow, where did I put that plug for my hydro-jack swivel spanner...', `VerifiedBuild` = 12340 WHERE `ID` = 2922;

UPDATE `quest_offer_reward` SET `Emote1` = 18, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes it\'s true. Techbot has gone $C! Please, can you help me?', `VerifiedBuild` = 12340 WHERE `ID` = 2923;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got them!  Now I can begin my new experiments!$B$BI can\'t thank you enough, $N!  Your bravery has advanced gnomish research by a leap and a bound!', `VerifiedBuild` = 12340 WHERE `ID` = 2924;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I do!  I do need help with a mission into Gnomeregan.  And you\'re just the $C to do it!', `VerifiedBuild` = 12340 WHERE `ID` = 2925;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!', `VerifiedBuild` = 12340 WHERE `ID` = 2926;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I thought the loss of that outstanding head of hair would have been the end of him for sure, but he survived!$B$BI was standing right next to him when he was hit by the radiation bolt. Those delightful brown locks of hair hit the floor in clumps! Clusters! The horror of it all was only compounded when Gnoarn completely freaked out! Oh yes, freaked out I say! Gnoarn touched his bald head in disbelief, the look in his eyes screamed revenge, $N! Then he turned his anger towards the troggs!$B$B<Ozzie cringes.>', `VerifiedBuild` = 12340 WHERE `ID` = 2927;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This will do nicely, $N. One gyrodrillmatic excavationator fixed; 398 left to go.', `VerifiedBuild` = 12340 WHERE `ID` = 2928;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I like to think that the last thing that went through his head as he collapsed to the ground was your foot, $R. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality.', `VerifiedBuild` = 12340 WHERE `ID` = 2929;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!$B$BYour service to the gnomes will be long remembered, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2930;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I\'m organizing data extraction missions into Gnomeregan.  If you\'re here for that, then listen up!', `VerifiedBuild` = 12340 WHERE `ID` = 2931;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Word reached me of your deed. A grim deed, but one of honor. Let us hope the Witherbarks heed your message.', `VerifiedBuild` = 12340 WHERE `ID` = 2932;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, and what is this? It appears to be venom... from some arachnoid creature I deem. And where did you get it?', `VerifiedBuild` = 12340 WHERE `ID` = 2933;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, splendid! The venom is quite fresh and I\'m sure very deadly. Thank you!', `VerifiedBuild` = 12340 WHERE `ID` = 2934;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, so you want fresh venom from the spider of the witherbarks, yes? Well, sit down... you\'re not going to like what I have to tell you.', `VerifiedBuild` = 12340 WHERE `ID` = 2935;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Sweet, you got it!', `VerifiedBuild` = 12340 WHERE `ID` = 2937;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, very good. Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.$b$bWith luck, we will find many.$b$bThank you, $N. Your service to the Royal Apothecary Society is undeniable.', `VerifiedBuild` = 12340 WHERE `ID` = 2938;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, so Troyas Moonbreeze sent you?$b$b<mutters>...always bothering me with his wild notions that he found something important...$b$bLook, $N, I\'ll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.$b$bYou\'re welcome to take a look around, but I don\'t know if you\'ll find any books here that will help you.', `VerifiedBuild` = 12340 WHERE `ID` = 2939;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you\'d like to borrow Feralas: A History?$b$bLet me think...$b$bI will allow you to borrow this book, $N, but only if you do something for me first.', `VerifiedBuild` = 12340 WHERE `ID` = 2940;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Are you another one of Daryn\'s interns? She\'s quite a knowledgeable historian, $N. You should be grateful to be studying under her leadership.$b$bNow, let me get the Super Snapper FX. You\'re gonna love it!', `VerifiedBuild` = 12340 WHERE `ID` = 2941;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I have been reading since you left, $N. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.$B$BI will continue my studies, and I hope I will be able to count on you in the future, $N. Thank you for all your help.', `VerifiedBuild` = 12340 WHERE `ID` = 2942;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have brought a book along. Excellent!', `VerifiedBuild` = 12340 WHERE `ID` = 2943;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well! Curgle\'s invention lived up to its expectations.$B$BDon\'t get too excited, but do know that I am pleased with your work, $N.$B$BNow, where did I leave that book...', `VerifiedBuild` = 12340 WHERE `ID` = 2944;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Ozzie examines you.> Impressive, you still have all of your limbs. Now it\'s time to see what this stuff can do!', `VerifiedBuild` = 12340 WHERE `ID` = 2962;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am glad you\'re maintaining your interest in exploration, $N!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!$B$BThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum...', `VerifiedBuild` = 12340 WHERE `ID` = 2963;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We\'re all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You\'ve brought us this far $N, and I hope you will be the one to head back in to the field to unlock Uldum for us all!$B$BAllow me to give you this honorarium in the meantime; this should cover any expenses you\'ve encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!', `VerifiedBuild` = 12340 WHERE `ID` = 2964;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank Elune, $N! You are a great blessing to us and to the darters you saved. Jer\'kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem\'s affairs will be remembered.$B$BSpeak to Jer\'kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn\'t mean they will remain so. Jer\'kai and I will now go on the offensive.', `VerifiedBuild` = 12340 WHERE `ID` = 2969;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Kindal was right about you, $N--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.$B$BThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn\'t be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.$B$BBut that is a discussion for another day.', `VerifiedBuild` = 12340 WHERE `ID` = 2970;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s an amazing story, $N. It pleases us that you\'ve not only helped dragonkind, but also one of our own priestess. Jer\'kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.$B$BThank you again, and please, make yourself at home while you\'re here.', `VerifiedBuild` = 12340 WHERE `ID` = 2972;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful, $C! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.$b$bI hope the trip wasn\'t too dangerous? The area of Feralas is not known for being forgiving, but you\'ve obviously done well enough.$b$bThank you again, $C.', `VerifiedBuild` = 12340 WHERE `ID` = 2973;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent, $N. In time, the land will heal. We must not give up.', `VerifiedBuild` = 12340 WHERE `ID` = 2975;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?$b$bMy peers will want to hear your news, $C. Tell me more and I\'ll count out your coin while you do so.$b$bAnd before you go, know that I give you thanks for the information you\'ve passed on to me this day.', `VerifiedBuild` = 12340 WHERE `ID` = 2976;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.$B$BIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!$B$BNot that there\'s anything wrong with shovels... or digging...', `VerifiedBuild` = 12340 WHERE `ID` = 2977;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have proven yourself to be a trustworthy and dependable ally, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 2980;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, Belgrom sent you. You are just in time, $R.$B$BLet me explain the situation, and then you can decide if you are up to the challenge... But if Belgrom sent you, I am sure your courage is unquestionable.', `VerifiedBuild` = 12340 WHERE `ID` = 2981;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am very grateful you were able to do this for me.$B$BNow, please, don\'t mention a word to Troyas about this...', `VerifiedBuild` = 12340 WHERE `ID` = 2982;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Sharpbeak wasn\'t there?  That is bad news, but it is good news too...$B$BIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.$B$BI thank you for all of your aid, but I\'m afraid I have an even greater task ahead.', `VerifiedBuild` = 12340 WHERE `ID` = 2989;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.$B$BYou wish to find him?  Then listen close, brave $C...', `VerifiedBuild` = 12340 WHERE `ID` = 2990;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion\'s power while avoiding its... unpleasant side effects.$B$BYou have done me a service, $N.  I shall now uphold my end of our bargain.', `VerifiedBuild` = 12340 WHERE `ID` = 2991;

