UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N.$B$BThe Golden Flame will now be returned back to my homeland, where it may be protected, never again to be used for evil.$B$BSince you did so much for me, I\'d like you to have this. Without you, I\'d still have no idea who I am!', `VerifiedBuild` = 12340 WHERE `ID` = 3962;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We haven\'t got much time. Listen carefully, $R. What I have to tell you is classified and for your ears only.', `VerifiedBuild` = 12340 WHERE `ID` = 3981;

