UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Thrall is taken aback by the information you have presented to him.>$B$BA new threat now looms on the horizon. As Magni\'s years dwindle down, the way shall be opened for this unborn Dark Iron to become ruler of Ironforge.$B$BYou have accomplished what I asked of you and for that, you shall be rewarded.$B$BNow leave me, $N! I must confer with Sylvanas and Cairne.', `VerifiedBuild` = 12340 WHERE `ID` = 4004;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Blazerunner, you say...$b$bYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him.', `VerifiedBuild` = 12340 WHERE `ID` = 4005;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 66, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have done it! You have defeated the Kolkar!$B$BI will be sure Thrall receives word of your actions here, $N.$B$BStand tall. You do yourself, and the Horde, proud.', `VerifiedBuild` = 12340 WHERE `ID` = 4021;

