UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What is this?!? This head is not flesh. This is some sort of dark iron creation: A shadow of Argelmach - ANOTHER machine! I suspect that your destruction of Argelmach will be short lived as another shall rise to take \'its\' place soon.', `VerifiedBuild` = 12340 WHERE `ID` = 4063;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 25, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This first strike should put a crease in Angerforge\'s pants. Now, move along soldier. I have work to complete, battles to plan, enemies to crush!$B$BCheck the wanted signs for more work.', `VerifiedBuild` = 12340 WHERE `ID` = 4081;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Angerforge is undoubtedly... angry. Return to me when you receive a third tribute and we shall proceed with Operation: Death to Angerforge. I cannot go into any detail of what this entails, but rest assured, it involves somebody dying.', `VerifiedBuild` = 12340 WHERE `ID` = 4082;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well, $N. I can see you are serious about helping your friend.', `VerifiedBuild` = 12340 WHERE `ID` = 4084;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This blood amber will be used to find a means of defeating the corruption present in Felwood. You\'ve proven to me that you\'re willing to do whatever it takes for the Cenarion Circle. I trust you now, friend.$B$BIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take. You and I can now focus on the preservation of life through the salves I can make.$B$B$N, the time has come to cleanse Felwood.', `VerifiedBuild` = 12340 WHERE `ID` = 4101;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This blood amber will be used to find a means of defeating the corruption present in Felwood.  You\'ve proven to me that you\'re willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.$B$BIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.$B$B$N, the time has come to cleanse Felwood.', `VerifiedBuild` = 12340 WHERE `ID` = 4102;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.', `VerifiedBuild` = 12340 WHERE `ID` = 4103;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, $n! Wherever they are, use the salve I have given you to purify them.', `VerifiedBuild` = 12340 WHERE `ID` = 4108;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It sounds from your descriptions as if the creatures show a mindless ferocity...$b$bStay alert, $N. It would be in your best interest to learn more of the corruption. Always know your enemy.', `VerifiedBuild` = 12340 WHERE `ID` = 4120;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your heroics will not go unrecognized, $N. You have earned this tribute. The Warlord will speak with you now in regards to the final mission.', `VerifiedBuild` = 12340 WHERE `ID` = 4121;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Can you not see the power we gain by joining the legion of Blackrock? ', `VerifiedBuild` = 12340 WHERE `ID` = 4122;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Latro sent you to me, I presume.  While I think it is a lost cause at this point, I\'ll take whatever assistance you can offer.  I must admit... I\'ll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment.', `VerifiedBuild` = 12340 WHERE `ID` = 4124;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You found it! Well done! And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!$b$bThe Thunderbrews are at your service, $N. You are a hero of heroes!', `VerifiedBuild` = 12340 WHERE `ID` = 4126;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Interesting... I believe that this is Raschal\'s knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife\'s discovery might not be enough to connect this to Raschal\'s disappearance; we do, however, have an unconventional option available to us to try and learn more.$B$BHave you ever heard of psychometry?', `VerifiedBuild` = 12340 WHERE `ID` = 4127;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re right I\'m mad!  I\'ve been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn\'t have enough cause to hate the Dark Iron dwarves!  Now, oh... now they\'re in for it!', `VerifiedBuild` = 12340 WHERE `ID` = 4128;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N.$B$BWhile psychometry isn\'t an exact art by any stretch of the imagination, I\'ve used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you\'ve uncovered will give us a glimpse into what happened to Raschal.$B$BIt will only take a moment to do, but it isn\'t what I\'d call a caster-friendly task.  Bear with me on this.', `VerifiedBuild` = 12340 WHERE `ID` = 4129;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks for passing along Quint\'s visions to me, $N.  I\'ll try to remember to be a little easier on him the next time we play cards.$B$BRaschal can hold his own in a fight, and gnolls aren\'t anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need.', `VerifiedBuild` = 12340 WHERE `ID` = 4130;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for coming, $N. This place is not without a stark charm, but is lacks the amenities of the Apothecarium.$b$bEnough with the pleasantries. To business, yes?', `VerifiedBuild` = 12340 WHERE `ID` = 4133;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good. I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets. One day, the dwarves of the Alliance may find the virtues of this drink used against them!$b$bI find that terribly amusing. Perhaps death has an affect on one\'s sense of humor... do you think?', `VerifiedBuild` = 12340 WHERE `ID` = 4134;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I\'ll tell you whether or not I can help you.', `VerifiedBuild` = 12340 WHERE `ID` = 4142;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Marvon\'s been gone quite a long time now, $N. He went off to Tanaris to study some of the ancient troll ruins.$b$bNow, what was it that you said you needed?', `VerifiedBuild` = 12340 WHERE `ID` = 4147;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well $N, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.$B$BKeep your ears perked $N, and you might learn something.', `VerifiedBuild` = 12340 WHERE `ID` = 4181;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, you\'ve done it! Wonderful! Thank you, $N.$b$bOh, my poor, A-Me. Look at all those dents. We\'ll get her up and running perfectly with just a little work.$b$bThank you again, $N. I really appreciate it.', `VerifiedBuild` = 12340 WHERE `ID` = 4245;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, $N. Felwood has been through much hardship. Thank you for what you have done.$B$BOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps.', `VerifiedBuild` = 12340 WHERE `ID` = 4261;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Incendius? Oh dear...', `VerifiedBuild` = 12340 WHERE `ID` = 4262;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh dear! Are you sure Incendius said \'Ragnaros?\'$b$b<Jalinda hands you something and pats you on the wrist as she fades deep into thought.>', `VerifiedBuild` = 12340 WHERE `ID` = 4263;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome home, $N.  Raschal checked in just a little while ago and told me what happened.$B$BI... no, the entire Stronghold can\'t even begin to thank you for your great deed; Raschal would have been dead without your timely aid, and your assistance came to us without even so much as the whisper of a mercenary\'s fee.  You bear the mark of a true hero.  Know that you will always have a friend in Ginro Hearthkindle.', `VerifiedBuild` = 12340 WHERE `ID` = 4265;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '$N, I give you my warmest thanks for the aid you\'ve given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.$B$BNow, if I may... I\'d like to ask for your aid one more time.  In light of the discovery of the Zukk\'ash hive here in Feralas, I think you\'re the best choice for this mission.', `VerifiedBuild` = 12340 WHERE `ID` = 4266;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.$B$BThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.$B$BI pray we will have the resolve to defeat them before they destroy us.', `VerifiedBuild` = 12340 WHERE `ID` = 4267;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 2, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!$b$bYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier. I hope that everything works out. I know that recently, the Woodpaw have become highly agitated from some source to their south. Maybe he fell to the wilds there; I would be careful, friend.$b$bRegardless, thank you again. Here is payment for this parcel\'s delivery.', `VerifiedBuild` = 12340 WHERE `ID` = 4281;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!', `VerifiedBuild` = 12340 WHERE `ID` = 4283;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 5, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Oralius starts rummaging through the mountainous pile of fanny packs.>$B$BOH WONDERFUL!$B$B<Oralius sticks his large nose into the pile and takes a whiff.>$B$BDELICIOUS! Look at all these goodies!$B$BTake one for yourself, $N. There\'s plenty to go around.', `VerifiedBuild` = 12340 WHERE `ID` = 4286;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 4, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What\'s this?  Ah!  It smells like Dark Iron Ale!  Drink has blurred my sight, but I can tell that you, $gsir:my lady;, are a real friend!', `VerifiedBuild` = 12340 WHERE `ID` = 4295;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, you found the tablet!  And your transcription is superb!  Are you sure you\'re a $c and not a scribe?$B$BHere you are, $N.  Here is the payment I promised.', `VerifiedBuild` = 12340 WHERE `ID` = 4296;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 6, `Emote3` = 11, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These\'ll do nicely, and if I\'m not mistaken, your little egg\'s just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn\'t think ya\'d have to deal with such responsibility, now did ya?', `VerifiedBuild` = 12340 WHERE `ID` = 4297;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.$B$BCongrats, $N. You\'re a parent... kinda.', `VerifiedBuild` = 12340 WHERE `ID` = 4298;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I\'m looking for my brother.  We must find him and retrieve him, bless his heart.$B$BBut if we can\'t bring all of him... then his head will suffice.', `VerifiedBuild` = 12340 WHERE `ID` = 4324;

