UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. Now, we must pray that we can undo the damage that has been done...', `VerifiedBuild` = 12340 WHERE `ID` = 4441;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'With the blessed water, I was able to break the link between the flute and the ancient spirit. I do believe though, that if you were to use this flute in a sacred spot, you may be able to summon the ancient spirits.$B$BPerhaps you might try the ruins in the southern part of Irontree Woods. Many corrupted treants inhabited this area at one time, and it is possible that they may still reside there, even in spirit form.', `VerifiedBuild` = 12340 WHERE `ID` = 4442;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, you\'ve seen fit to do some of the work I requested. Excellent. And here I thought you were going to ask me to craft you something.$B$BThese are all perfect... and everything\'s here. Thank you, $C.$B$BMaybe it wouldn\'t hurt to reward you some... hmm, what would you find useful.', `VerifiedBuild` = 12340 WHERE `ID` = 4450;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Take your trinket, fool. Leave me to my studies!', `VerifiedBuild` = 12340 WHERE `ID` = 4463;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is disgrace to his memory... a mortal, such as yourself, finishing his life\'s work.$B$BTake your amalgamation and be gone!', `VerifiedBuild` = 12340 WHERE `ID` = 4481;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 25, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It took Kariel what would amount to several of your lifetimes to complete the libram that you now hold, $R. All for what? So that his disciple could stand in the Burning Steppes and bastardize his research in order to satiate a never ending arcane craving... Curse this foul addiction.$B$BI am disgusted with your lack of compassion and insatiable greed. Be gone!', `VerifiedBuild` = 12340 WHERE `ID` = 4482;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Other librams are lost in this world. Lost in places you would not dare enter. Places you would pray did not exist.$B$BI will drink in the energies of these components. You shall be given the residual waste...', `VerifiedBuild` = 12340 WHERE `ID` = 4483;

UPDATE `quest_offer_reward` SET `Emote1` = 33, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'My head throbs... The energies of the vast expanses that makes up our universe... ARGGH!$B$BTake what you desire and leave!', `VerifiedBuild` = 12340 WHERE `ID` = 4484;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ringo\'s not in the best shape, $N, but I am glad to have him back in one piece!$b$bThank you for finding him.', `VerifiedBuild` = 12340 WHERE `ID` = 4491;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I gathered that Gracina sent you to me. Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before. As for Gracina\'s idea that Un\'Goro Crater is their heart... perhaps it is. Un\'Goro is a mysterious and dangerous jungle to the west of here. Perhaps it is also one step closer to figuring out what the silithid are all about.', `VerifiedBuild` = 12340 WHERE `ID` = 4493;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, I gathered that Zilzibin sent you to me. Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before. As for Zil\'s idea that Un\'Goro Crater is their heart... perhaps it is. Un\'Goro is a mysterious and dangerous jungle to the west of here. Perhaps it is also one step closer to figuring out what the silithid are all about.', `VerifiedBuild` = 12340 WHERE `ID` = 4494;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The scent gland, ah yes. The membrane appears intact - excellent. The soil, yes, this should work out perfectly. With my special additions, I should be able to grind all this up into the perfect lure.$b$bGive me a moment to make the lure, $N. Once it\'s ready, we\'ll be able to enact the next step that may hopefully stop the silithid before they overrun Gadgetzan... and the rest of Kalimdor.', `VerifiedBuild` = 12340 WHERE `ID` = 4496;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 4, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am absolutely terrified of the pterrordax here! Thank you for decreasing their numbers, $N. Now I might feel safe enough to venture out of Marshal\'s Refuge.', `VerifiedBuild` = 12340 WHERE `ID` = 4501;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These samples will be perfect for my studies! Thank you, $N! I promise, you\'ll be the first one I will tell about my findings.', `VerifiedBuild` = 12340 WHERE `ID` = 4502;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!$B$BThanks!', `VerifiedBuild` = 12340 WHERE `ID` = 4503;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very well. We must find a way to use this corruption against our enemies...', `VerifiedBuild` = 12340 WHERE `ID` = 4505;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 11, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent!$b$bThe forsaken will resort to any means necessary to crush the alliance! The use of the corrupted water will surely prove useful in our future efforts...', `VerifiedBuild` = 12340 WHERE `ID` = 4506;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Fantastic, $N!  We\'ve won quite the victory here today.  It will take some time for us to fully understand what we have here; we\'ll put it to good use though, don\'t you worry about that.$B$BAs for the silithid, I genuinely doubt that this was the full extent of their presence.  This is much too clean of a resolution, I\'m sorry to say.', `VerifiedBuild` = 12340 WHERE `ID` = 4507;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'While I genuinely appreciate this, I am not sure what good it will do us.  The Alliance ignores threats from any source other than the Horde, and even our own leaders here in Darnassus cannot agree on what exactly this threat is.  Fools like Fandral Staghelm theorize that the silithid are nothing like the threat from the ancient past I claim them to be.  His ignorance is only surpassed by his arrogance.$B$BYou have seen the threat yourself, $N.  We must remain committed to defeating the silithid!', `VerifiedBuild` = 12340 WHERE `ID` = 4508;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'While I genuinely appreciate this, I am not sure what good it will do us.  The Horde ignores threats from any source other than the Alliance.  While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice.  These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!$B$BYou have seen the threat yourself, $N.  We must remain committed to defeating the silithid!', `VerifiedBuild` = 12340 WHERE `ID` = 4509;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This bank voucher authorizes me to withdraw an item from Gracina Spiritmight\'s account with us and present it to you.  Congratulations would seem to be in order!', `VerifiedBuild` = 12340 WHERE `ID` = 4510;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This bank voucher authorizes me to withdraw an item from Zilzibin Drumlore\'s account with us and present it to you.  Congratulations would seem to be in order!', `VerifiedBuild` = 12340 WHERE `ID` = 4511;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Amazing results, $N! You got close enough to take a sample of the corrupted things, and managed to look no worse for wear! Thank you. Oh, these samples will be perfect. I can\'t wait to start testing on them.$B$BIf I\'m right, I could be one of the Explorers\' Leagues greatest scientists!$B$BThat\'ll prove to all the dwarves that it wasn\'t a mistake to allow us gnomes into Ironforge  after the Gnomeregan incident.', `VerifiedBuild` = 12340 WHERE `ID` = 4512;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 4, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve found it? $N, you are a treasure unto yourself. Your dedication and aid has been magnificent and I could not possibly thank you enough.$B$BPlease, take this for your troubles. I have some work to do, but I\'m sure, if you come back at a later time, I\'ll have need of your services again.$B$BThank you. Thank you so much.', `VerifiedBuild` = 12340 WHERE `ID` = 4513;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Shindrell\'s report!  Many thanks, $N.  Shindrell is a fine sentinel, brave and keen.  I must read this for clues of a wickedness I fear is moving through Ashenvale.', `VerifiedBuild` = 12340 WHERE `ID` = 4581;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 4, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Another one of Kaltunk\'s recruits, hm?$B$BA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you\'re ready to leave the Valley, you\'ll be a proud $C of the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 4641;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve been a tremendous help here today; we now have a solid chance at unlocking the mystery of why these creatures choose to beach themselves on the cost of Darkshore. The idea that they might be fleeing the area around Teldrassil is disturbing. Should you come across others in your travels, please let me know. Our research here is but in its infancy.$B$BOn behalf of the Temple of the Moon, please accept this as thanks for the effort you have given. Thank you, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 4681;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Do not dwell upon her suffering, $N. The beast was corrupt - a product of dark magic. You have done the Alliance a great service and you shall be rewarded.', `VerifiedBuild` = 12340 WHERE `ID` = 4701;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Another discovery for us to research - well done $N!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study.', `VerifiedBuild` = 12340 WHERE `ID` = 4722;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 21, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Rabid pups? Gizrul the Slavener? And you live to tell the tale?! Incredible! A tribute well earned!', `VerifiedBuild` = 12340 WHERE `ID` = 4724;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It worked!  You got the essence!  Well done, $N!  Well done!$B$BThis essence will be invaluable in my research.  I hope to one day learn how to capture living dragon whelps, or perhaps capture their eggs.  If I could find a way to do that, then I would be the envy of dragon scholars around the world!$B$BMy employer would also be happy, and as I said before, he\'s someone you want to keep happy...', `VerifiedBuild` = 12340 WHERE `ID` = 4726;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You got \'em at the perfect time, $N. Any later and they\'d be untrainable! Gimmie a minute and I\'ll have the little fella ready for you to take home.', `VerifiedBuild` = 12340 WHERE `ID` = 4729;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It worked? Splendid! I knew it would!$b$bWhile you were gone I was working on a new version of the eggscilloscope. This one has a much longer range.$b$bHere, you can have one in case you go back to Blackrock Spire.', `VerifiedBuild` = 12340 WHERE `ID` = 4734;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wow, you got them! The collectronic module worked! I\'m a genius!$B$BThank you, $N. My patron will be very pleased to get these eggs...', `VerifiedBuild` = 12340 WHERE `ID` = 4735;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Briarthorn sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you\'ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.', `VerifiedBuild` = 12340 WHERE `ID` = 4736;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, Zevrost sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you\'ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.', `VerifiedBuild` = 12340 WHERE `ID` = 4737;

