UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N!  It\'ll be a long time before they can grow another clutch of dragons.$B$B...At least, I hope it will!', `VerifiedBuild` = 12340 WHERE `ID` = 5529;

