UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I was Tirion\'s most trusted advisor when he held rank as Lord of Mardenholde. I openly dissented the verdict passed by the Order of the Silver Hand and was banished for my insolence.$b$bHe has been through much heart ache and disappointment in his life, $R. Are you prepared to right the wrongs set upon the Fordrings?', `VerifiedBuild` = 12340 WHERE `ID` = 5861;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 16, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 1000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What is this, soldier?$b$b<Taelan opens the box and begins to examine its contents.>$b$bThis... this cannot be true. But all that you have shown me...$b$b<Taelan falls to one knee, his heartbeat quickens. The fury of ages is about to be loosed upon this town.>', `VerifiedBuild` = 12340 WHERE `ID` = 5862;

