UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 1, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The death of my son at the hands of these monsters will not pass without incident. Take solace in knowing that the Order is reborn.$b$bI now take my place as Highlord of the new Order of the Silver Hand.$b$bThese possessions of my past - they are all that I have to offer for all that you have done. Please, take these as a symbol of my gratitude; all have served me well over the years.$b$bMay we meet again, in better times, and reminisce of days long past... battles hard fought... dreams redeemed.', `VerifiedBuild` = 12340 WHERE `ID` = 5944;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption.', `VerifiedBuild` = 12340 WHERE `ID` = 5961;

