UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The fools! My deception went unnoticed! Prepare yourself, $C. We must strike with cold cunning!', `VerifiedBuild` = 12340 WHERE `ID` = 6147;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'They will be reeling from this blow for years! Well done, $N! You have earned not only my respect but also this reward.', `VerifiedBuild` = 12340 WHERE `ID` = 6148;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.$b$bThank you again, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 6162;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 66, `EmoteDelay1` = 0, `EmoteDelay2` = 1000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I wonder... did it beg for mercy? Could it know what mercy is?$B$B<Nathanos spits.>$B$BI will hang this beast\'s head upon my wall.$B$BYou have earned a spot amongst one of my champions, $N.$B$B<Nathanos salutes.>', `VerifiedBuild` = 12340 WHERE `ID` = 6163;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have to get this note to Stormwind? That\'s not a problem, you can take one of my gryphons!', `VerifiedBuild` = 12340 WHERE `ID` = 6181;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 35, `Emote3` = 6, `Emote4` = 274, `EmoteDelay1` = 1000, `EmoteDelay2` = 1000, `EmoteDelay3` = 2000, `EmoteDelay4` = 1000, `RewardText` = 'No. It... NO! How? An agent of the Forsaken? The CHAMPION of the Banshee Queen???$B$B<King Varian Wrynn slumps in defeat.>', `VerifiedBuild` = 12340 WHERE `ID` = 6186;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A crate for Westfall, eh? Have you been to Westall before? If so, then it\'s no problem, my friend. I have plenty of gryphons trained to fly that route!', `VerifiedBuild` = 12340 WHERE `ID` = 6261;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, a note from Quartermaster Lewis? I\'m not surprised he needs more gear. Sentinel Hill is far away, in a land Stormwind has all but forgotten.$B$BWell thank you, $N. Here\'s some money to cover your travel costs.', `VerifiedBuild` = 12340 WHERE `ID` = 6281;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!', `VerifiedBuild` = 12340 WHERE `ID` = 6282;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all Tauren should.$b$bPlease accept this as a reward for your troubles.', `VerifiedBuild` = 12340 WHERE `ID` = 6283;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good hunting, $N! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.$b$b<Maggran rubs the wound caused by Besseleth.>$b$bPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark.', `VerifiedBuild` = 12340 WHERE `ID` = 6284;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you brought the armor! We\'ll get this divvied to those who need it immediately.$B$BThank you, $N. Your efforts have been a great help to us. And now that you\'re no stranger to gryphons, I hope you\'ll come and lend your aid to Sentinel Hill often!', `VerifiedBuild` = 12340 WHERE `ID` = 6285;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked.', `VerifiedBuild` = 12340 WHERE `ID` = 6321;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This crate must reach the Sepulcher in Silverpine? That is easily done; our bats fly there daily.', `VerifiedBuild` = 12340 WHERE `ID` = 6322;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'An order from the Sepulcher? Very well. It is an honor to serve those who serve our Dark Lady.', `VerifiedBuild` = 12340 WHERE `ID` = 6323;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good work, $N. These weapons will ensure our Deathguards don\'t get caught unprepared.$B$BYou have done a valuable service for our Dark Lady.', `VerifiedBuild` = 12340 WHERE `ID` = 6324;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, a new bundle of hides. I will get to work on these immediately!$B$BThank you, $Gbrother:sister;. You have done me a great service. Here are some coins to pay for your time and travel costs.', `VerifiedBuild` = 12340 WHERE `ID` = 6362;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have to get this meat to Orgrimmar? That is no problem. For a small fee, my wind rider can take you there.', `VerifiedBuild` = 12340 WHERE `ID` = 6365;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome to the new frontier, $N.  Ashenvale is a land of opportunity, one where a young $C like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.$B$BYour presence here tells me that you\'ve come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.', `VerifiedBuild` = 12340 WHERE `ID` = 6382;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'There are three legendary creatures that make up the Ashenvale Hunt; you may seek them and test yourself against their cunning and might.  In the process, you will hopefully learn something about yourself.  The creatures are: the bear Ursangous, the nightsaber cat Shadumbra, and the hippogryph Sharptalon.$B$BThe creatures of the Ashenvale Hunt are powerful, and you may find that you\'ll need aid in bringing them down.  If you should best them, bring me proof of your deed.', `VerifiedBuild` = 12340 WHERE `ID` = 6383;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, wonderful! Those are fine cuts! These are from Zargh, are they? That orc sure knows his way into a lady\'s heart...$B$BOh, I can\'t wait to cook it. But not too much! Meat is best served rare, don\'t you think?', `VerifiedBuild` = 12340 WHERE `ID` = 6384;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have to get this to the Crossroads in the Barrens? Yes, I can get you there...', `VerifiedBuild` = 12340 WHERE `ID` = 6385;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hah! I guess she liked it! Nothing brings red to a lady\'s cheeks like a big, juicy steak!$B$BThank you, $N. You\'ve done me a great service. Here is some money for your trouble, and don\'t be surprised if I invite you to my wedding!', `VerifiedBuild` = 12340 WHERE `ID` = 6386;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have to get this to Ironforge, eh? For a small fee I can put you on the back of one of my gryphons, and it\'ll take you there. How does that sound?', `VerifiedBuild` = 12340 WHERE `ID` = 6387;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have to get these to Thelsamar, eh? That won\'t be a problem. As long as you\'ve already been to Thelsamar and spoken to Thorgrum Borrelson, then you can take one of my gryphons back to him.', `VerifiedBuild` = 12340 WHERE `ID` = 6388;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. Here, take this coin. I\'m sorry it\'s not more, but try to take some joy in helping destroy the Scarlet Crusade\'s efforts!', `VerifiedBuild` = 12340 WHERE `ID` = 6390;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, the lastest list of Brock\'s best pupils. I have a batch of honorary picks ready to go. I just need to chisel in the names of the students...', `VerifiedBuild` = 12340 WHERE `ID` = 6391;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You brought the picks. Great! I\'ll get these to my mining students. I\'m sure they\'re eager to use them on the ore deposits of Loch Modan.$b$bThank you for your help, $N. I am in your debt, but I hope this money will at least cover your travel costs.', `VerifiedBuild` = 12340 WHERE `ID` = 6392;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, you got it! Thanks a lot, $N. This is my favorite pick! Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!', `VerifiedBuild` = 12340 WHERE `ID` = 6394;

