UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah... Yes! That\'s it; the Resonite crystals have a trace of Earthen magic. The Kobolds must have dug deep uncovering an Earthen.$b$bLegend states that the Earthen are creatures created by the Titans. They were used to create the land our feet walk on. This most definitely is a threat that cannot be ignored.$b$b<Mor\'rogal shakes his head.>$b$bPerhaps I can enchant these ore samples to use against this Kobold plot.', `VerifiedBuild` = 12340 WHERE `ID` = 6421;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We could use more of your kind around here, $N. Thank you for your help.', `VerifiedBuild` = 12340 WHERE `ID` = 6442;

