UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I had doubted your dedication, whelp. You persisted, dominating our enemies, bringing honor to our flight.$B$BI must now prepare the skulls for your ascension.', `VerifiedBuild` = 12340 WHERE `ID` = 6585;

