UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 2, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These are perfect, $N. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study.', `VerifiedBuild` = 12340 WHERE `ID` = 7070;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done! Graveyards are vital to our control of Alterac Valley. When you capture one, you help ensure the Alliance\'s sovereignty here.$B$BGo now, $N. Reenter the battle, and if you see a graveyard under the Horde\'s control... you know what to do!', `VerifiedBuild` = 12340 WHERE `ID` = 7081;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I received a field report stating you helped secure an enemy banner. Well done, $N! With their ranged troops out of position we can move the line of battle forward!', `VerifiedBuild` = 12340 WHERE `ID` = 7102;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You did it! Well done, $N!$B$BWhen we control a mine and have troops stationed there, it\'s much easier to gather minerals and supplies from it.', `VerifiedBuild` = 12340 WHERE `ID` = 7122;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Take and wear this insignia with pride, $N. As your rank among the Stormpike grows, so too will the insignia. Return to me as you gain honor with Stormpike, and I shall replace your insignia with other, more powerful insignias.$B$BPerhaps someday you will grow to be a legend on this field of battle. Should that day ever come, you will be granted the Eye of Command.', `VerifiedBuild` = 12340 WHERE `ID` = 7162;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!', `VerifiedBuild` = 12340 WHERE `ID` = 7168;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The king has been made aware of your battlefront heroics, $C. Continue in your stalwart defense of the Stormpike Guard!', `VerifiedBuild` = 12340 WHERE `ID` = 7169;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'When we first met, I would have never guessed that a hero was in the making. Carry on, soldier!', `VerifiedBuild` = 12340 WHERE `ID` = 7170;

UPDATE `quest_offer_reward` SET `Emote1` = 25, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Soon, all on the field of battle will be under your watchful eye. Command of the Valley and its troops will be yours!', `VerifiedBuild` = 12340 WHERE `ID` = 7171;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is you who must lead our troops to victory, Commander! The soldiers are under your command. They will follow your direct orders. Lead them... Crush the Frostwolf.', `VerifiedBuild` = 12340 WHERE `ID` = 7172;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful! I will have these sent by courier to the Undercity at once!$B$BAs for you - here is payment, as promised. Keep the change, you filthy beast!', `VerifiedBuild` = 12340 WHERE `ID` = 7201;

