UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Are you headed back into the Scholomance, $n? You\'ve already paid such a great price for the use of the Divination Scryer - perhaps you\'d like to take another one with you. With it, you\'d be able to face the perils of the Great Ossuary once more.$b$bBy all means, have it. You\'ve certainly earned it.', `VerifiedBuild` = 12340 WHERE `ID` = 7666;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 25, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I am glad to see you $N.  I know that you have awaited word as to how to acquire your charger, and now that time has come.$B$BYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you.  These are not done as a learning exercise - your stature is beyond simple educational tests.  You must save your future companion from the clutches of the evil you have spent your life fighting.$B$BTake heed, your time has come!', `VerifiedBuild` = 12340 WHERE `ID` = 7670;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I never thunk I\'d be lookin\' at thish ugly mug again!$B$BHe acshually looksh better without the resht o\' him attached.$B$BHere\'s yer reward *hic*, $r.', `VerifiedBuild` = 12340 WHERE `ID` = 7701;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful! Those sleepy Dark Irons will head back to their homes in the Depths to get some rest, greatly slowing down the productivity of the Slag Pit.', `VerifiedBuild` = 12340 WHERE `ID` = 7702;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I hope you kicked his teeth in too, $N. Ragnaros knows, he deserved it.$B$BNow we can get down to business.', `VerifiedBuild` = 12340 WHERE `ID` = 7722;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 21, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ye\'re a good $g lad:lass;, ye are. I got ye a lil\' present fer yer troubles.', `VerifiedBuild` = 12340 WHERE `ID` = 7723;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Hansel sneezes.>$B$BI think I\'m gettin\' a cold. Damn this frigid climate!', `VerifiedBuild` = 12340 WHERE `ID` = 7724;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Inconceivably fantastical, $N!  You\'ve come through for me again, and for that I thank you.$B$BThank you!$B$BWhile you may find this coin to be a little less than you\'re accustomed to, rest assured your great deeds on the field of goblindom are echoing through the halls of power in the Steamwheedle Cartel.  Should you need something else to do, then by all means talk to me!', `VerifiedBuild` = 12340 WHERE `ID` = 7725;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh me achin\' feets.$B$BI figured since ye didn\'t have a luffa...', `VerifiedBuild` = 12340 WHERE `ID` = 7727;

