UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A Defiler scout came to me with a report of your success, $n.  Well done.$b$bAs you will learn, to win the battle for Arathi Basin, we must be ever vigilant and crush any attempts at Alliance expansion.  Do this, and our victory here is ensured.', `VerifiedBuild` = 12340 WHERE `ID` = 8171;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 5, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So, you have been speaking with that old dwarf Ironboot and uncovered the lost Mosh\'aru Tablets, have you?  That meddling prospector...$B$BNo matter.  It is too late to save this world.  Hakkar has been reborn, and even now grows in power... deep in the ancient troll kingdom of Zul\'Gurub!  He has come!  And he will rule in blood and terror!$B$BThank you, $N.  Your help has sped the return of the Soulflayer!', `VerifiedBuild` = 12340 WHERE `ID` = 8181;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You were sent by the prospector, Ironboot?  His kind are wise, and wiser still to bring you to me, for I and the Zandalarian trolls may know a way to defeat the Soulflayer.$B$BSpeak with the trolls of this isle, heed their words, and prepare yourself, $N, for the task before you is soaked in blood.', `VerifiedBuild` = 12340 WHERE `ID` = 8182;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome, welcome, welcome!  Please, $N, have a seat and discuss a simple matter with me.$B$BYou see, $N, I\'ve recently lost something dear to me, and to put it bluntly, I want it back at all costs.  There\'s something in it for you, don\'t worry about that!  Oh yes, something very nice.$B$BNow, what say you $N... are you up for some adventure?', `VerifiedBuild` = 12340 WHERE `ID` = 8233;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I see you have Lord Ravenholdt\'s bag. Why didn\'t you say so, boy?', `VerifiedBuild` = 12340 WHERE `ID` = 8234;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It looks like you picked up some of the better fragments. Perhaps you aren\'t worthless after all.', `VerifiedBuild` = 12340 WHERE `ID` = 8235;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The key! I thought it lost forever. Please, take an enchanted garment from my stores -- they are reserved for rogues of exceptional skill and loyalty. It should be known that $N is not to be trifled with!$B$B<Jorach opens the bag and is bathed by a golden glow from within. His eyes widen and he stares...>', `VerifiedBuild` = 12340 WHERE `ID` = 8236;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is good the divine path has led you to us, $N. Your beliefs do not interfere with the tasks involved in creating this salve.$B$BYou see, the courser is sacred to the Cenarion Circle, and killing them for any reason, no matter how necessary, weakens their spirit.', `VerifiedBuild` = 12340 WHERE `ID` = 8255;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I cannot say I\'m pleased to receive such a wretched substance, but it is a necessary evil. Thank you, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 8256;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have slain Morphaz and carried his blood to us... I can hardly believe this good news!$B$BWe will combine the ingredients at once and begin healing the trees and creatures of Felwood. It will take a lifetime to undo what has happened here, but you have given us the means to do it.', `VerifiedBuild` = 12340 WHERE `ID` = 8257;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve certainly begun to prove yourself to us, $n.  As a reward, please take this care package!  Inside it you\'ll find rations and bandages that are usable only inside Arathi Basin.$b$bAs you continue to prove yourself inside the Basin, you\'ll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.', `VerifiedBuild` = 12340 WHERE `ID` = 8260;

