UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Now that\'s one face I was not expecting to see so soon.$B$BThis is quite the good news. $N, in more ways than you can imagine.', `VerifiedBuild` = 12340 WHERE `ID` = 9238;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Here is your order, $N. Delivered as promised!', `VerifiedBuild` = 12340 WHERE `ID` = 9239;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you, $N. You\'re on a quick path to redeeming yourself with our fair town.', `VerifiedBuild` = 12340 WHERE `ID` = 9266;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see. the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth.', `VerifiedBuild` = 12340 WHERE `ID` = 9407;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Greetings, $C.  I trust that you\'re journey here was uneventful?$B$BThese poor souls are beset upon all sides by the creatures of the night.  It is our wish that you lend them what aid you can in pushing back the darkness.$B$BTravel about the town and get to know its inhabitants.  Please, $N, help them in any way that you can.', `VerifiedBuild` = 12340 WHERE `ID` = 9429;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What? She didn\'t mention the moonwell? That\'s what she had in mind all along. I admit the whole thing\'s a bit wacky, but who am I to turn away a client, especially when she\'s the only one I\'ve got?$B$BMaybe trying to sneak into a night elf settlement and steal water from their moonwell isn\'t the most prudent thing I\'ve ever helped a customer do, but her money is as gold as anyone else\'s!', `VerifiedBuild` = 12340 WHERE `ID` = 9431;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent, it appears everything is here. Now, all I have to do is mix everything together and give it a try. If this tonic does what my research indicates it should do, I may have discovered a way to lessen the effects of my people\'s magic addiction.$B$BYou\'re about to witness history in the making, $N. Just think, without your help, this wouldn\'t have been possible.', `VerifiedBuild` = 12340 WHERE `ID` = 9434;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank the Light! From the tone of the foreman\'s letter, it sounded as if that box of crystals contained the only known samples from the mine. If we had lost them, $N, we may never have seen another like them.$B$BI can\'t thank you enough for your help.', `VerifiedBuild` = 12340 WHERE `ID` = 9435;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re a miracle worker, $N! I tell you, I\'ve never been so eager for a change of clothes in my life.$B$BAnd my rapier! I felt positively naked without my blade.$B$BYou are to be commended and rewarded for your efforts. Never let it be said that Sarophas failed to acknowledge the little people who\'ve helped him along the way!', `VerifiedBuild` = 12340 WHERE `ID` = 9439;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, excellent! I can\'t wait to measure the effects from this latest batch!$B$BWell, you did an admirable job, sweetie.  Wish I could give you more than this for the entertainment you\'ve provided, but you know how it is.  There\'s not much money to be made out here in the swamp.$B$BI\'m sure it was worth it just for the fun!', `VerifiedBuild` = 12340 WHERE `ID` = 9440;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 15, `Emote3` = 5, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Forgives me?  He FORGIVES ME?!!!$B$BI don\'t care what that old ghost had to say - it was his fault!  Everything that\'s happened to Quel\'Thalas was a result of his incompetence!$B$BIt is clear that the defiling did not work.  Go, be gone from my sight!  I must think this through.', `VerifiedBuild` = 12340 WHERE `ID` = 9444;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is done then. I thank you for showing your compassion. Once corrupted by whatever Cersei was feeding them, there is nothing else that could be done.$B$BThey are now at peace and hopefully my studies of the others will bear fruit so that they can be rehabilitated.', `VerifiedBuild` = 12340 WHERE `ID` = 9448;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is the ring, is it? Not much to look at, but you know what they say about one elves\' trash...$B$BAnd let\'s not forget your payment. Don\'t feel shy about spending it right here sweetie!', `VerifiedBuild` = 12340 WHERE `ID` = 9491;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'With Warlord Sriss\'tiz dead, the possibility of a naga invasion is now only a distant memory. We are safe, for the time being...$B$BI must admit, I was wrong to think badly of you, $N. You have shown that you are nothing like the filth that was Archimonde. Accept this as a gift from the night elves.', `VerifiedBuild` = 12340 WHERE `ID` = 9515;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have my respect and thanks, $C. Perhaps we\'ll be able to create a new home here without having to worry about the Burning Legion yet again.', `VerifiedBuild` = 12340 WHERE `ID` = 9516;

UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 5, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'At last we have sent a message that the orcs won\'t dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!$B$BWe must press our advantage, $N, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.', `VerifiedBuild` = 12340 WHERE `ID` = 9518;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent work, $N. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim. Do you see how it still shines, after all these years?', `VerifiedBuild` = 12340 WHERE `ID` = 9519;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 274, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'By the Seven Crystals of Ata\'mal, this cannot be!  They plan to attack us here at Forest Song?!$B$BNot on my watch!$B$B<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>$B$BNo.  We will not allow this to happen!', `VerifiedBuild` = 12340 WHERE `ID` = 9520;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for delivering this report, $C. From what Sentinel Luciel writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.$B$BWe can\'t afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I\'m certain we could triumph. Will you join our fight?', `VerifiedBuild` = 12340 WHERE `ID` = 9521;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Never again will the Burning Legion threaten us here! You have delivered us from a fight we very likely would have lost, $C.$B$BI give you thanks and the deepest gratitude of the Hand of Argus. It honors me to have you at our side.', `VerifiedBuild` = 12340 WHERE `ID` = 9522;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can\'t believe it!  It was the gnome all along...  I should have known!', `VerifiedBuild` = 12340 WHERE `ID` = 9531;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s good to see another new arrival here at Forest Song.$B$BVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.$B$BTake a look around, $C. It may not be much now, but with time and help from our night elf allies, we\'ll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.', `VerifiedBuild` = 12340 WHERE `ID` = 9533;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s better! There\'s nothing quite like ridding our world of a demon. And they make for worthy opponents as well, unlike the weak races of the Alliance.', `VerifiedBuild` = 12340 WHERE `ID` = 9534;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Dreadlords!  They plan to attack us here at Splintertree Post?!$B$BNot while I still draw breath!$B$B<Valusha crumples the demon-scrawled plans in her fist.>$B$BNo.  We will not allow this to happen!  They are a blight upon our world!', `VerifiedBuild` = 12340 WHERE `ID` = 9535;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!$B$BBravely fought, $C! You have the true heart of the Horde beating inside of you! You give us much honor!', `VerifiedBuild` = 12340 WHERE `ID` = 9536;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Do not distress the bewilderment shown by those you have helped. It is common for those recently brought back to the world of the living to experience disorientation, but imagine the shock of meeting with a strange being at the same time.$B$BThe young shaman is blessed to have survived such a harsh lesson thanks to you, and it is befitting you be allowed to call upon this power as you see fit.', `VerifiedBuild` = 12340 WHERE `ID` = 9600;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ahh... it seems it is time.$B$B<Mehlar nods knowingly.>', `VerifiedBuild` = 12340 WHERE `ID` = 9601;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'What? A draenei sent you here from the Harborage? How odd.$B$BWell, I\'m not one to turn down assistance. Thanks for coming, $C!', `VerifiedBuild` = 12340 WHERE `ID` = 9609;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 6, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I thank you, $C.  The study of these artifacts should keep me occupied for some time.  How else are we Broken and draenei to fit in if we do not come to understand the history of your world?', `VerifiedBuild` = 12340 WHERE `ID` = 9610;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area.', `VerifiedBuild` = 12340 WHERE `ID` = 9664;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'This is good news, $N. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.$B$BUntil that day, I hope that we will have your continued assistance.', `VerifiedBuild` = 12340 WHERE `ID` = 9665;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These will do quite nicely. Allow me a moment to mix up the potion.', `VerifiedBuild` = 12340 WHERE `ID` = 9801;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'They refused? They are welcome to choose their own path, of course, but their choice surprises me. I would think that all the draenei, including the Broken and Lost Ones, would still remember that we\'re all a part of the same people.$B$BI suppose he is right about the folly of deceiving them, but still, could he not see that our intentions were friendly?', `VerifiedBuild` = 12340 WHERE `ID` = 9803;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'At last! You have our thanks for your help in securing our position at the Orebor Harborage. I will send word of your deeds to the Kurenai city of Telaar in Nagrand. There will be many more opportunities for our peoples to work together.', `VerifiedBuild` = 12340 WHERE `ID` = 9839;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 6, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I\'m glad that Stonebreaker Hold sent you. The druids of the thicket have been slain! Only myself and one other have survived. and he\'s insane.$B$BI don\'t know what happened, but I intend to get to the bottom of it. Whatever it was, it happened quickly and feels unnatural.$B$BWill you help me?', `VerifiedBuild` = 12340 WHERE `ID` = 9961;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $N. We have enough to worry about without wondering when the arakkoa will accost our merchants and messengers again.', `VerifiedBuild` = 12340 WHERE `ID` = 9986;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ethereals?  Goods delivered to Tuurem?  Exotic engineering parts?  And a blood elf getting ready to deliver this last box to Firewing Point?$B$BWhat does all of this mean?!  How does it relate to what happened to the druids in the Cenarion Thicket?$B$BI think we should have a look inside that box.', `VerifiedBuild` = 12340 WHERE `ID` = 9990;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you for bringing these seeds. I\'ve almost got enough to send back the first batch!', `VerifiedBuild` = 12340 WHERE `ID` = 9992;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh no! That\'s horrible news! I can\'t believe that all but two of our Cenarion friends are dead.$B$BAlright, let me have a look at those parts. I\'m just hoping they aren\'t what I suspect that they might be.$B$BYes, as I feared, I believe these are bomb parts. Our eyes and ears in Shattrath City have been feeding us information about some of the ethereals importing proscribed goods from other dimensions that they\'re in contact with.', `VerifiedBuild` = 12340 WHERE `ID` = 9994;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh no!  That\'s horrible news!  I can\'t believe that all but two of our Cenarion friends are dead.$B$BAlright, let me have a look at those parts.  I\'m just hoping they aren\'t what I suspect that they might be.', `VerifiedBuild` = 12340 WHERE `ID` = 9995;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s a good start, but based on what you witnessed there in the courtyard, as well as intelligence that I\'ve received, we have a far more pressing matter at hand!', `VerifiedBuild` = 12340 WHERE `ID` = 9996;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<The high elf nods.>$B$BIt\'s a good start, but Bertelm was right to send you to me. I\'ve made a discovery that may help explain the fel orc presence here.', `VerifiedBuild` = 12340 WHERE `ID` = 9998;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Theloria nods at you.>$B$BWell done. We have bought ourselves a little time. The blood elves will grow curious about what happened to their friend. Hopefully, by that time, we will have a better understanding of their intentions.', `VerifiedBuild` = 12340 WHERE `ID` = 10002;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A bomb utilizing pure mana that can take out whole towns! But why? Why would the blood elves create such a thing and use it on us? The Cenarion Thicket was a place of peace and repose.$B$BWhatever the reason, it must be locked inside the head of Warden Treelos, and I have no idea how to cure him. Perhaps his mind will heal in time?$B$BRegardless, I want to thank you for helping me to figure out what happened. I can only hope that this tragedy will never befall anyone else ever again!', `VerifiedBuild` = 12340 WHERE `ID` = 10005;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Things are starting to look up. I think if we can prevent the fel orcs from reinforcing their fellows here, we can keep this post under control.', `VerifiedBuild` = 12340 WHERE `ID` = 10007;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Bertelm takes the plans from you and looks them over.>$B$BIf you hadn\'t brought this map, I\'d say you were out of your mind, but here it is, plain as day. Not only are the fel orcs here to serve the blood elves, but it appears, they\'ve been ordered to keep us occupied.$B$BThis map raises more questions than it answers, but it gives us a better idea of what we\'re facing here.', `VerifiedBuild` = 12340 WHERE `ID` = 10012;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, well done, friend. These are finer than I thought they\'d be. They\'ll make a fine cloak.$B$B<Bertelm glances toward the inn.>$B$BYes, a fine cloak it shall be.', `VerifiedBuild` = 12340 WHERE `ID` = 10016;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I bow to your skills, $N. You have proven yourself the superior hunter.$B$BI won\'t forget your help in making this cloak. It will truly be a one-of-a-kind piece and I\'ll wear it proudly.', `VerifiedBuild` = 12340 WHERE `ID` = 10022;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Andarl dabs at his forehead with the sleeve of his robe.>$B$BThank goodness. I was beginning to wonder if the things had displaced the rest of the forest\'s creatures.', `VerifiedBuild` = 12340 WHERE `ID` = 10026;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I hope these aren\'t the only intact vessels in the city. This is a good start, but I suspect we\'ll need many more than this.', `VerifiedBuild` = 12340 WHERE `ID` = 10028;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Great, just what I needed... more bones.$B$B<Ramdor sighs.>$B$BYes, yes, I will see to it that these remains of our honored ancestors are given a proper burial, have no fear.$B$BThere is something else that you can do if you\'re truly interested in aiding the dead.', `VerifiedBuild` = 12340 WHERE `ID` = 10030;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Yeah, I\'m sure that you killed all of those bonelashers. It\'s obvious since the captain asked for you to turn in proof on that wanted poster.$B$B<Taela gives you a sarcastic look.>$B$BI\'ll take your word for it. I\'m not certain who I angered to pull this duty, but thanks for your efforts on behalf of the Alliance. Here\'s a little something for all of your trouble.', `VerifiedBuild` = 12340 WHERE `ID` = 10033;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Color me impressed, $C. Torgos was one of the toughest creatures I know of this side of Nagrand.$B$BWell, I suppose that\'s good enough for something from the Allerian Stronghold treasury. Take your pick.', `VerifiedBuild` = 12340 WHERE `ID` = 10035;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thanks! I can\'t remember the last time I had eel!$B$BHow should I cook \'em?', `VerifiedBuild` = 12340 WHERE `ID` = 10037;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s about time someone came out here. I sent that report to the Allerian Stronghold over a week ago!$B$BBureaucracy!', `VerifiedBuild` = 12340 WHERE `ID` = 10038;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good, you finally made it back! Okay, what did you figure out? Who are they?', `VerifiedBuild` = 12340 WHERE `ID` = 10040;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That\'s dire news indeed! Well, it would seem I made the right choice in sending you out there to help Weeks. The last thing that we want is the Shadow Council establishing themselves right on our doorstep!$B$B$N, in recognition of your efforts at Grangol\'var Village, I hereby grant you the right to your pick of any of these fine rewards.', `VerifiedBuild` = 12340 WHERE `ID` = 10042;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 2, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Isla Starmane just left, but she gave me a full rundown on what\'s going on out at Firewing Point. It\'s understandable that she\'s quite distraught over what happened to the Cenarion Thicket. Nasty blood elves!$B$BShe told me how you were instrumental in saving her so that we could get that information. Allerian Stronghold is indebted to you for your service.$B$BPlease, accept this gift on behalf of us all.', `VerifiedBuild` = 12340 WHERE `ID` = 10051;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Isla Starmane just left, but she gave me a full rundown on what\'s going on out at Firewing Point. It\'s understandable that she\'s quite distraught over what happened to the Cenarion Thicket.$B$BShe told me how you were instrumental in saving her so that we could get that information. Stonebreaker Hold is indebted to you for your service.$B$BPlease, accept this gift on behalf of us all.', `VerifiedBuild` = 12340 WHERE `ID` = 10052;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well done, $n. You are quickly becoming one of my best students and I look forward to continuing your training in the future.', `VerifiedBuild` = 20886 WHERE `ID` = 10073;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It\'s about time that you arrived.$B$BMehlisah said that she would be sending help days ago. And we\'ve been fighting in here longer than that!', `VerifiedBuild` = 12340 WHERE `ID` = 10177;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I should\'ve suspected he would send you after me. He tried to talk me out of returning to the Sethekk Halls, but I couldn\'t live with myself if I allowed Lakka to die in there.', `VerifiedBuild` = 12340 WHERE `ID` = 10180;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You must be the one that zapped all of that sapping equipment back to us here from the ruins! Hooray for you!$B$BI\'ve already reallocated the equipment out to our other locations. Now we\'ll be able to expedite our fissure operations on this whole island by an order of magnitude! The nether-rocket will be completed in no time!$B$BHmmm, that\'s odd. Wait a minute, did you say that you sent four things back to us? I only got three...', `VerifiedBuild` = 12340 WHERE `ID` = 10203;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well, that\'s good and bad news, now isn\'t it? We\'ve dealt them a blow, but with the Burning Legion running free all over the Netherstorm - and getting closer to us here - well, I don\'t know how it\'s going to go.$B$BI have a feeling that we\'re going to have to change gears here for a while. Hope you\'ll be able to help us out, $N.', `VerifiedBuild` = 12340 WHERE `ID` = 10232;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well, my boy that certainly was exciting! And for my money, I\'d say that the Scrap Reaver X6000 performed admirably, despite its rookie pilot.$B$BHehe, no, don\'t take offense, I was just kidding.  After all, you just saved Area 52 and the X-52 Nether-Rocket from certain doom!', `VerifiedBuild` = 12340 WHERE `ID` = 10248;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'That is most excellent news, my friend!$B$BYou and Drijya have done us a great service.  With that warp-gate out of commission, the nearby demons will not be getting any further reinforcements.$B$BPlease allow me to reward you in the proper manner of the Consortium.', `VerifiedBuild` = 12340 WHERE `ID` = 10310;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'re not just pulling my bandage, right? That\'s most excellent news!$B$BNow that you\'ve done the surveying grunt-work, I\'ll be able to take my team up to the ruins and see what\'s there to be procured.$B$BYou have my thanks, $c.', `VerifiedBuild` = 12340 WHERE `ID` = 10335;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wonderful! We thank you for your generous donation, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 10352;

