UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 25, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Hah! So you heard of my challenge, did you?$B$BWell sit down and listen. Have a drink, and savor it... because it might be your last.', `VerifiedBuild` = 12340 WHERE `ID` = 10371;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, especially with the looming threat of the Scourge to our north and northeast. I am glad to hear that the clarion call of duty and service to the greater good did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.', `VerifiedBuild` = 12340 WHERE `ID` = 10373;

UPDATE `quest_offer_reward` SET `Emote1` = 66, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Welcome to the Plaguelands, hero. This is one of the most dangerous frontiers in Azeroth, with the looming threat of the Scourge to our east, and then even further still eastward from there. I am glad to hear that the call of duty and service to the Horde did not fall on deaf ears with you!$B$BIf you are ready to get your hands dirty, then there is plenty for willing and able heroes to do here on the edge of the Plaguelands.', `VerifiedBuild` = 12340 WHERE `ID` = 10374;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Bomb parts. So my suspicions were true. That\'s not something that I wanted to be right about.$B$BOkay, you and I have some grim business ahead of us then.', `VerifiedBuild` = 12340 WHERE `ID` = 10444;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'YOU DID IT! YOU SAVED US! YOU SAVED THE ALLERIAN STRONGHOLD!!$B$BWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.$B$B$N, I\'ve never seen such selflessness... such heroism! Please, accept this on behalf of all of us.', `VerifiedBuild` = 12340 WHERE `ID` = 10446;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Excellent! Let\'s perform the trade then. It\'s hard to part with this excellent armor, but I\'m afraid I won\'t be needing it any time soon.$B$BIf you\'re interested in performing more work for me, I might be willing to give up the rest of the pieces.', `VerifiedBuild` = 12340 WHERE `ID` = 10492;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Ah, yes. Mux will be quite happy with this.$B$BThose bracers were part of a larger armor set. If you\'re interested in providing me with further assistance, I\'d be willing to consider parting with the rest of it.', `VerifiedBuild` = 12340 WHERE `ID` = 10493;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You\'ve kept your end of the bargain, I shall keep mine.$B$BJust remember that I\'m holding on to the best pieces until your work is finished.', `VerifiedBuild` = 12340 WHERE `ID` = 10494;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Our agreement remains in place. Just remember, this is but a taste of what awaits you. Free me of this cursed fate and I will reward you with items of truly great power.', `VerifiedBuild` = 12340 WHERE `ID` = 10495;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well now, $C... since you were informed that I was leading this research myself, you obviously came as quickly as you could.$B$BNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.', `VerifiedBuild` = 12340 WHERE `ID` = 10520;

UPDATE `quest_offer_reward` SET `Emote1` = 21, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Very good, $N. Perhaps you have a taste for revenge after all.', `VerifiedBuild` = 12340 WHERE `ID` = 10590;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These stones carry a taint I do not wish to remember, but one I cannot forget. You try my patience dangerously by bringing these to me.$B$BHowever, it is clear your heart seeks the same vengeance as I, and I will aid you with instruction.', `VerifiedBuild` = 12340 WHERE `ID` = 10592;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 2000, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The Banshee Queen has guided you well. This is precisely what I need to combine the fragments.$B$B<Mehlar watches as the vine interweaves through the fragments, binding them together.>$B$BThere!  Scourgebane, I shall call it. Be wary when you use it, for it serves you against its will.', `VerifiedBuild` = 12340 WHERE `ID` = 10593;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your world is about to change, $N.$B$B<Hildagard begins crafting something out of the ash.>', `VerifiedBuild` = 12340 WHERE `ID` = 10624;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Gorefiend? T... Teron Gorefiend? But... How?$b$bHow could Gorefiend be here? This is impossible!$b$bThe legend of Teron Gorefiend is one that causes even the Forsaken to tremble in fear. By all accounts, Gorefiend was a warlock of Gul\'dan - extremely powerful in his own right. When Gorefiend was slain by Orgrim Doomhammer, Gul\'dan took the soul of the fallen warlock and placed it inside the broken shell of a slain knight of Stormwind. And so was born the first death knight of the Horde.', `VerifiedBuild` = 12340 WHERE `ID` = 10625;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Baron Sablemane peers inside the gronn\'s sack and seems satisfied.>$B$BVery well, you have upheld your end of the bargain. With that price paid, I will give Rexxar what he seeks.', `VerifiedBuild` = 12340 WHERE `ID` = 10721;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So Thundris Windweaver still thinks I need looking after? I\'ll need to remind him who saved whom; he seems to forget it was I that pulled him from harm\'s way.$B$BWell now that you\'re here, $R, perhaps I can find something for you to do.', `VerifiedBuild` = 12340 WHERE `ID` = 10752;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I heard the explosion from here. Not with my ears, but with my heart.$B$BIf the touch of the blessed Naaru, A\'dal, is not enough to bring the arakkoa to redemption, nothing will be. Those who have not given themselves over to the Light are mere servants of evil.$B$BThey must be destroyed.', `VerifiedBuild` = 12340 WHERE `ID` = 10839;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.$B$BBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk\'s gaze fixates on the south.$B$BThese Eyes are all seeing.', `VerifiedBuild` = 12340 WHERE `ID` = 10847;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Those foul spirits deserved to die. The death they would have wrought on others is reason enough.$B$BWe cannot hope to redeem those in Terokk\'s grasp. But we shall deliver them a devastating blow in the name of the Light.', `VerifiedBuild` = 12340 WHERE `ID` = 10848;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Rilak\'s tale is grim, traveler. As you can see from the state of the caravan, there is much sorrow and darkness in the forest of Terokk these days.', `VerifiedBuild` = 12340 WHERE `ID` = 10849;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is grim work toiling with someone\'s hatchlings, yet ignoring the brewing evil would be a bleak proposition as well. You have done well. A\'dal\'s favor shines upon your heart.', `VerifiedBuild` = 12340 WHERE `ID` = 10861;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You saved so many.  I didn\'t think we would ever see them again.  We cannot thank you enough, $N.  ', `VerifiedBuild` = 12340 WHERE `ID` = 10873;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'We witnessed the cursed smoke rise from here. You are most brave, $c.', `VerifiedBuild` = 12340 WHERE `ID` = 10874;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It is good to hear of all your moves against the fel orcs, $N.  The apothecaries have spent much time and resources studying the cause of their corruption, and although such information is invaluable... my orc blood burns to strike a severe blow against these betrayers!$b$bListen close, and I will explain my task...', `VerifiedBuild` = 12340 WHERE `ID` = 10875;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I can breathe a sigh of relief for now, $N.  The Shadow Council will be held off for the time being.$b$bThey are murderers and cowards and your display of courage will keep them at bay.', `VerifiedBuild` = 12340 WHERE `ID` = 10878;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I applaud your prowess in combat, $C. You have proven yourself to be a true defender of the Light. May A\'dal\'s blessing shine upon your darkest hours.$B$BBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us.', `VerifiedBuild` = 12340 WHERE `ID` = 10879;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The guardians of Skettis grow restless from their perch. Shattrath is in trouble. We will surely feel the brunt of Terokk\'s revenge.$B$BMuster a defense party quickly! Speak with Defender Grashna and let him know you are ready to bear arms against our attackers!', `VerifiedBuild` = 12340 WHERE `ID` = 10889;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Of course I\'ll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!', `VerifiedBuild` = 12340 WHERE `ID` = 10891;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Of course I\'ll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!', `VerifiedBuild` = 12340 WHERE `ID` = 10892;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Victory is ours! This defeat will set the Auchenai back several weeks.', `VerifiedBuild` = 12340 WHERE `ID` = 10915;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 66, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I heard the sounds of your battle from here, $C. The sounds of your victory filled my heart with hope. If you can win against such terrible odds, perhaps I can find the strength to drag my companions from this terrible place.', `VerifiedBuild` = 12340 WHERE `ID` = 10920;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'A bone wurm! Fantastic! This may actually be the first time in recorded history that Letoll has actually made a discovery.', `VerifiedBuild` = 12340 WHERE `ID` = 10922;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 5, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Sand gnomes? Yea, sure... The desert can do strange things to a person.$B$BI think we\'re about to make a breakthrough here with these worms!', `VerifiedBuild` = 12340 WHERE `ID` = 10929;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Amazing! Look at this stuff! The thing-a-ma-whatever has some sort of dust inside its whatcha-ma-bobber. Bah! I won\'t bore you with all this scientific jargon. I did manage to pull a few teeth from the little ones to make these incredibly sharp knives. Want one?', `VerifiedBuild` = 12340 WHERE `ID` = 10930;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You help Grok?  Grok need help!  Bloodmaul clan need help!', `VerifiedBuild` = 12340 WHERE `ID` = 10984;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = NULL, `VerifiedBuild` = 12340 WHERE `ID` = 11052;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Calia chuckles as you describe the guards\' reactions to the propaganda.>$B$BJust as I\'d hoped! I think it\'s safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!', `VerifiedBuild` = 12340 WHERE `ID` = 11133;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Gavis\' request isn\'t as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.$B$BIt\'s been a pleasure working with you, $N. Without your help, I doubt the operation would\'ve gone so smoothly. When I make my report in Stormwind, it will name you as the $C who ended the deserter threat.', `VerifiedBuild` = 12340 WHERE `ID` = 11134;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Captain Wymor accepts the orders from you and reads over them.>$B$BWhat in the world could \'precious cargo\' refer to? The Defias have done some small time smuggling back in lands of Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.', `VerifiedBuild` = 12340 WHERE `ID` = 11137;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Renn looks over the orders.>$B$BSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we\'re going to need some of their gear if you\'re to help me find the cargo.', `VerifiedBuild` = 12340 WHERE `ID` = 11138;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Wow, this is in worse shape than I\'d thought, and these tools...$B$BWell, I said I\'d get this back into working condition for you, so I\'d better get to work.', `VerifiedBuild` = 12340 WHERE `ID` = 11139;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn\'t have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we\'re always glad to have the extra help.', `VerifiedBuild` = 12340 WHERE `ID` = 11143;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Captain Darill glances at the battle plan.>$B$BI\'d say it doesn\'t get any clearer than this. They\'ve taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list.', `VerifiedBuild` = 12340 WHERE `ID` = 11144;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.$B$BYou have my thanks and that of the men. ', `VerifiedBuild` = 12340 WHERE `ID` = 11145;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Captain Darill inspects the armaments you\'ve brought from Blackhoof Village.>$B$BThere\'s no doubt about it. These match the description exactly, but there\'s just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.', `VerifiedBuild` = 12340 WHERE `ID` = 11148;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<The captain listens to your report intently.>$B$BWe have avenged James and his family, but not even that can restore what was destroyed.', `VerifiedBuild` = 12340 WHERE `ID` = 11151;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>$B$BIt\'s good to know that they understand. You didn\'t tell them about James, did you?$B$BI\'ll deliver his wife\'s message to him, but I doubt he\'ll understand.', `VerifiedBuild` = 12340 WHERE `ID` = 11152;

UPDATE `quest_offer_reward` SET `Emote1` = 273, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Apprentice Morlann nods.>$B$BGood. Can\'t say I\'ll miss the company, if you can call it that. You\'d think at least in the middle of the swamp you\'d get some privacy, you know?', `VerifiedBuild` = 12340 WHERE `ID` = 11156;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'You have Brogg\'s thanks, $N. Brogg has big plans for clan banner.', `VerifiedBuild` = 12340 WHERE `ID` = 11160;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1500, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<The apprentice listens as you describe your experiment.>$B$BA haze and some lightning? That\'s it? There\'s got to be more to the totem than just that! The Grimtotems aren\'t likely to bring something like this to the battlefield unless it has some kind of utility.', `VerifiedBuild` = 12340 WHERE `ID` = 11169;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So those hermit mages sent you? How can I be sure that I can trust you?$B$BI suppose I can use the help. There\'s not much here a mage would be interested in, anyway.', `VerifiedBuild` = 12340 WHERE `ID` = 11172;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Apprentice Garion inspects the venom.>$B$BThis is absolutely perfect! He\'ll never know the difference.', `VerifiedBuild` = 12340 WHERE `ID` = 11173;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>$B$BFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.$B$BSomething has been corrupting and killing them. Those who follow don\'t learn the truth until it\'s too late. We have to put an end to this, $N!', `VerifiedBuild` = 12340 WHERE `ID` = 11180;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 5, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'It worked?$B$B<Mordant clears his throat.>$B$BI mean... it worked! Jarl and I are in your debt, $N. Now the only remaining problem is my friend\'s taste in furniture, and I\'m afraid that won\'t be solved as easily.', `VerifiedBuild` = 12340 WHERE `ID` = 11183;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1500, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Andello reads the letter, shocked at its contents.>$B$BWe\'ve long had misgivings about the cooperation between the Horde and the Forsaken, and this only confirms those suspicions. With the backing for Forsaken magic and arms, the Grimtotems would become an even more fearsome enemy. The balance of power in Kalimdor could shift considerably.', `VerifiedBuild` = 12340 WHERE `ID` = 11185;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = NULL, `VerifiedBuild` = 12340 WHERE `ID` = 11196;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Krog inspects the weapons and armor you\'ve brought from Blackhoof Village.>$B$BThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.', `VerifiedBuild` = 12340 WHERE `ID` = 11200;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 1500, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Krog reads over the battle plan.>$B$BThere\'s no doubt in my mind that the Grimtotems are moving against the humans. What I don\'t understand is what their intentions are toward us. The actions of the Grimtotems have caused tension within the Horde in the past, but the Warchief has always diffused it.', `VerifiedBuild` = 12340 WHERE `ID` = 11201;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Tabetha smiles slightly.>$B$BKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.$B$BIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.', `VerifiedBuild` = 12340 WHERE `ID` = 11203;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.', `VerifiedBuild` = 12340 WHERE `ID` = 11204;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 1, `Emote3` = 66, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Krog listens to your report.>$B$BI\'m impressed, $N. I would\'ve thought that the Grimtotem criminals would\'ve been more difficult to locate. $B$BTabetha\'s warnings have not fallen on deaf ears, but it is not my place to chastise the Grimtotems. I will, of course, mention it in my report to the Warchief. Do not speak of it to anyone until Thrall has dealt with the Grimtotems. You have done well in solving the mystery of the Shady Rest and sparing us from the suspicion of Theramore. ', `VerifiedBuild` = 12340 WHERE `ID` = 11206;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 2000, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<You recount your experiences with Nat Pagle, carefully omitting the portion about the \'bait test.\'>$B$BWell, it sounds like we\'ve got our work cut out for us. I\'ll make the preparations.', `VerifiedBuild` = 12340 WHERE `ID` = 11210;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.', `VerifiedBuild` = 12340 WHERE `ID` = 11217;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Will you lay the candle down and call the Headless Horseman from his doomed rest?', `VerifiedBuild` = 12340 WHERE `ID` = 11405;

UPDATE `quest_offer_reward` SET `Emote1` = 1, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = NULL, `VerifiedBuild` = 12340 WHERE `ID` = 11528;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Aw, so you must be the so-called King Mrgl-Mrgl\'s lackey. I suppose that night elf has sent you to appease me?$b$bGood, I have just the thing that needs doing for someone as powerful as you!', `VerifiedBuild` = 12340 WHERE `ID` = 11562;

UPDATE `quest_offer_reward` SET `Emote1` = 5, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'WHAT?!$B$B<The image before you distorts for a moment as the archmage attempts to regain her composure.>$B$BOf course, we should have guessed that this was what they were up to all along. Quickly, there\'s no time to waste.$B$BWyrmrest must be warned!', `VerifiedBuild` = 12340 WHERE `ID` = 12107;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'WHAT?!$B$B<The image before you distorts for a moment as the archmage attempts to regain her composure.>$B$BOf course, we should have guessed that this was what they were up to all along. Quickly, there\'s no time to waste.$B$BWyrmrest must be warned!', `VerifiedBuild` = 12340 WHERE `ID` = 12110;

UPDATE `quest_offer_reward` SET `Emote1` = 2, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Oh, thank you! May the Light bless your good works, kind $Gsir:lady;. The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.', `VerifiedBuild` = 12340 WHERE `ID` = 12135;

UPDATE `quest_offer_reward` SET `Emote1` = 4, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'The fires are out! You and your fire brigade were victorious! Hah!$B$BThe Headless Horseman\'s attack has failed, but until he and his head are destroyed together, he will return.$B$BUntil then, however, let\'s take comfort in the safety you brought our children. I am honored to have watched your brave work today.', `VerifiedBuild` = 12340 WHERE `ID` = 12139;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Your paperwork looks to be in order. Welcome to the club, $N!$B$BYou can expect to get our mail at the start of every month. If you like what you got, stop by and we can sell you some more. This is the club that keeps on giving.', `VerifiedBuild` = 12340 WHERE `ID` = 12420;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.$b$bThis is the break that we\'ve been waiting for to strike at the Aspect of Magic!$b$b<The queen of dragons studies you for a brief moment.>$b$bYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.$b$bIt will be enough to draw Malygos\'s ire!', `VerifiedBuild` = 12340 WHERE `ID` = 13372;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.$b$bThis is the break that we\'ve been waiting for to strike at the Aspect of Magic!$b$b<The queen of dragons studies you for a brief moment.>$b$bYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.$b$bIt will be enough to draw Malygos\'s ire!', `VerifiedBuild` = 12340 WHERE `ID` = 13375;

