UPDATE `quest_offer_reward` SET `Emote1` = 11, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = '<Nathanos laughs.>$B$BExcellent! Finally! An opportunity to destroy the Scarlet Oracle!', `VerifiedBuild` = 12340 WHERE `ID` = 14350;

UPDATE `quest_offer_reward` SET `Emote1` = 6, `Emote2` = 1, `Emote3` = 1, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'So you\'re the $c who tore through the Alliance forces in the Hillsbrad Foothills? I\'ve heard your name already. Word travels fast.$B$BThe Horde can use someone like you if you keep this up, $N.$B$BWe need to keep our eyes on all threats around us, but with that king leading them, the humans will continue to be a problem. You\'ve confirmed that there\'s strength enough in the Horde to end that threat in time.', `VerifiedBuild` = 12340 WHERE `ID` = 14351;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'I\'ve seen the insignia on this scroll before during my time in Northrend. You say this was on that crone who leads the pigs in Razorfen Kraul?$b$bI\'ll be damned if I\'m going to let the Scourge get a foothold here. The one who wrote this - this Malcin - is one of the Lich King\'s servants, obviously, and that makes him a target. Your target.$b$bThey\'re not going to take Kalimdor.$b$b', `VerifiedBuild` = 12340 WHERE `ID` = 14352;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good, $C. You\'ve done well. I\'ll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.$B$BCheck back with me in the future; there\'s always something that needs doing around here, apparently, and I might need another able body.', `VerifiedBuild` = 12340 WHERE `ID` = 14356;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Good. $n, I know of you. You\'ll be perfect for these tasks.$B$BWe\'ve been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we\'re to avoid Arthas\' notice.', `VerifiedBuild` = 12340 WHERE `ID` = 24506;

UPDATE `quest_offer_reward` SET `Emote1` = 0, `Emote2` = 0, `Emote3` = 0, `Emote4` = 0, `EmoteDelay1` = 0, `EmoteDelay2` = 0, `EmoteDelay3` = 0, `EmoteDelay4` = 0, `RewardText` = 'Well timed, $c!$B$BThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... and a route to vengeance long overdue.', `VerifiedBuild` = 12340 WHERE `ID` = 24511;

