INSERT INTO `quest_request_items_locale`(`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES (10004, 'deDE', '<Sal\'salabim kratzt sich am Kopf.>$B$B[Dämonisch] Ik il romath sardon.', 26972);

